window.BOOKS = [{"id":"como-defender-la-fe-sin-levantar-la-voz","shelf":1,"theme":"Fe y espiritualidad","title":"Cómo defender la fe sin levantar la voz","author":"Austen Ivereigh y Yago de la Cierva","sortKey":"Ivereigh","summary":"Nacido de la experiencia de Catholic Voices, un grupo de laicos que se preparó para explicar la fe en los medios durante la visita de Benedicto XVI al Reino Unido, este manual enseña a abordar con serenidad los temas más espinosos: el aborto, la sexualidad, la libertad religiosa, los abusos o el papel de la mujer en la Iglesia. Su clave es descubrir la intención positiva que late tras cada crítica y responder con argumentos, empatía y buen humor, sin ponerse a la defensiva. Una herramienta muy práctica para cualquier católico que quiera dar razón de su esperanza en conversaciones cotidianas o en público, con caridad y sin crispación.","authorBio":"Austen Ivereigh es un periodista y biógrafo británico, autor de una conocida biografía del papa Francisco y cofundador de Catholic Voices; Yago de la Cierva es profesor de comunicación institucional y gestión de crisis, y fue director de comunicación de la JMJ de Madrid 2011.","year":2012,"originalTitle":"How to Defend the Faith Without Raising Your Voice","language":"inglés","pages":250,"tags":["apologética","comunicación","iglesia católica","debate público","fe","medios de comunicación"],"cover":"covers/como-defender-la-fe-sin-levantar-la-voz.jpg","ratio":1.645,"color":"#132c53"},{"id":"descubre-el-lider-que-hay-en-ti","shelf":2,"theme":"Liderazgo y empresa","title":"Descubre el líder que hay en ti","author":"Virginia Prieto Menéndez","sortKey":"Prieto","summary":"Con un estilo ameno y didáctico, la autora tiende un puente entre dos territorios que rara vez se tratan juntos: el liderazgo y la felicidad. Su tesis es que ambos comparten una misma raíz, el conocimiento de uno mismo, y que nadie puede guiar a otros si antes no ha aprendido a gobernar su propia vida. A través de reflexiones, ejemplos y ejercicios inspirados en el coaching, el libro invita al lector a revisar sus creencias, sus emociones y sus metas para dar un giro consciente a su manera de vivir y de trabajar. Una lectura breve y estimulante para quien busca crecer por dentro.","authorBio":"Virginia Prieto Menéndez es una psicóloga ovetense, formada en la Universidad Autónoma de Madrid, especializada en recursos humanos, PNL y coaching de consciencia.","year":2013,"language":"español","pages":154,"tags":["liderazgo","autoconocimiento","felicidad","coaching","desarrollo personal"],"cover":"covers/descubre-el-lider-que-hay-en-ti.jpg","ratio":1.558,"color":"#792b91"},{"id":"deviate","shelf":3,"theme":"Liderazgo y empresa","title":"Deviate","author":"Beau Lotto","sortKey":"Lotto","note":"Edición en inglés","summary":"El neurocientífico Beau Lotto parte de una idea desconcertante: no vemos la realidad, sino la interpretación que nuestro cerebro construye a partir de la experiencia pasada. Con ilusiones ópticas, experimentos y anécdotas, el libro muestra cómo la percepción está moldeada por supuestos que casi nunca cuestionamos, y propone aprender a «desviarse» de ellos para pensar de forma original. La incertidumbre, que solemos temer, se convierte aquí en la puerta de la creatividad y la innovación. Un ensayo vivo y visual, a medio camino entre la ciencia divulgativa y el manual de pensamiento creativo, que invita a mirar el mundo con ojos nuevos.","authorBio":"Beau Lotto es un neurocientífico estadounidense, profesor en el University College de Londres y fundador del Lab of Misfits, dedicado al estudio de la percepción.","year":2017,"language":"inglés","pages":350,"tags":["neurociencia","percepción","creatividad","innovación","pensamiento crítico"],"cover":"covers/deviate.jpg","ratio":1.094,"color":"#87d03b"},{"id":"infinito-una-mirada-creativa-y-humana-del-liderazgo","shelf":4,"theme":"Liderazgo y empresa","title":"Infinito. Una mirada creativa y humana del liderazgo","author":"Marcos Abollado Rego","sortKey":"Abollado","summary":"Desde la psicología y la experiencia en proyectos de cambio cultural, Marcos Abollado propone entender el liderazgo como algo profundamente humano y nunca terminado. El libro se organiza en torno a cuatro espacios —la libertad, la imperfección humana, la excelencia y la influencia— y los recorre combinando preguntas, historias inspiradoras y resultados de investigación. Una de sus originalidades es que incorpora recursos audiovisuales que acompañan la lectura y buscan una experiencia más sensorial. Es un ensayo cercano y creativo para quienes dirigen equipos, pero también para cualquiera que quiera influir de manera positiva en los demás a partir de su propia autenticidad.","authorBio":"Marcos Abollado Rego es licenciado en Psicopedagogía por la Universidad Pontificia Comillas y consultor especializado en cambio cultural y formación en liderazgo, comunicación y ventas.","year":2024,"language":"español","tags":["liderazgo","psicología","creatividad","cultura organizativa","humanismo"],"cover":"covers/infinito-una-mirada-creativa-y-humana-del-liderazgo.jpg","ratio":1.502,"color":"#16525c"},{"id":"etica-para-maquinas","shelf":5,"theme":"Liderazgo y empresa","title":"Ética para máquinas","author":"José Ignacio Latorre","sortKey":"Latorre","summary":"¿Puede una máquina tomar decisiones morales? ¿Quién responde cuando un algoritmo se equivoca? El físico José Ignacio Latorre recorre con claridad la historia de la inteligencia artificial, desde los primeros autómatas hasta el aprendizaje profundo, para plantear las grandes preguntas éticas que ya tenemos encima: coches autónomos, sesgos en los datos, armas inteligentes o el futuro del trabajo. Sin alarmismos ni ingenuidad, defiende que las máquinas reflejarán los valores de quienes las diseñan, y que por eso la ética no puede quedar en manos de unos pocos ingenieros. Un ensayo accesible y necesario para entender el mundo que llega.","authorBio":"José Ignacio Latorre es catedrático de Física Teórica en la Universidad de Barcelona y director del Centro de Tecnologías Cuánticas de Singapur, experto en computación cuántica.","year":2019,"language":"español","pages":272,"tags":["inteligencia artificial","ética","tecnología","algoritmos","futuro","ciencia"],"cover":"covers/etica-para-maquinas.jpg","ratio":1.506,"color":"#5ebad9"},{"id":"inspired","shelf":6,"theme":"Liderazgo y empresa","title":"Inspired","author":"Marty Cagan","sortKey":"Cagan","note":"Segunda edición, en inglés","summary":"Considerado una biblia de la gestión de producto tecnológico, este libro explica qué distingue a las empresas que crean productos que los clientes adoran de las que fracasan pese a sus recursos. Marty Cagan describe el papel del product manager, la importancia de equipos de producto autónomos y empoderados, y técnicas para descubrir rápidamente qué merece la pena construir antes de invertir en ello. La segunda edición, reescrita casi por completo, incorpora ejemplos de compañías como Google, Netflix o Amazon. Lectura imprescindible para quien trabaja en tecnología y quiere entender cómo se pasa de una idea a un producto valioso.","authorBio":"Marty Cagan es un ejecutivo de producto estadounidense que trabajó en HP, Netscape y eBay y fundó el Silicon Valley Product Group, referencia mundial en gestión de producto.","year":2008,"language":"inglés","pages":368,"tags":["gestión de producto","tecnología","innovación","equipos","startups"],"cover":"covers/inspired.jpg","ratio":1.511,"color":"#bdbdbd"},{"id":"educar-es-de-valientes","shelf":7,"theme":"Familia y crianza","title":"Educar es de valientes","author":"Julio de la Iglesia","sortKey":"Iglesia","note":"Título por confirmar","summary":"Libro firmado por Julio de la Iglesia, coach y conferenciante conocido por su trabajo sobre la gestión del miedo y la valentía. Como sugiere su título, plantea la educación de los hijos como una tarea que exige coraje: poner límites, acompañar los miedos propios y los de los niños, y ayudarles a crecer con confianza para afrontar la vida. No hemos podido verificar con certeza los datos bibliográficos de esta obra, por lo que conviene contrastar el título con el ejemplar; en cualquier caso, ocupa un lugar natural en la sección de familia y crianza como lectura de ánimo para padres.","authorBio":"Julio de la Iglesia es un antiguo TEDAX y guardia civil reconvertido en coach y conferenciante, autor de «El miedo es de valientes» (2022).","language":"español","tags":["educación","paternidad","valentía","crianza","miedo"],"ratio":1.5,"color":"#ac8b72"},{"id":"guia-practica-para-tener-bebes-tranquilos-y-felices","shelf":8,"theme":"Familia y crianza","title":"Guía práctica para tener bebés tranquilos y felices","author":"Tracy Hogg y Melinda Blau","sortKey":"Hogg","summary":"Tracy Hogg, la célebre «encantadora de bebés», responde aquí a las dudas concretas que más angustian a los padres primerizos: el sueño, la alimentación, el llanto o la dificultad para establecer rutinas. Su método consiste en aprender a hacerse las preguntas adecuadas para descubrir qué le ocurre realmente al niño y actuar con calma y coherencia, siempre respetando su temperamento. Propone además una rutina diaria flexible y consejos para no caer en los errores más habituales. Escrito con sentido común y mucho humor, es un manual de consulta muy útil durante los primeros años, cuando cualquier pequeña mejora en casa se agradece enormemente.","authorBio":"Tracy Hogg (1960-2004) fue una enfermera y asesora de crianza británica, conocida como «la encantadora de bebés»; Melinda Blau es una periodista estadounidense especializada en familia.","year":2005,"originalTitle":"The Baby Whisperer Solves All Your Problems","language":"inglés","pages":400,"tags":["bebés","crianza","sueño infantil","rutinas","paternidad","lactancia"],"cover":"covers/guia-practica-para-tener-bebes-tranquilos-y-felices.jpg","ratio":1.348,"color":"#5e352b"},{"id":"la-fase-cero-de-tu-futuro","shelf":9,"theme":"Liderazgo y empresa","title":"La fase cero de tu futuro","author":"Chechu Salas","sortKey":"Salas","summary":"«¿Qué quiero hacer con mi vida?» es una pregunta que paraliza a muchos jóvenes y no tan jóvenes. Chechu Salas sostiene que la incertidumbre ante el futuro es universal, pero que la mejor manera de afrontarla es construir ese futuro uno mismo. Para ello propone una «fase cero»: un trabajo previo de autoconocimiento, con ejercicios y preguntas prácticas que ayudan a identificar talentos, pasiones y valores antes de tomar decisiones de estudios o de carrera. Un libro breve, motivador y muy aplicable, pensado para orientar a quien está ante una encrucijada vital y quiere elegir con más libertad y menos ansiedad.","authorBio":"Chechu Salas es un formador y orientador español especializado en desarrollo del talento y orientación vocacional para jóvenes.","year":2018,"language":"español","pages":192,"tags":["orientación vocacional","jóvenes","autoconocimiento","propósito","desarrollo personal"],"cover":"covers/la-fase-cero-de-tu-futuro.jpg","ratio":1.241,"color":"#77c7cd"},{"id":"factfulness","shelf":10,"theme":"Historia y actualidad","title":"Factfulness","author":"Hans Rosling, Ola Rosling y Anna Rosling Rönnlund","sortKey":"Rosling","summary":"¿Está el mundo peor que nunca? Hans Rosling demuestra, con datos y con una pasión contagiosa, que la mayoría de nosotros tiene una imagen del planeta mucho más sombría de lo que la realidad justifica. El libro identifica diez instintos que distorsionan nuestra percepción —el miedo, la generalización, el dramatismo o la tendencia a dividir el mundo en dos— y enseña a corregirlos mirando los hechos. Pobreza, salud, educación o natalidad aparecen así bajo una luz nueva. Escrito con calidez y anécdotas personales, es una invitación a pensar con rigor y a mirar el mundo con una esperanza bien fundada.","authorBio":"Hans Rosling (1948-2017) fue un médico y profesor sueco de salud global, célebre por sus conferencias TED; escribió el libro junto a su hijo Ola y su nuera Anna, cofundadores de la Fundación Gapminder.","year":2018,"originalTitle":"Factfulness: Ten Reasons We're Wrong About the World","language":"inglés","pages":360,"tags":["datos","desarrollo","pensamiento crítico","salud global","optimismo","estadística"],"cover":"covers/factfulness.jpg","ratio":1.54,"color":"#d25941"},{"id":"reinventar-las-organizaciones","shelf":11,"theme":"Liderazgo y empresa","title":"Reinventar las organizaciones","author":"Frederic Laloux","sortKey":"Laloux","summary":"Frederic Laloux estudia la evolución de las organizaciones humanas a lo largo de la historia y describe un nuevo modelo emergente, al que llama «teal» u organizaciones evolutivas. A partir de casos reales de empresas, hospitales y escuelas, muestra tres rasgos comunes: la autogestión sin jerarquías rígidas, la posibilidad de que las personas lleven al trabajo su ser completo y la orientación hacia un propósito vivo. El libro combina análisis y ejemplos muy concretos de prácticas sobre decisiones, salarios o resolución de conflictos. Una lectura influyente para quien busca formas de trabajar más humanas y con sentido.","authorBio":"Frederic Laloux es un consultor y antiguo socio de McKinsey, de origen belga, dedicado a acompañar a líderes en la transformación de sus organizaciones.","year":2014,"originalTitle":"Reinventing Organizations","language":"inglés","pages":360,"tags":["organizaciones","autogestión","cultura empresarial","liderazgo","propósito"],"cover":"covers/reinventar-las-organizaciones.jpg","ratio":1.483,"color":"#49a09a"},{"id":"talk-like-ted","shelf":12,"theme":"Liderazgo y empresa","title":"Talk Like TED","author":"Carmine Gallo","sortKey":"Gallo","note":"Edición en inglés","summary":"Tras analizar cientos de charlas TED y entrevistar a sus ponentes más aplaudidos, Carmine Gallo destila nueve claves para hablar en público de forma memorable. Las agrupa en tres pilares: emocionar (contar historias y mostrar pasión auténtica), aportar novedad (enseñar algo nuevo, sorprender, usar el humor) y ser memorable (respetar la regla de los dieciocho minutos y apelar a varios sentidos). Cada principio se ilustra con ejemplos reales y apoyos de la neurociencia. Un libro práctico y ameno para cualquiera que tenga que presentar ideas, desde una reunión de trabajo hasta un gran auditorio.","authorBio":"Carmine Gallo es un periodista y coach de comunicación estadounidense, autor de varios best sellers sobre presentaciones y liderazgo.","year":2014,"language":"inglés","pages":288,"tags":["oratoria","comunicación","presentaciones","storytelling","hablar en público"],"cover":"covers/talk-like-ted.jpg","ratio":1.52,"color":"#bdbdbd"},{"id":"inventar-criar","shelf":13,"theme":"Liderazgo y empresa","title":"Inventar & Criar","author":"Jeff Bezos","sortKey":"Bezos","note":"Edición portuguesa de «Invent and Wander»","summary":"Recopilación de los textos más significativos de Jeff Bezos: sus cartas anuales a los accionistas de Amazon desde 1997, junto con discursos y entrevistas en los que habla de su trayectoria personal y de su manera de entender la empresa. Con introducción de Walter Isaacson, el libro deja ver los principios que guiaron el crecimiento de Amazon: la obsesión por el cliente, el pensamiento a largo plazo, la tolerancia al fracaso y la voluntad de seguir siendo siempre «el día uno». Es una ventana directa a la mente de uno de los empresarios más influyentes de nuestro tiempo, sin intermediarios. Esta es la edición portuguesa.","authorBio":"Jeff Bezos es un empresario estadounidense, fundador de Amazon y de la empresa aeroespacial Blue Origin.","year":2020,"originalTitle":"Invent and Wander: The Collected Writings of Jeff Bezos","language":"inglés","pages":300,"tags":["emprendimiento","amazon","estrategia","innovación","liderazgo"],"ratio":1.5,"color":"#6379b0"},{"id":"healthy-business","shelf":14,"theme":"Liderazgo y empresa","title":"Healthy Business","author":"Jean-Charles Samuelian-Werve","sortKey":"Samuelian-Werve","summary":"El cofundador de la aseguradora de salud Alan cuenta cómo construyó una empresa de crecimiento muy rápido sin renunciar al bienestar de quienes trabajan en ella. El libro expone una cultura poco convencional: transparencia radical, documentación escrita en lugar de reuniones, ausencia de mandos intermedios tradicionales, responsabilidad compartida y el error entendido como fuente de aprendizaje. Lejos de ser un manifiesto teórico, describe prácticas concretas que se pueden adaptar a otras organizaciones. Una lectura interesante para quien busca conciliar exigencia y salud en el trabajo, y especialmente cercana para quien conoce Alan desde dentro.","authorBio":"Jean-Charles Samuelian-Werve es un emprendedor francés, cofundador y consejero delegado de Alan, la empresa de seguros de salud fundada en 2016.","year":2020,"language":"francés","pages":226,"tags":["cultura empresarial","bienestar laboral","startups","transparencia","alan","liderazgo"],"ratio":1.5,"color":"#355569"},{"id":"el-alma-popular","shelf":15,"theme":"Teatro","title":"El alma popular","author":"Carlos Arniches","sortKey":"Arniches","summary":"Volumen dedicado a Carlos Arniches, el gran retratista del Madrid castizo, cuyo teatro supo captar como pocos el habla, el ingenio y la ternura de las clases populares. Reúne una selección de su obra y textos en torno a ella, para mostrar tanto al autor de sainetes chispeantes como al creador de la «tragedia grotesca», donde la risa convive con la crítica social y la compasión por los humildes. Su título resume bien la intención: acercarse al alma del pueblo que Arniches convirtió en materia teatral. Una buena puerta de entrada a un clásico del teatro español a veces injustamente olvidado.","authorBio":"Carlos Arniches (1866-1943) fue un dramaturgo alicantino, maestro del sainete y del género chico madrileño y creador de la «tragedia grotesca».","language":"español","tags":["teatro","sainete","madrid","humor","costumbrismo"],"ratio":1.5,"color":"#a03731"},{"id":"obtenga-el-si","shelf":16,"theme":"Liderazgo y empresa","title":"Obtenga el sí","author":"Roger Fisher, William Ury y Bruce Patton","sortKey":"Fisher","summary":"Fruto del Proyecto de Negociación de Harvard, este clásico propone dejar atrás la negociación basada en posiciones, en la que cada parte se atrinchera, para negociar según principios. Su método se resume en cuatro ideas: separar a las personas del problema, centrarse en los intereses y no en las posturas, inventar opciones de beneficio mutuo e insistir en criterios objetivos. Incluye además consejos para tratar con interlocutores más poderosos o que juegan sucio. Claro, breve y aplicable tanto a la empresa como a la familia o la vida diaria, sigue siendo una de las mejores guías para llegar a acuerdos justos sin romper relaciones.","authorBio":"Roger Fisher (1922-2012) y William Ury fundaron el Programa de Negociación de la Universidad de Harvard; Bruce Patton, coautor de la segunda edición, es también experto en negociación y mediación.","year":1981,"originalTitle":"Getting to Yes","language":"inglés","pages":240,"tags":["negociación","conflictos","comunicación","acuerdos","harvard"],"cover":"covers/obtenga-el-si.jpg","ratio":1.497,"color":"#9fbf69"},{"id":"escucha-cataluna-escucha-espana","shelf":17,"theme":"Historia y actualidad","title":"Escucha, Cataluña. Escucha, España","author":"Josep Borrell, Francesc de Carreras, Juan-José López Burniol y Josep Piqué","sortKey":"Borrell","summary":"Cuatro voces catalanas de trayectorias y sensibilidades políticas distintas —un exministro socialista, un catedrático de Derecho Constitucional, un notario y un exministro popular— se unen para dialogar sobre la crisis abierta en Cataluña con el proceso independentista. Analizan sus raíces históricas, económicas y jurídicas, desmontan algunos mitos de uno y otro lado y defienden que la secesión no es la salida, sino el entendimiento dentro de un marco común. Es un libro de reflexión serena y plural, escrito al calor de los acontecimientos de 2017, que invita a escuchar antes de juzgar y a buscar puentes.","authorBio":"Josep Borrell y Josep Piqué fueron ministros en gobiernos de distinto signo; Francesc de Carreras es catedrático de Derecho Constitucional y Juan-José López Burniol, notario y articulista.","year":2017,"language":"español","pages":240,"tags":["cataluña","política","independentismo","españa","constitución","actualidad"],"cover":"covers/escucha-cataluna-escucha-espana.jpg","ratio":1.548,"color":"#cf7730"},{"id":"the-new-father-a-dad-s-guide-to-the-first-year","shelf":18,"theme":"Familia y crianza","title":"The New Father. A Dad's Guide to the First Year","author":"Armin A. Brott","sortKey":"Brott","note":"Tercera edición, en inglés","summary":"Casi todos los libros sobre el primer año del bebé se dirigen a la madre; este, en cambio, está escrito para el padre. Mes a mes, Armin Brott explica cómo se desarrolla el niño, qué está viviendo la madre y, sobre todo, qué siente y qué puede hacer el propio padre: sus dudas, su cansancio, su relación de pareja, el trabajo o las finanzas familiares. Lleno de consejos prácticos, datos y un tono cercano y con humor, anima a los hombres a implicarse de lleno en la crianza desde el primer día. Una guía muy útil y tranquilizadora para estrenarse en la paternidad.","authorBio":"Armin A. Brott es un escritor y divulgador estadounidense especializado en paternidad, autor de la serie de guías «The New Father».","year":1997,"language":"inglés","pages":320,"tags":["paternidad","bebés","primer año","crianza","padres"],"ratio":1.5,"color":"#92704f"},{"id":"como-polvo-en-el-viento","shelf":19,"theme":"Narrativa","title":"Como polvo en el viento","author":"Leonardo Padura","sortKey":"Padura","summary":"Un grupo de amigos cubanos, el Clan, se reúne en La Habana en 1990 para celebrar un cumpleaños. Poco después, la crisis del llamado Período Especial los dispersa por el mundo: Barcelona, Madrid, Miami, Buenos Aires… Décadas más tarde, una joven descubre en una vieja fotografía un secreto que obliga a revisar aquella historia común. Leonardo Padura construye una novela coral y emotiva sobre el exilio, la amistad, la pérdida y la memoria, y sobre lo que queda de una generación arrancada de su tierra. Un retrato profundo y humano de la diáspora cubana, narrado con la maestría habitual del autor.","authorBio":"Leonardo Padura es un novelista y periodista cubano, creador del detective Mario Conde y Premio Princesa de Asturias de las Letras en 2015.","year":2020,"language":"español","pages":672,"tags":["cuba","exilio","amistad","memoria","novela contemporánea","diáspora"],"cover":"covers/como-polvo-en-el-viento.jpg","ratio":1.52,"color":"#333333"},{"id":"don-quijote-de-la-mancha-version-de-jose-luis-gimenez-fronti","shelf":20,"theme":"Narrativa","title":"Don Quijote de la Mancha (versión de José Luis Giménez-Frontín)","author":"Miguel de Cervantes","sortKey":"Cervantes","note":"Adaptación de José Luis Giménez-Frontín","summary":"Adaptación de la obra cumbre de Cervantes que conserva lo esencial de su argumento y de su espíritu en un texto más breve y accesible. Acompañamos a don Alonso Quijano, que de tanto leer libros de caballerías decide hacerse caballero andante, y a su fiel escudero Sancho Panza en sus aventuras por los caminos de La Mancha: los molinos de viento, los rebaños, la ínsula Barataria… La versión de Giménez-Frontín facilita la lectura sin renunciar al humor, la ternura y la hondura de un libro que habla del idealismo, la locura, la amistad y la dignidad humana. Una excelente puerta de entrada al clásico.","authorBio":"Miguel de Cervantes (1547-1616) es la figura cumbre de las letras españolas y creador de la novela moderna; José Luis Giménez-Frontín (1943-2008), autor de esta versión, fue poeta, narrador y ensayista barcelonés.","year":1605,"language":"español","tags":["clásicos","siglo de oro","novela","caballerías","adaptación","cervantes"],"cover":"covers/don-quijote-de-la-mancha-version-de-jose-luis-gimenez-fronti.jpg","ratio":1.538,"color":"#d2763e"},{"id":"vivir-la-vida-con-sentido","shelf":21,"theme":"Liderazgo y empresa","title":"Vivir la vida con sentido","author":"Víctor Küppers","sortKey":"Küppers","summary":"Víctor Küppers, uno de los conferenciantes más queridos de España, defiende que lo que marca la diferencia en la vida no son los conocimientos ni la experiencia, sino la actitud. Con un tono desenfadado, lleno de anécdotas familiares y humor, recuerda verdades sencillas que solemos olvidar: la importancia de la alegría, del agradecimiento, del esfuerzo, de tratar bien a los demás y de poner lo importante por delante de lo urgente. No pretende ser un tratado, sino un empujón de entusiasmo para vivir de forma más plena y generosa. Una lectura ligera y optimista que deja muy buen sabor de boca.","authorBio":"Víctor Küppers es un formador y conferenciante hispano-alemán, doctor en Humanidades y profesor, conocido por sus charlas sobre actitud y entusiasmo.","year":2012,"language":"español","pages":192,"tags":["actitud","optimismo","sentido de la vida","desarrollo personal","felicidad"],"cover":"covers/vivir-la-vida-con-sentido.jpg","ratio":1.65,"color":"#a0252f"},{"id":"la-primera-revolucion-mundial-informe-del-consejo-al-club-de","shelf":22,"theme":"Historia y actualidad","title":"La primera revolución mundial. Informe del Consejo al Club de Roma","author":"Alexander King y Bertrand Schneider","sortKey":"King","summary":"Veinte años después de «Los límites del crecimiento», el Club de Roma revisó el estado del mundo tras el final de la Guerra Fría. Este informe describe una época de cambios acelerados y entrelazados —demografía, medio ambiente, energía, desarrollo, tecnología, gobernabilidad— que configuran lo que los autores llaman la primera revolución verdaderamente mundial. Frente a la «problemática» global, propone una «resolútica»: respuestas coordinadas, nuevas formas de gobierno y, sobre todo, un despertar ético y educativo. Leído hoy, es un documento muy interesante para comparar los diagnósticos de entonces con lo que de verdad ha ocurrido.","authorBio":"Alexander King (1909-2007), químico escocés, fue cofundador del Club de Roma; Bertrand Schneider fue secretario general de esta organización.","year":1991,"originalTitle":"The First Global Revolution","language":"inglés","pages":260,"tags":["club de roma","globalización","medio ambiente","geopolítica","futuro","desarrollo"],"cover":"covers/la-primera-revolucion-mundial-informe-del-consejo-al-club-de.jpg","ratio":1.511,"color":"#1e5782"},{"id":"juegos-de-ninos","shelf":23,"theme":"Poesía","title":"Juegos de niños","author":"Ana Merino","sortKey":"Merino","summary":"Poemario galardonado con el Premio Fray Luis de León, en el que Ana Merino recorre las distintas edades de la vida a partir de un homenaje a la infancia, sus juegos y sus mitos. Los poemas muestran cómo la inocencia del niño se va transformando con el tiempo, y cómo crecer supone aceptar pérdidas y metamorfosis. Con una voz delicada, a menudo femenina, y con imágenes sencillas pero cargadas de hondura, el libro invita a mirar hacia atrás con ternura y algo de melancolía. Una lectura breve, luminosa y evocadora para quien disfruta de la poesía contemporánea en español.","authorBio":"Ana Merino es una poeta, dramaturga y novelista madrileña, profesora en la Universidad de Iowa y Premio Nadal 2020; es también especialista en cómic.","year":2003,"language":"español","pages":80,"tags":["poesía","infancia","memoria","poesía contemporánea","crecer"],"cover":"covers/juegos-de-ninos.jpg","ratio":1.645,"color":"#353531"},{"id":"1808-el-dos-de-mayo-tres-miradas","shelf":24,"theme":"Historia y actualidad","title":"1808. El dos de mayo, tres miradas","author":"Alejo Carpentier, Benito Pérez Galdós y José María Blanco White","sortKey":"Carpentier","summary":"Publicado con motivo del bicentenario del levantamiento madrileño contra las tropas napoleónicas, este volumen reúne tres visiones literarias de aquellos días. La «Carta duodécima» de José María Blanco White ofrece el testimonio de un contemporáneo; Benito Pérez Galdós evoca los hechos en «El 19 de marzo y el 2 de mayo», uno de sus Episodios Nacionales; y Alejo Carpentier, en «El siglo de las luces», mira la época desde el Caribe y la Revolución francesa. Tres estilos y perspectivas complementarias para comprender un episodio decisivo de la historia de España y el comienzo de la Guerra de la Independencia.","authorBio":"Tres grandes escritores en lengua española: el sevillano José María Blanco White (1775-1841), el canario Benito Pérez Galdós (1843-1920) y el cubano Alejo Carpentier (1904-1980).","year":2008,"language":"español","tags":["historia de españa","guerra de la independencia","dos de mayo","napoleón","madrid","episodios nacionales"],"cover":"covers/1808-el-dos-de-mayo-tres-miradas.jpg","ratio":1.773,"color":"#38352f"},{"id":"milagro-en-los-andes","shelf":25,"theme":"Historia y actualidad","title":"Milagro en los Andes","author":"Nando Parrado","sortKey":"Parrado","summary":"En octubre de 1972, un avión que llevaba a un equipo de rugby uruguayo se estrelló en plena cordillera de los Andes. Nando Parrado, uno de los supervivientes, perdió allí a su madre y a su hermana, y tras más de dos meses de frío, hambre y decisiones extremas emprendió con Roberto Canessa una travesía a pie por las montañas para pedir ayuda. Treinta años después, narra con sobriedad y emoción aquella experiencia y lo que aprendió sobre el amor, la amistad, la fe y la fuerza de la voluntad humana. Un testimonio sobrecogedor y profundamente esperanzador.","authorBio":"Nando Parrado es un empresario y conferenciante uruguayo, superviviente de la tragedia de los Andes de 1972; escribió el libro junto al periodista Vince Rause.","year":2006,"originalTitle":"Miracle in the Andes","language":"inglés","pages":320,"tags":["supervivencia","testimonio","andes","esperanza","amistad","historia real"],"ratio":1.5,"color":"#a6913a"},{"id":"la-vida-es-sueno","shelf":26,"theme":"Teatro","title":"La vida es sueño","author":"Pedro Calderón de la Barca","sortKey":"Calderón","summary":"Segismundo, príncipe de Polonia, ha vivido encerrado en una torre desde su nacimiento porque su padre, el rey Basilio, temía un oráculo que lo presentaba como un tirano. Cuando es llevado a palacio para ponerlo a prueba, se comporta con violencia y es devuelto a su prisión, convencido de que todo fue un sueño. A partir de ahí, Calderón plantea grandes preguntas sobre la libertad frente al destino, el sentido de la vida y la necesidad de obrar bien aunque todo sea pasajero. Cumbre del teatro barroco español, sus versos siguen resonando con una fuerza filosófica y espiritual extraordinaria.","authorBio":"Pedro Calderón de la Barca (1600-1681) fue, junto a Lope de Vega, el gran dramaturgo del Siglo de Oro español y maestro del auto sacramental.","year":1635,"language":"español","pages":200,"tags":["siglo de oro","teatro barroco","libertad","destino","filosofía","clásicos"],"cover":"covers/la-vida-es-sueno.jpg","ratio":1.667,"color":"#9a7d5e"},{"id":"divinas-palabras","shelf":27,"theme":"Teatro","title":"Divinas palabras","author":"Ramón María del Valle-Inclán","sortKey":"Valle-Inclán","summary":"En una aldea gallega, la muerte de una mendiga deja huérfano a un niño hidrocéfalo, y sus parientes se disputan la custodia del pequeño porque exhibirlo por las ferias puede dar dinero. A su alrededor se despliega un mundo de miseria, codicia, lujuria y superstición, en el que solo las palabras latinas de la Escritura, pronunciadas por el sacristán, logran imponer al final un silencio sobrecogedor. Valle-Inclán escribe una «tragicomedia de aldea» de enorme fuerza poética y crudeza, que retrata la condición humana en su degradación pero también la misteriosa potencia de lo sagrado.","authorBio":"Ramón María del Valle-Inclán (1866-1936) fue un escritor gallego de la generación del 98, creador del esperpento y uno de los grandes renovadores del teatro español.","year":1920,"language":"español","pages":180,"tags":["teatro","galicia","valle-inclán","tragicomedia","mundo rural","clásicos"],"cover":"covers/divinas-palabras.jpg","ratio":1.52,"color":"#333333"},{"id":"luces-de-bohemia","shelf":28,"theme":"Teatro","title":"Luces de bohemia","author":"Ramón María del Valle-Inclán","sortKey":"Valle-Inclán","summary":"Max Estrella, poeta ciego y empobrecido, recorre la noche madrileña acompañado del pícaro Don Latino de Hispalis en su última jornada de vida. Por tabernas, redacciones, comisarías y calles revueltas desfila una España grotesca de políticos corruptos, policías brutales y artistas fracasados. En esta obra Valle-Inclán formula su estética del esperpento: la realidad española, deformada como en los espejos cóncavos del callejón del Gato, para mostrar su tragedia con toda su crudeza. Un hito del teatro del siglo XX, lleno de humor amargo, lucidez y una prosa deslumbrante.","authorBio":"Ramón María del Valle-Inclán (1866-1936) fue un escritor gallego de la generación del 98, creador del esperpento y uno de los grandes renovadores del teatro español.","year":1920,"language":"español","pages":200,"tags":["esperpento","teatro","madrid","bohemia","crítica social","generación del 98"],"cover":"covers/luces-de-bohemia.jpg","ratio":1.597,"color":"#daaf61"},{"id":"ivanov-la-gaviota-tio-vania","shelf":29,"theme":"Teatro","title":"Ivánov. La gaviota. Tío Vania","author":"Antón Chéjov","sortKey":"Chéjov","summary":"Este volumen reúne tres obras fundamentales de Chéjov. En «Ivánov», un hombre agotado y lleno de culpa ve cómo se apaga su vida y su matrimonio; en «La gaviota», jóvenes aspirantes a escritores y actrices chocan con artistas consagrados en una reflexión sobre el arte y el amor no correspondido; y en «Tío Vania», un hombre descubre que ha sacrificado su vida al servicio de un profesor mediocre. Con diálogos aparentemente cotidianos, Chéjov revolucionó el teatro mostrando el drama silencioso de personas corrientes, su tedio, sus anhelos frustrados y su capacidad de seguir adelante.","authorBio":"Antón Chéjov (1860-1904) fue un médico, cuentista y dramaturgo ruso, considerado uno de los padres del teatro moderno y maestro del relato breve.","year":1887,"originalTitle":"Иванов. Чайка. Дядя Ваня","language":"ruso","pages":300,"tags":["teatro","literatura rusa","chéjov","clásicos","drama"],"ratio":1.5,"color":"#845c43"},{"id":"el-persa","shelf":30,"theme":"Clásicos grecolatinos","title":"El persa","author":"Plauto","sortKey":"Plauto","summary":"Comedia del latino Plauto ambientada en Atenas, en la que un esclavo enamorado, Tóxilo, aprovecha la ausencia de su amo para urdir un engaño con el que liberar a la muchacha que ama de las garras de un proxeneta. Para ello cuenta con un parásito siempre hambriento y su hija, que se hará pasar por cautiva traída de Persia. Con su ritmo vivo, sus juegos de palabras, sus disfraces y su desenlace festivo, la obra muestra el talento de Plauto para la farsa y la sátira de tipos humanos. Una pieza menos conocida de su repertorio, pero muy divertida y representativa de la comedia romana.","authorBio":"Tito Macio Plauto (c. 254-184 a. C.) fue el gran comediógrafo latino, cuya obra influyó en Shakespeare, Molière y en todo el teatro cómico europeo.","originalTitle":"Persa","language":"latín","tags":["comedia","teatro latino","clásicos grecolatinos","roma","humor"],"cover":"covers/el-persa.jpg","ratio":1.529,"color":"#33b64a"},{"id":"edipo-rey","shelf":31,"theme":"Clásicos grecolatinos","title":"Edipo rey","author":"Sófocles","sortKey":"Sófocles","summary":"Tebas sufre una peste y el oráculo exige descubrir al asesino del antiguo rey Layo. Edipo, el soberano que un día salvó a la ciudad resolviendo el enigma de la Esfinge, emprende la investigación con decisión, sin sospechar que la verdad lo señala a él mismo. Sófocles construye una tragedia de precisión perfecta, en la que cada revelación acerca al protagonista a su propia ruina. Considerada por Aristóteles el modelo de la tragedia, la obra plantea preguntas eternas sobre el destino, la culpa, los límites del conocimiento humano y la humildad ante lo divino. Imprescindible.","authorBio":"Sófocles (c. 496-406 a. C.) fue uno de los tres grandes trágicos de la Atenas clásica, junto a Esquilo y Eurípides.","originalTitle":"Οἰδίπους Τύραννος","language":"griego antiguo","pages":120,"tags":["tragedia griega","clásicos grecolatinos","destino","mitología","teatro"],"cover":"covers/edipo-rey.jpg","ratio":1.502,"color":"#715c4a"},{"id":"eloisa-esta-debajo-de-un-almendro-las-cinco-advertencias-de-","shelf":32,"theme":"Teatro","title":"Eloísa está debajo de un almendro. Las cinco advertencias de Satanás","author":"Enrique Jardiel Poncela","sortKey":"Jardiel","summary":"Dos comedias de Jardiel Poncela, maestro del humor inverosímil. En «Eloísa está debajo de un almendro», una joven se ve envuelta en el misterio de una familia excéntrica, llena de manías absurdas, que guarda un secreto ligado a una mujer desaparecida veinte años atrás; el resultado mezcla intriga policiaca y disparate. «Las cinco advertencias de Satanás» presenta a un donjuán que recibe avisos misteriosos mientras se enamora de verdad por primera vez. Ingenio verbal, situaciones imposibles y personajes estrafalarios hacen de estas obras dos joyas del teatro cómico español del siglo XX.","authorBio":"Enrique Jardiel Poncela (1901-1952) fue un dramaturgo y novelista madrileño, renovador del humor en el teatro español con su comedia de lo inverosímil.","year":1935,"language":"español","pages":300,"tags":["comedia","humor","teatro español","siglo xx","absurdo"],"cover":"covers/eloisa-esta-debajo-de-un-almendro-las-cinco-advertencias-de-.jpg","ratio":1.548,"color":"#ca92b6"},{"id":"la-mujer-eterna","shelf":33,"theme":"Fe y espiritualidad","title":"La mujer eterna","author":"Gertrud von le Fort","sortKey":"Le Fort","summary":"Gertrud von le Fort, gran escritora católica alemana, medita sobre la vocación de la mujer a la luz de la fe. Frente a las visiones que la reducen a funciones sociales o la enfrentan al varón, contempla lo femenino como una realidad con un significado espiritual propio, que se expresa en tres figuras: la virgen, la esposa y la madre, todas ellas iluminadas por María. Para la autora, la entrega, la acogida y el velo del misterio son rasgos de una dignidad inmensa. Un ensayo breve, de prosa poética y gran profundidad, que sigue inspirando la reflexión cristiana sobre la mujer.","authorBio":"Gertrud von le Fort (1876-1971) fue una novelista y poeta alemana convertida al catolicismo, autora de «La última en el cadalso», que inspiró los «Diálogos de carmelitas».","year":1934,"originalTitle":"Die ewige Frau","language":"alemán","pages":180,"tags":["mujer","espiritualidad","virgen maría","antropología cristiana","vocación","catolicismo"],"ratio":1.5,"color":"#54bdc4"},{"id":"the-god-of-small-things","shelf":34,"theme":"Narrativa","title":"The God of Small Things","author":"Arundhati Roy","sortKey":"Roy","note":"Edición en inglés","summary":"En el estado indio de Kerala, los mellizos Estha y Rahel crecen en una familia acomodada marcada por los secretos, las tensiones religiosas y las rígidas barreras de casta. Un verano de 1969, la llegada de una prima inglesa y el amor prohibido de su madre por un intocable desencadenan una tragedia que los separará durante años. Arundhati Roy alterna pasado y presente con una prosa sensorial, juguetona y muy original, para mostrar cómo las «cosas pequeñas» de la vida chocan con las grandes leyes de la historia y la sociedad. Una novela deslumbrante y dolorosa, ganadora del Booker.","authorBio":"Arundhati Roy es una escritora y activista india que ganó el Premio Booker en 1997 con esta, su primera novela.","year":1997,"language":"inglés","pages":340,"tags":["india","familia","castas","infancia","novela contemporánea","premio booker"],"cover":"covers/the-god-of-small-things.jpg","ratio":1.449,"color":"#4a3c34"},{"id":"cartas-a-un-joven-poeta","shelf":35,"theme":"Poesía","title":"Cartas a un joven poeta","author":"Rainer Maria Rilke","sortKey":"Rilke","summary":"Entre 1903 y 1908, Rilke respondió por carta a Franz Xaver Kappus, un joven cadete que le había enviado sus versos pidiéndole consejo. Lejos de corregir sus poemas, el gran poeta le habla de lo esencial: mirar dentro de uno mismo y preguntarse si de verdad necesita escribir, amar la soledad, tener paciencia con lo que aún no se ha resuelto en el corazón y vivir las preguntas. Estas diez cartas se han convertido en un pequeño clásico sobre la vocación artística y sobre la vida interior, lleno de sabiduría y belleza, que cada lector puede aplicar a su propio camino.","authorBio":"Rainer Maria Rilke (1875-1926) fue un poeta en lengua alemana nacido en Praga, autor de las «Elegías de Duino» y de los «Sonetos a Orfeo».","year":1929,"originalTitle":"Briefe an einen jungen Dichter","language":"alemán","pages":110,"tags":["poesía","vocación","soledad","cartas","vida interior","escritura"],"cover":"covers/cartas-a-un-joven-poeta.jpg","ratio":1.506,"color":"#4b501d"},{"id":"surprised-by-joy","shelf":36,"theme":"Fe y espiritualidad","title":"Surprised by Joy","author":"C. S. Lewis","sortKey":"Lewis","note":"Edición en inglés","summary":"C. S. Lewis narra en esta autobiografía espiritual su camino desde la infancia en Belfast, la temprana muerte de su madre y los duros internados ingleses, hasta su conversión al cristianismo. El hilo conductor es la «alegría»: un anhelo intenso y fugaz de algo que ninguna cosa de este mundo logra colmar, y que lo acompañó a través del ateísmo de juventud y las trincheras de la Primera Guerra Mundial. Con su habitual inteligencia y humor, describe cómo, casi a su pesar, acabó rindiéndose a Dios. Un testimonio sincero y profundo para quien busca sentido y reflexiona sobre la fe.","authorBio":"C. S. Lewis (1898-1963) fue un escritor y profesor de literatura en Oxford y Cambridge, autor de «Las crónicas de Narnia» y de «Mero cristianismo».","year":1955,"language":"inglés","pages":240,"tags":["autobiografía","conversión","cristianismo","alegría","fe","c. s. lewis"],"cover":"covers/surprised-by-joy.jpg","ratio":1.543,"color":"#c6bc9d"},{"id":"el-despertar-de-la-senorita-prim","shelf":37,"theme":"Narrativa","title":"El despertar de la señorita Prim","author":"Natalia Sanmartín Fenollera","sortKey":"Sanmartín","summary":"Prudencia Prim, una joven culta y muy segura de sus ideas modernas, acepta un empleo como bibliotecaria en San Ireneo de Arnois, un pequeño pueblo cuyos habitantes han decidido vivir de espaldas a las prisas del mundo actual. Allí trabaja para un caballero enigmático y erudito, con quien mantiene conversaciones que poco a poco desmontan sus certezas. Entre libros, té, niños sorprendentes y vecinos singulares, la protagonista emprende un viaje interior hacia la belleza, la tradición, el amor y la fe. Una novela delicada y luminosa, que se ha convertido en un fenómeno internacional.","authorBio":"Natalia Sanmartín Fenollera es una periodista y escritora gallega; esta fue su primera novela, traducida a numerosos idiomas.","year":2013,"language":"español","pages":360,"tags":["novela","belleza","tradición","conversión","vida sencilla","literatura católica"],"cover":"covers/el-despertar-de-la-senorita-prim.jpg","ratio":1.534,"color":"#62272d"},{"id":"el-autobus-perdido","shelf":38,"theme":"Narrativa","title":"El autobús perdido","author":"John Steinbeck","sortKey":"Steinbeck","summary":"Un viejo autobús que une dos carreteras secundarias de California se queda atascado por una tormenta, y sus pasajeros —un vendedor, una camarera, una joven ingenua, un matrimonio acomodado, el conductor y su ayudante— se ven obligados a convivir durante una larga jornada. Steinbeck aprovecha esta situación para retratar con ironía y humanidad los deseos, frustraciones y apariencias de la sociedad estadounidense de posguerra. Cada personaje se revela poco a poco, con sus miserias y anhelos. Una novela menos conocida del autor, pero llena de observación psicológica y de su característico realismo.","authorBio":"John Steinbeck (1902-1968) fue un novelista estadounidense, autor de «Las uvas de la ira» y «Al este del Edén», y Premio Nobel de Literatura en 1962.","year":1947,"originalTitle":"The Wayward Bus","language":"inglés","pages":320,"tags":["literatura estadounidense","novela","sociedad","california","posguerra"],"ratio":1.5,"color":"#9a3c3e"},{"id":"post-office","shelf":39,"theme":"Narrativa","title":"Post Office","author":"Charles Bukowski","sortKey":"Bukowski","note":"Edición en inglés","summary":"Primera novela de Charles Bukowski, en la que su alter ego Henry Chinaski relata sus años como cartero y empleado de clasificación en el servicio postal de Los Ángeles. Con un estilo seco, directo y a menudo cómico, describe la monotonía de un trabajo alienante, los jefes absurdos, las apuestas en el hipódromo, el alcohol y unas relaciones sentimentales desordenadas. Bajo su apariencia descarnada hay una crítica feroz a la deshumanización del trabajo moderno. Una obra cruda y de lenguaje explícito, que retrata con sinceridad una vida a la deriva y se ha convertido en clave del realismo sucio.","authorBio":"Charles Bukowski (1920-1994) fue un poeta y novelista estadounidense de origen alemán, figura emblemática del llamado realismo sucio.","year":1971,"language":"inglés","pages":200,"tags":["literatura estadounidense","trabajo","realismo sucio","novela","los ángeles"],"cover":"covers/post-office.jpg","ratio":1.534,"color":"#94d5e6"},{"id":"momentos-estelares-de-la-humanidad","shelf":40,"theme":"Historia y actualidad","title":"Momentos estelares de la humanidad","author":"Stefan Zweig","sortKey":"Zweig","summary":"Stefan Zweig reúne una serie de miniaturas históricas sobre esos instantes decisivos en los que, en apenas unas horas, se juega el destino de muchas generaciones: la caída de Constantinopla, el descubrimiento del Pacífico por Núñez de Balboa, la derrota de Napoleón en Waterloo, la composición de «El Mesías» de Händel, la carrera hacia el Polo Sur o el viaje de Lenin hacia Rusia. Con su prosa elegante y su capacidad para narrar con tensión dramática, Zweig convierte la historia en una sucesión de relatos apasionantes. Una lectura deliciosa que enseña historia y emociona como una novela.","authorBio":"Stefan Zweig (1881-1942) fue un escritor austriaco, maestro de la novela corta y la biografía, y uno de los autores más leídos de su tiempo.","year":1927,"originalTitle":"Sternstunden der Menschheit","language":"alemán","pages":320,"tags":["historia","biografías","momentos decisivos","relatos","europa"],"ratio":1.5,"color":"#956750"},{"id":"soldados-de-salamina","shelf":41,"theme":"Narrativa","title":"Soldados de Salamina","author":"Javier Cercas","sortKey":"Cercas","summary":"Un periodista en crisis se obsesiona con un episodio poco conocido del final de la Guerra Civil: el fusilamiento fallido de Rafael Sánchez Mazas, ideólogo falangista, que logró huir al bosque y fue descubierto por un joven soldado republicano que, tras mirarlo a los ojos, le dejó escapar. ¿Por qué lo hizo? La búsqueda de ese soldado anónimo, mezcla de novela, crónica y relato real, se convierte en una reflexión conmovedora sobre la memoria, el heroísmo y la compasión. Javier Cercas renovó con este libro la manera de narrar la guerra y alcanzó un enorme éxito de crítica y lectores.","authorBio":"Javier Cercas es un novelista y ensayista español, nacido en Ibahernando (Cáceres), autor de obras como «Anatomía de un instante» y «El impostor».","year":2001,"language":"español","pages":210,"tags":["guerra civil","memoria histórica","heroísmo","novela","literatura española"],"cover":"covers/soldados-de-salamina.jpg","ratio":1.488,"color":"#133c53"},{"id":"sin-noticias-de-gurb","shelf":42,"theme":"Narrativa","title":"Sin noticias de Gurb","author":"Eduardo Mendoza","sortKey":"Mendoza","summary":"Un extraterrestre llega a Barcelona en vísperas de los Juegos Olímpicos de 1992 en busca de su compañero Gurb, que se ha perdido tras adoptar la apariencia de la cantante Marta Sánchez. A través de su diario, minuto a minuto, asistimos a sus desconcertantes intentos de adaptarse a la vida humana: comer churros, coger el autobús, enamorarse de una vecina o entender las costumbres de los barceloneses. Eduardo Mendoza firma una sátira desternillante de la sociedad urbana, de sus manías y absurdos, contada con un humor fino y desbordante. Uno de los libros más divertidos de la literatura española reciente.","authorBio":"Eduardo Mendoza es un novelista barcelonés, autor de «La verdad sobre el caso Savolta» y «La ciudad de los prodigios», y Premio Cervantes en 2016.","year":1991,"language":"español","pages":140,"tags":["humor","barcelona","sátira","ciencia ficción","novela"],"ratio":1.5,"color":"#774057"},{"id":"un-lugar-llamado-antano","shelf":43,"theme":"Narrativa","title":"Un lugar llamado Antaño","author":"Olga Tokarczuk","sortKey":"Tokarczuk","summary":"Antaño es un pueblo imaginario de Polonia, custodiado por cuatro arcángeles en sus cuatro fronteras, donde transcurre la vida de varias generaciones a lo largo del siglo XX. Las guerras mundiales, el comunismo y los cambios sociales irrumpen en este microcosmos, pero el relato se detiene también en el tiempo de las cosas, de los animales, de los muertos e incluso de Dios. Olga Tokarczuk combina realismo y magia en capítulos breves y poéticos para construir una especie de mito sobre la existencia humana y el paso del tiempo. Una novela hermosa y singular de la premio Nobel polaca.","authorBio":"Olga Tokarczuk es una escritora polaca, autora de «Los errantes» y «Los libros de Jacob», y Premio Nobel de Literatura 2018.","year":1996,"originalTitle":"Prawiek i inne czasy","language":"polaco","pages":320,"tags":["polonia","realismo mágico","siglo xx","tiempo","premio nobel","novela"],"ratio":1.5,"color":"#c16c71"},{"id":"sendas-equivocas","shelf":44,"theme":"Narrativa","title":"Sendas equívocas","author":"Stefan Zweig","sortKey":"Zweig","summary":"Volumen que reúne tres novelas cortas de Stefan Zweig menos conocidas que otras suyas, pero de la misma calidad: «Historia de un crepúsculo», sobre el despertar sentimental de un adolescente en un castillo; «Subversión de los sentidos», que explora la intensa y turbadora relación entre un joven estudiante y su admirado profesor; y «Ocaso de un corazón», donde un anciano descubre de pronto el vacío de una vida dedicada a su familia. En todas, Zweig despliega su maestría para sondear las pasiones ocultas, los secretos y los extravíos del alma humana con delicadeza psicológica.","authorBio":"Stefan Zweig (1881-1942) fue un escritor austriaco, maestro de la novela corta y la biografía, y uno de los autores más leídos de su tiempo.","language":"alemán","pages":204,"tags":["novela corta","psicología","pasiones","literatura austriaca","relatos"],"cover":"covers/sendas-equivocas.jpg","ratio":1.401,"color":"#6e4b4a"},{"id":"patria","shelf":45,"theme":"Narrativa","title":"Patria","author":"Fernando Aramburu","sortKey":"Aramburu","summary":"El día en que ETA anuncia el abandono de las armas, Bittori, viuda de un empresario asesinado por la banda, decide volver al pueblo donde vivió para buscar la verdad. Allí vive Miren, su amiga íntima de juventud, cuyo hijo está preso por terrorismo. A través de dos familias unidas y después separadas por la violencia, Fernando Aramburu reconstruye treinta años de historia del País Vasco: el miedo, el silencio, el odio y la complicidad, pero también la posibilidad del perdón. Una novela coral, honda y emocionante, convertida en un fenómeno literario y social en España.","authorBio":"Fernando Aramburu es un novelista donostiarra afincado en Alemania, Premio Nacional de Narrativa por «Patria».","year":2016,"language":"español","pages":648,"tags":["eta","país vasco","terrorismo","perdón","familia","novela"],"cover":"covers/patria.jpg","ratio":1.543,"color":"#2b303b"},{"id":"cinco-horas-con-mario","shelf":46,"theme":"Narrativa","title":"Cinco horas con Mario","author":"Miguel Delibes","sortKey":"Delibes","summary":"Marzo de 1966. Carmen vela durante toda una noche el cadáver de su marido Mario, profesor de instituto y escritor de ideas progresistas, fallecido de repente. En un largo monólogo dirigido al difunto, le reprocha mil cosas: su falta de ambición, su idealismo, su desinterés por el dinero y por las apariencias, y deja escapar sus propias frustraciones y secretos. A través de esa voz, Delibes retrata con maestría la España del franquismo, sus prejuicios y su división, y el drama de un matrimonio que nunca llegó a comprenderse. Una de las grandes novelas españolas del siglo XX.","authorBio":"Miguel Delibes (1920-2010) fue un novelista vallisoletano, miembro de la Real Academia Española y Premio Cervantes en 1993.","year":1966,"language":"español","pages":280,"tags":["monólogo","matrimonio","franquismo","sociedad española","novela","delibes"],"cover":"covers/cinco-horas-con-mario.jpg","ratio":1.605,"color":"#4d3c35"},{"id":"la-insoportable-levedad-del-ser","shelf":47,"theme":"Narrativa","title":"La insoportable levedad del ser","author":"Milan Kundera","sortKey":"Kundera","summary":"Praga, 1968. Tomás, un cirujano incapaz de renunciar a sus aventuras, se enamora de Teresa, una joven sensible que sufre por sus infidelidades; a su alrededor se mueven Sabina, una pintora que huye de todo compromiso, y Franz, un profesor idealista. Con la invasión soviética como telón de fondo, Kundera teje una novela-ensayo sobre la libertad y el compromiso, el peso y la levedad de nuestras decisiones, el amor y el sentido de una vida que solo se vive una vez. Un clásico contemporáneo, de gran lucidez filosófica, que aborda la sexualidad con franqueza.","authorBio":"Milan Kundera (1929-2023) fue un novelista checo nacionalizado francés, autor también de «La broma» y «La inmortalidad».","year":1984,"originalTitle":"Nesnesitelná lehkost bytí","language":"checo","pages":330,"tags":["praga","amor","libertad","comunismo","filosofía","novela"],"cover":"covers/la-insoportable-levedad-del-ser.jpg","ratio":1.543,"color":"#8ec1d6"},{"id":"niebla","shelf":48,"theme":"Narrativa","title":"Niebla","author":"Miguel de Unamuno","sortKey":"Unamuno","summary":"Augusto Pérez, un joven rico y ocioso, se enamora de Eugenia, una pianista que no le corresponde, y su vida sin rumbo se ve sacudida por el desengaño. Desesperado, decide visitar en Salamanca a su propio autor, don Miguel de Unamuno, para discutir con él sobre su destino. En este famoso encuentro entre criatura y creador, Unamuno plantea sus grandes obsesiones: la existencia, la libertad, la muerte y la relación del hombre con Dios. Una «nivola», como la llamó él mismo, que rompió las convenciones de la novela realista y anticipó muchas búsquedas de la literatura moderna.","authorBio":"Miguel de Unamuno (1864-1936) fue un escritor y filósofo bilbaíno de la generación del 98, rector de la Universidad de Salamanca.","year":1914,"language":"español","pages":260,"tags":["nivola","existencialismo","generación del 98","libertad","novela","clásicos"],"ratio":1.5,"color":"#60393f"},{"id":"la-celestina","shelf":49,"theme":"Teatro","title":"La Celestina","author":"Fernando de Rojas","sortKey":"Rojas","summary":"Calisto se enamora apasionadamente de Melibea y, ante su rechazo, recurre por consejo de su criado a Celestina, una vieja alcahueta experta en hechizos y engaños. A partir de ahí, la codicia de los criados y la pasión desordenada de los amantes desencadenan una cadena de muertes. Obra de transición entre la Edad Media y el Renacimiento, «La Celestina» combina un lenguaje riquísimo, culto y popular, con personajes de enorme verdad psicológica. Su intención declarada es moral: advertir contra los peligros del amor loco y de la avaricia. Un clásico imprescindible de la literatura española.","authorBio":"Fernando de Rojas (c. 1470-1541) fue un jurista castellano de La Puebla de Montalbán, a quien se atribuye la autoría de «La Celestina».","year":1499,"originalTitle":"Tragicomedia de Calisto y Melibea","language":"español","pages":360,"tags":["clásicos","renacimiento","amor","tragicomedia","literatura medieval","moral"],"cover":"covers/la-celestina.jpg","ratio":1.712,"color":"#483e1e"},{"id":"la-espuma-de-los-dias","shelf":50,"theme":"Narrativa","title":"La espuma de los días","author":"Boris Vian","sortKey":"Vian","summary":"Colin, un joven rico y soñador, se enamora de Chloé y se casan en un París fantástico donde los ratones hablan, las anguilas salen de los grifos y existe un «pianocóctel» que prepara bebidas según la melodía que se toca. Pero Chloé enferma: un nenúfar crece en su pulmón, y a medida que su salud empeora, el mundo luminoso que los rodea se va encogiendo y oscureciendo. Boris Vian escribió una historia de amor poética y surrealista, llena de humor, juegos de lenguaje y jazz, que se transforma en una melancólica meditación sobre la fragilidad de la felicidad.","authorBio":"Boris Vian (1920-1959) fue un escritor, ingeniero, trompetista de jazz y letrista francés, figura del París de posguerra de Saint-Germain-des-Prés.","year":1947,"originalTitle":"L'Écume des jours","language":"francés","pages":220,"tags":["surrealismo","amor","literatura francesa","jazz","novela","melancolía"],"ratio":1.5,"color":"#823e3a"},{"id":"1984","shelf":51,"theme":"Narrativa","title":"1984","author":"George Orwell","sortKey":"Orwell","summary":"En un Londres gris dominado por el Gran Hermano, Winston Smith trabaja reescribiendo el pasado para que coincida con las consignas del Partido. Su pequeña rebeldía —un diario, un amor clandestino con Julia— lo enfrenta a un poder que no solo vigila, sino que aspira a gobernar el pensamiento y el lenguaje mismos. Orwell construye una distopía de precisión implacable sobre la mentira institucionalizada, la neolengua y la fragilidad de la verdad. Una lectura imprescindible para reconocer las formas sutiles de manipulación y para valorar la libertad interior como un bien que hay que custodiar.","authorBio":"George Orwell (1903–1950), seudónimo de Eric Arthur Blair, fue un novelista y ensayista británico. Combatió en la guerra civil española y dedicó su obra a denunciar el totalitarismo y la corrupción del lenguaje político.","year":1949,"originalTitle":"Nineteen Eighty-Four","language":"inglés","pages":350,"tags":["distopía","totalitarismo","manipulación","lenguaje","libertad","vigilancia"],"cover":"covers/1984.jpg","ratio":1.529,"color":"#bc5d4c"},{"id":"nada","shelf":52,"theme":"Narrativa","title":"Nada","author":"Carmen Laforet","sortKey":"Laforet","summary":"Andrea llega a Barcelona poco después de la guerra civil para estudiar Letras, llena de ilusiones, y se instala en el piso de la calle Aribau donde vive su familia. Lo que encuentra es una casa sombría, habitada por parientes violentos, hambrientos y desquiciados. Entre la miseria doméstica y la amistad luminosa con Ena, la protagonista va madurando en silencio. Con una prosa intensa y sensorial, Laforet retrata la asfixia de la posguerra y la búsqueda de identidad de una joven. Una novela fundamental de la literatura española del siglo XX, fresca todavía hoy.","authorBio":"Carmen Laforet (1921–2004) fue una novelista española que ganó el primer Premio Nadal con esta obra. Su posterior conversión al catolicismo inspiró novelas como «La mujer nueva».","year":1945,"language":"español","pages":300,"tags":["posguerra","barcelona","juventud","familia","novela de formación","premio nadal"],"cover":"covers/nada.jpg","ratio":1.616,"color":"#d75762"},{"id":"el-jugador","shelf":53,"theme":"Narrativa","title":"El jugador","author":"Fiódor M. Dostoievski","sortKey":"Dostoievski","summary":"Alexéi Ivánovich, preceptor al servicio de un general ruso arruinado, vive en un balneario alemán pendiente de la herencia de una tía rica y enamorado sin remedio de la orgullosa Polina. La ruleta se convierte pronto en el centro de todo: promesa de salvación, humillación y vértigo. Dostoievski, que conoció de primera mano la ludopatía, escribió esta novela breve en pocas semanas, y en ella late una mirada lúcida sobre la esclavitud de las pasiones y la libertad perdida. Ágil, irónica y dolorosamente humana, es una puerta excelente al universo dostoievskiano.","authorBio":"Fiódor M. Dostoievski (1821–1881) fue un novelista ruso, autor de «Crimen y castigo» y «Los hermanos Karamázov». Su obra explora con hondura la libertad, el pecado, el sufrimiento y la fe.","year":1866,"originalTitle":"Игрок (Igrok)","language":"ruso","pages":200,"tags":["adicción","juego","pasiones","literatura rusa","amor","libertad"],"cover":"covers/el-jugador.jpg","ratio":1.429,"color":"#cb722f"},{"id":"la-suerte-esta-echada","shelf":54,"theme":"Narrativa","title":"La suerte está echada","author":"Jean-Paul Sartre","sortKey":"Sartre","summary":"Eva y Pierre mueren el mismo día en circunstancias muy distintas y, ya en el más allá, descubren que estaban destinados el uno al otro. Se les concede una segunda oportunidad: volver a la vida durante veinticuatro horas para demostrar que su amor puede vencer a todo. Pero las ataduras de clase, la política y los compromisos previos pesan más de lo que imaginaban. Concebida como guion cinematográfico, esta obra plantea con agilidad las preguntas sartreanas sobre la libertad y el determinismo. Un texto breve y sugerente para dialogar críticamente con el existencialismo ateo.","authorBio":"Jean-Paul Sartre (1905–1980) fue un filósofo, novelista y dramaturgo francés, principal figura del existencialismo ateo. Rechazó el Premio Nobel de Literatura en 1964.","year":1947,"originalTitle":"Les jeux sont faits","language":"francés","pages":150,"tags":["existencialismo","libertad","destino","amor","guion","muerte"],"ratio":1.5,"color":"#c54473"},{"id":"los-cantos-de-maldoror","shelf":55,"theme":"Poesía","title":"Los cantos de Maldoror","author":"Conde de Lautréamont","sortKey":"Lautréamont","summary":"Maldoror es un ser que ha declarado la guerra a Dios y a los hombres, y sus cantos recorren un paisaje de pesadilla poblado de océanos, piojos, tumbas y metamorfosis imposibles. Escrito en una prosa poética desbordante y deliberadamente perturbadora, este libro fue casi ignorado en su tiempo y después reivindicado por los surrealistas como precursor. Es una obra difícil y oscura, de imágenes violentas, que interesa sobre todo como documento literario de la rebelión romántica llevada al extremo. Para lectores con criterio, curiosos por las raíces de la poesía moderna.","authorBio":"Conde de Lautréamont es el seudónimo de Isidore Ducasse (1846–1870), poeta francés nacido en Montevideo. Murió muy joven en París, dejando una obra breve que influyó decisivamente en el surrealismo.","year":1869,"originalTitle":"Les Chants de Maldoror","language":"francés","pages":300,"tags":["poesía en prosa","surrealismo","romanticismo","rebeldía","mal","literatura francesa"],"cover":"covers/los-cantos-de-maldoror.jpg","ratio":1.502,"color":"#5d4f3f"},{"id":"historia-de-un-idiota-contada-por-el-mismo","shelf":56,"theme":"Narrativa","title":"Historia de un idiota contada por él mismo","author":"Félix de Azúa","sortKey":"Azúa","summary":"Un narrador sin nombre repasa su vida desde la infancia hasta la madurez con un único propósito: averiguar en qué consiste la felicidad. Familia, colegio, militancia política, amores, universidad y cultura van desfilando como intentos fallidos, contados con una ironía feroz y desengañada. Azúa escribe una sátira brillante de las ilusiones de su generación y de las promesas vacías de la modernidad. Breve, mordaz y muy divertida, su desencanto invita también a preguntarse dónde buscar de verdad una felicidad que no defraude.","authorBio":"Félix de Azúa (Barcelona, 1944) es novelista, poeta y ensayista español, catedrático de Estética y miembro de la Real Academia Española desde 2015.","year":1986,"language":"español","pages":130,"tags":["felicidad","sátira","ironía","generación","autobiografía ficticia","desencanto"],"cover":"covers/historia-de-un-idiota-contada-por-el-mismo.jpg","ratio":1.524,"color":"#84978d"},{"id":"san-manuel-bueno-martir","shelf":57,"theme":"Narrativa","title":"San Manuel Bueno, mártir","author":"Miguel de Unamuno","sortKey":"Unamuno","summary":"En la aldea de Valverde de Lucerna, Ángela Carballino recuerda a don Manuel, el párroco entregado sin descanso a sus feligreses, a quienes consuela, cuida y sostiene en la fe. Pero el sacerdote guarda un secreto doloroso: él mismo no logra creer en la vida eterna que predica. Unamuno condensa en esta novela corta su propia agonía religiosa, la tensión entre razón y fe, y la pregunta por el sentido del sufrimiento. Leída desde la fe católica, es un testimonio conmovedor de la sed de Dios y una invitación a pedir el don de creer.","authorBio":"Miguel de Unamuno (1864–1936) fue un escritor y filósofo español de la Generación del 98, rector de la Universidad de Salamanca. Su obra gira en torno a la fe, la inmortalidad y el sentido trágico de la vida.","year":1931,"language":"español","pages":120,"tags":["fe","duda","sacerdocio","inmortalidad","generación del 98","novela corta"],"cover":"covers/san-manuel-bueno-martir.jpg","ratio":1.414,"color":"#bdbdbd"},{"id":"elogio-de-la-locura","shelf":58,"theme":"Filosofía","title":"Elogio de la locura","author":"Erasmo de Rotterdam","sortKey":"Erasmo","summary":"La propia Locura sube a la tribuna y pronuncia un discurso en su honor: sin ella, asegura, nadie se casaría, nadie gobernaría y nadie sería feliz. Con ese ingenioso punto de partida, Erasmo despliega una sátira afilada contra la vanidad de reyes, sabios, teólogos y eclesiásticos de su tiempo, para terminar elogiando la «locura» de la cruz, la sabiduría humilde del Evangelio. Dedicado a su amigo Tomás Moro, es uno de los grandes textos del humanismo cristiano renacentista: divertido, irónico y sorprendentemente actual.","authorBio":"Erasmo de Rotterdam (c. 1466–1536) fue un sacerdote y humanista neerlandés, figura central del Renacimiento europeo. Defendió una reforma de la Iglesia basada en la vuelta a las fuentes y en la piedad interior.","year":1511,"originalTitle":"Moriae encomium","language":"latín","pages":200,"tags":["humanismo","sátira","renacimiento","humanismo cristiano","ironía","sabiduría"],"ratio":1.5,"color":"#777ab1"},{"id":"el-ultimo-dia-de-un-condenado-a-muerte","shelf":59,"theme":"Narrativa","title":"El último día de un condenado a muerte","author":"Victor Hugo","sortKey":"Hugo","summary":"Un hombre condenado a la guillotina escribe, en sus últimas semanas, el diario de su angustia: el juicio, la celda, el traslado, el recuerdo de su hija y la cuenta atrás hacia el cadalso. Victor Hugo omite deliberadamente su nombre y su delito para que el lector se enfrente sin excusas a la dignidad de una persona ante la muerte. Breve e intensísimo, este alegato contra la pena capital es también una meditación sobre la conciencia, el arrepentimiento y la misericordia. Un clásico que se lee de un tirón y deja huella.","authorBio":"Victor Hugo (1802–1885) fue un poeta, dramaturgo y novelista francés, cumbre del romanticismo y autor de «Los miserables» y «Nuestra Señora de París».","year":1829,"originalTitle":"Le Dernier Jour d'un condamné","language":"francés","pages":150,"tags":["pena de muerte","dignidad humana","justicia","romanticismo","conciencia","angustia"],"cover":"covers/el-ultimo-dia-de-un-condenado-a-muerte.jpg","ratio":1.502,"color":"#719361"},{"id":"fausto","shelf":60,"theme":"Teatro","title":"Fausto","author":"Johann Wolfgang von Goethe","sortKey":"Goethe","summary":"El doctor Fausto, sabio desengañado de todo conocimiento, sella un pacto con Mefistófeles: le entregará su alma si alguna vez llega a decir al instante «detente, eres tan bello». Comienza así un viaje por el amor, el poder y la ambición que arrastra a la inocente Margarita a la tragedia. Goethe trabajó en este drama durante casi toda su vida y lo convirtió en un gran poema sobre el anhelo humano de infinito, la tentación y la posibilidad de redención. Una de las cumbres de la literatura universal, densa y fascinante.","authorBio":"Johann Wolfgang von Goethe (1749–1832) fue un poeta, dramaturgo, novelista y científico alemán, figura central de la literatura alemana y del clasicismo de Weimar.","year":1808,"originalTitle":"Faust","language":"alemán","pages":500,"tags":["pacto con el diablo","ambición","redención","teatro en verso","clasicismo","tentación"],"cover":"covers/fausto.jpg","ratio":1.534,"color":"#b78c95"},{"id":"el-proceso","shelf":61,"theme":"Narrativa","title":"El proceso","author":"Franz Kafka","sortKey":"Kafka","summary":"Una mañana, Josef K., apoderado de un banco, es detenido sin haber hecho nada malo. Nadie le explica de qué se le acusa, pero el proceso avanza implacable a través de buhardillas convertidas en tribunales, abogados inútiles y funcionarios inaccesibles. Kafka construye una pesadilla absurda y a la vez inquietantemente reconocible sobre la culpa, la burocracia y la impotencia del individuo ante un poder anónimo. Publicada póstumamente, es una de las novelas más influyentes del siglo XX y una lectura que invita a pensar en la justicia y en la conciencia.","authorBio":"Franz Kafka (1883–1924) fue un escritor checo en lengua alemana, nacido en Praga. Sus relatos y novelas, en buena parte póstumos, dieron nombre a lo «kafkiano».","year":1925,"originalTitle":"Der Process","language":"alemán","pages":280,"tags":["absurdo","culpa","burocracia","justicia","angustia","literatura centroeuropea"],"ratio":1.5,"color":"#783f56"},{"id":"madame-bovary","shelf":62,"theme":"Narrativa","title":"Madame Bovary","author":"Gustave Flaubert","sortKey":"Flaubert","summary":"Emma, hija de un granjero normando educada entre novelas sentimentales, se casa con Charles Bovary, un médico rural bondadoso y gris. Pronto la vida de provincias le resulta insoportable y busca en el adulterio, el lujo y las deudas la pasión que había soñado. Flaubert narra su caída con un estilo de perfección casi científica, desmontando el romanticismo ingenuo y la mediocridad burguesa. Una novela fundacional del realismo moderno que muestra con lucidez cómo los deseos desordenados pueden destruir una vida y a quienes la rodean.","authorBio":"Gustave Flaubert (1821–1880) fue un novelista francés, maestro del realismo, célebre por su obsesión por la palabra exacta y el estilo impersonal.","year":1857,"originalTitle":"Madame Bovary","language":"francés","pages":450,"tags":["realismo","adulterio","matrimonio","provincias","insatisfacción","literatura francesa"],"cover":"covers/madame-bovary.jpg","ratio":1.748,"color":"#402f26"},{"id":"escupire-sobre-vuestra-tumba","shelf":63,"theme":"Narrativa","title":"Escupiré sobre vuestra tumba","author":"Boris Vian","sortKey":"Vian","summary":"Lee Anderson, un joven de origen mestizo que puede pasar por blanco, llega a un pueblo del sur de Estados Unidos decidido a vengar el linchamiento de su hermano. Su venganza, fría y brutal, se dirige contra dos hermanas de una familia acomodada. Vian publicó esta novela negra bajo el seudónimo de Vernon Sullivan, imitando el estilo de la novela policiaca americana, y provocó un enorme escándalo por su violencia y crudeza. Es un texto duro, de contenido explícito, que denuncia el racismo pero muestra también cómo el odio degrada a quien se entrega a él.","authorBio":"Boris Vian (1920–1959) fue un escritor, músico de jazz y traductor francés, figura de la vida cultural de Saint-Germain-des-Prés y autor de «La espuma de los días».","year":1946,"originalTitle":"J'irai cracher sur vos tombes","language":"francés","pages":170,"tags":["novela negra","racismo","venganza","violencia","estados unidos","escándalo"],"cover":"covers/escupire-sobre-vuestra-tumba.jpg","ratio":1.639,"color":"#756955"},{"id":"la-perla","shelf":64,"theme":"Narrativa","title":"La perla","author":"John Steinbeck","sortKey":"Steinbeck","summary":"Kino, un humilde pescador de perlas de la costa mexicana, encuentra la perla más grande jamás vista y cree que con ella podrá pagar el médico para su hijo y darle un futuro. Pero la riqueza repentina despierta la codicia de todos y desata sobre su familia una cadena de desgracias. Inspirada en una leyenda popular, esta novela breve tiene la sencillez y la fuerza de una parábola sobre la avaricia, la injusticia social y lo que de verdad vale en la vida. Ideal para leer y comentar en familia o en clase.","authorBio":"John Steinbeck (1902–1968) fue un novelista estadounidense, autor de «Las uvas de la ira» y «Al este del Edén». Recibió el Premio Nobel de Literatura en 1962.","year":1947,"originalTitle":"The Pearl","language":"inglés","pages":120,"tags":["parábola","codicia","pobreza","familia","méxico","injusticia"],"cover":"covers/la-perla.jpg","ratio":1.449,"color":"#5c708c"},{"id":"historia-universal-de-la-infamia","shelf":65,"theme":"Narrativa","title":"Historia universal de la infamia","author":"Jorge Luis Borges","sortKey":"Borges","summary":"Piratas, impostores, pistoleros, asesinos a sueldo y falsos profetas protagonizan estos relatos breves en los que Borges reescribe, con ironía y erudición juguetona, vidas de canallas reales o legendarios. Fue su primer libro de narraciones y en él ya aparecen el gusto por la falsa cita, la enciclopedia inventada y el estilo preciso que lo harían célebre. Entretenido y brillante, se lee como una galería de retratos de la maldad humana contada con distancia literaria. Una excelente entrada al mundo borgiano.","authorBio":"Jorge Luis Borges (1899–1986) fue un escritor argentino, maestro del cuento y del ensayo, autor de «Ficciones» y «El Aleph», y una de las grandes figuras de la literatura en español.","year":1935,"language":"español","pages":150,"tags":["cuentos","literatura argentina","infamia","ironía","biografías","erudición"],"cover":"covers/historia-universal-de-la-infamia.jpg","ratio":1.786,"color":"#323234"},{"id":"rayuela","shelf":66,"theme":"Narrativa","title":"Rayuela","author":"Julio Cortázar","sortKey":"Cortázar","summary":"Horacio Oliveira busca algo que no sabe nombrar entre las noches del París bohemio, junto a la Maga y los amigos del Club de la Serpiente, y más tarde en un Buenos Aires de circo y manicomio. La novela puede leerse de forma lineal o saltando de capítulo en capítulo siguiendo el «tablero de dirección» que propone el autor. Juego literario, reflexión sobre el lenguaje y búsqueda de un sentido que se escapa, «Rayuela» revolucionó la narrativa en español. Exigente y lúdica, es una experiencia de lectura única.","authorBio":"Julio Cortázar (1914–1984) fue un escritor argentino, maestro del relato fantástico y figura clave del boom latinoamericano. Vivió en París desde 1951.","year":1963,"language":"español","pages":600,"tags":["boom latinoamericano","novela experimental","parís","búsqueda de sentido","amor","juego"],"cover":"covers/rayuela.jpg","ratio":1.634,"color":"#333333"},{"id":"historias-de-cronopios-y-de-famas","shelf":67,"theme":"Narrativa","title":"Historias de cronopios y de famas","author":"Julio Cortázar","sortKey":"Cortázar","summary":"Un manual de instrucciones para llorar, para subir una escalera o para dar cuerda al reloj; y la descripción de tres extrañas especies: los cronopios, desordenados y poéticos; los famas, metódicos y prudentes; y las esperanzas, que se dejan estar. Con humor, ternura y una imaginación desbordante, Cortázar convierte la vida cotidiana en un territorio sorprendente. Son textos breves, perfectos para leer en voz alta y para recuperar la capacidad de mirar lo de siempre con ojos nuevos. Un libro alegre y lleno de ingenio.","authorBio":"Julio Cortázar (1914–1984) fue un escritor argentino, maestro del relato fantástico y figura clave del boom latinoamericano. Vivió en París desde 1951.","year":1962,"language":"español","pages":150,"tags":["relatos breves","humor","fantasía","cotidianidad","literatura argentina","imaginación"],"cover":"covers/historias-de-cronopios-y-de-famas.jpg","ratio":1.644,"color":"#e6e294"},{"id":"octaedro","shelf":68,"theme":"Narrativa","title":"Octaedro","author":"Julio Cortázar","sortKey":"Cortázar","summary":"Ocho cuentos componen este libro de madurez de Cortázar, en el que lo fantástico se insinúa con más discreción y el centro lo ocupan la memoria, la pérdida y la soledad. Hay relatos sobre un amor que regresa en sueños, sobre una casa que guarda un dolor antiguo o sobre la extraña fidelidad a un recuerdo. La prosa, precisa y envolvente, crea atmósferas inquietantes con muy pocos elementos. Una colección menos conocida que otras del autor, pero especialmente honda y conmovedora.","authorBio":"Julio Cortázar (1914–1984) fue un escritor argentino, maestro del relato fantástico y figura clave del boom latinoamericano. Vivió en París desde 1951.","year":1974,"language":"español","pages":180,"tags":["cuentos","literatura fantástica","memoria","pérdida","literatura argentina","soledad"],"cover":"covers/octaedro.jpg","ratio":1.632,"color":"#e6e694"},{"id":"el-arbol-de-la-ciencia","shelf":69,"theme":"Narrativa","title":"El árbol de la ciencia","author":"Pío Baroja","sortKey":"Baroja","summary":"Andrés Hurtado estudia Medicina en el Madrid de finales del siglo XIX y busca en la ciencia y en la filosofía una respuesta al sentido de la vida. Su recorrido —la facultad, los hospitales, un pueblo manchego, el matrimonio— es un desfile de mediocridad, dolor y desencanto, reflejo de una España en crisis. Baroja escribe con un estilo seco y directo una novela de ideas con fuerte carga autobiográfica. Su pesimismo invita a preguntarse si el conocimiento sin esperanza basta para vivir.","authorBio":"Pío Baroja (1872–1956) fue un novelista español de la Generación del 98, médico de formación, autor de una extensa obra narrativa de estilo sobrio y antirretórico.","year":1911,"language":"español","pages":300,"tags":["generación del 98","pesimismo","medicina","novela de ideas","sentido de la vida","españa"],"cover":"covers/el-arbol-de-la-ciencia.jpg","ratio":1.656,"color":"#bdbdbd"},{"id":"odisea","shelf":70,"theme":"Clásicos grecolatinos","title":"Odisea","author":"Homero","sortKey":"Homero","note":"Colección Austral, Espasa-Calpe","summary":"Terminada la guerra de Troya, Ulises emprende el regreso a Ítaca, donde su esposa Penélope resiste a los pretendientes y su hijo Telémaco sale en busca de noticias. Durante diez años el héroe se enfrenta a cíclopes, sirenas, hechiceras y dioses airados, y solo gracias a su astucia y su paciencia logra volver a casa. Uno de los poemas fundacionales de Occidente, la «Odisea» es un canto a la fidelidad, al hogar y a la nostalgia de la patria. Una aventura eterna que se relee siempre con gusto.","authorBio":"Homero es el poeta griego al que la tradición atribuye la «Ilíada» y la «Odisea», compuestas probablemente hacia el siglo VIII a. C. Su figura histórica sigue siendo objeto de debate.","originalTitle":"Ὀδύσσεια (Odýsseia)","language":"griego antiguo","pages":400,"tags":["epopeya","mitología griega","viaje","hogar","fidelidad","clásicos"],"cover":"covers/odisea.jpg","ratio":1.502,"color":"#d1b48c"},{"id":"don-quijote-de-la-mancha","shelf":71,"theme":"Narrativa","title":"Don Quijote de la Mancha","author":"Miguel de Cervantes","sortKey":"Cervantes","note":"Colección Austral, Espasa-Calpe","summary":"Un hidalgo manchego, de tanto leer libros de caballerías, decide hacerse caballero andante y salir a deshacer entuertos acompañado de su fiel escudero Sancho Panza. Sus aventuras, cómicas y entrañables, se convierten en una profunda reflexión sobre la realidad y la imaginación, la locura y la cordura, el ideal y sus límites. Considerada la primera novela moderna, es la obra cumbre de la lengua española y un tesoro de humor, humanidad y sabiduría. Cada etapa de la vida encuentra en ella algo nuevo.","authorBio":"Miguel de Cervantes (1547–1616) fue un novelista, poeta y dramaturgo español, soldado herido en Lepanto y cautivo en Argel, autor también de las «Novelas ejemplares».","year":1605,"language":"español","pages":1100,"tags":["siglo de oro","caballerías","humor","idealismo","novela moderna","clásicos"],"cover":"covers/don-quijote-de-la-mancha.jpg","ratio":1.538,"color":"#d2763e"},{"id":"la-iliada","shelf":72,"theme":"Clásicos grecolatinos","title":"La Ilíada","author":"Homero","sortKey":"Homero","note":"Editorial Moretón","summary":"En el décimo año del asedio de Troya, la cólera de Aquiles, ofendido por Agamenón, desata una cadena de desgracias entre griegos y troyanos. Héroes como Héctor, Patroclo o Ulises luchan bajo la mirada de unos dioses tan poderosos como caprichosos. Más que un relato bélico, la «Ilíada» es una meditación sobre el honor, la amistad, el dolor y la fragilidad de la vida humana, con escenas de una ternura inolvidable, como la despedida de Héctor y Andrómaca o la súplica de Príamo. La primera gran obra de la literatura europea.","authorBio":"Homero es el poeta griego al que la tradición atribuye la «Ilíada» y la «Odisea», compuestas probablemente hacia el siglo VIII a. C. Su figura histórica sigue siendo objeto de debate.","originalTitle":"Ἰλιάς (Iliás)","language":"griego antiguo","pages":500,"tags":["epopeya","guerra de troya","honor","mitología griega","heroísmo","clásicos"],"cover":"covers/la-iliada.jpg","ratio":1.558,"color":"#a5b436"},{"id":"la-eneida","shelf":73,"theme":"Clásicos grecolatinos","title":"La Eneida","author":"Virgilio","sortKey":"Virgilio","note":"Editorial Moretón","summary":"Tras la caída de Troya, Eneas huye con su padre a cuestas y su hijo de la mano, guiado por el destino de fundar una nueva patria en Italia. Su viaje lo lleva a Cartago y al amor trágico de Dido, al descenso a los infiernos y, finalmente, a la guerra en el Lacio. Virgilio compuso la gran epopeya de Roma con una sensibilidad melancólica y una profunda piedad, virtud que define a su héroe. Leída durante siglos por los cristianos, que veían en su autor un alma abierta a la esperanza, es un clásico esencial.","authorBio":"Publio Virgilio Marón (70–19 a. C.) fue el gran poeta latino de la época de Augusto, autor de las «Bucólicas», las «Geórgicas» y la «Eneida». Dante lo eligió como guía en la «Divina Comedia».","originalTitle":"Aeneis","language":"latín","pages":400,"tags":["epopeya","roma","piedad","destino","mitología","clásicos"],"cover":"covers/la-eneida.jpg","ratio":1.401,"color":"#47341f"},{"id":"el-senor-de-los-anillos-i-la-comunidad-del-anillo","shelf":74,"theme":"Narrativa","title":"El Señor de los Anillos I. La Comunidad del Anillo","author":"J. R. R. Tolkien","sortKey":"Tolkien","summary":"El hobbit Frodo hereda de su tío Bilbo un anillo aparentemente inofensivo que resulta ser el Anillo Único, forjado por el Señor Oscuro Sauron para dominarlo todo. Para destruirlo, deberá dejar la apacible Comarca y emprender un viaje peligroso junto a una compañía de hobbits, hombres, un elfo, un enano y el mago Gandalf. Esta primera parte de la gran epopeya de Tolkien, profundamente católica en su fondo, habla de la amistad, la humildad, la misericordia y la tentación del poder. Una obra maestra que no envejece.","authorBio":"J. R. R. Tolkien (1892–1973) fue un filólogo y escritor británico, católico ferviente y profesor en Oxford, creador del universo de la Tierra Media.","year":1954,"originalTitle":"The Fellowship of the Ring","language":"inglés","pages":550,"tags":["fantasía épica","amistad","tierra media","poder","misericordia","aventura"],"ratio":1.5,"color":"#913930"},{"id":"el-senor-de-los-anillos-ii-las-dos-torres","shelf":75,"theme":"Narrativa","title":"El Señor de los Anillos II. Las dos torres","author":"J. R. R. Tolkien","sortKey":"Tolkien","summary":"Rota la Compañía, sus miembros siguen caminos distintos: Aragorn, Legolas y Gimli persiguen a los orcos que han capturado a Merry y Pippin, mientras Frodo y Sam avanzan hacia Mordor guiados por la ambigua criatura Gollum. Entre la batalla del Abismo de Helm, el despertar de los ents y la compasión de Frodo hacia Gollum, Tolkien profundiza en el valor de la fidelidad y en la lucha interior contra el mal. La segunda parte de la saga gana en tensión y en hondura moral. Imprescindible.","authorBio":"J. R. R. Tolkien (1892–1973) fue un filólogo y escritor británico, católico ferviente y profesor en Oxford, creador del universo de la Tierra Media.","year":1954,"originalTitle":"The Two Towers","language":"inglés","pages":450,"tags":["fantasía épica","fidelidad","tierra media","compasión","lucha contra el mal","aventura"],"ratio":1.5,"color":"#c05d80"},{"id":"el-senor-de-los-anillos-iii-el-retorno-del-rey","shelf":76,"theme":"Narrativa","title":"El Señor de los Anillos III. El retorno del rey","author":"J. R. R. Tolkien","sortKey":"Tolkien","summary":"La guerra del Anillo llega a su desenlace: Gondor resiste el asedio de las fuerzas de Sauron, Aragorn asume su destino de rey y Frodo y Sam, exhaustos, alcanzan por fin el Monte del Destino. Tolkien cierra su epopeya con escenas grandiosas y, sobre todo, con una reflexión profunda sobre la gracia, el sacrificio y la eucatástrofe, ese giro inesperado del bien que él relacionaba con el Evangelio. El regreso a la Comarca añade una nota melancólica y verdadera. Un final que conmueve a cada relectura.","authorBio":"J. R. R. Tolkien (1892–1973) fue un filólogo y escritor británico, católico ferviente y profesor en Oxford, creador del universo de la Tierra Media.","year":1955,"originalTitle":"The Return of the King","language":"inglés","pages":450,"tags":["fantasía épica","sacrificio","gracia","tierra media","realeza","esperanza"],"ratio":1.5,"color":"#b1686b"},{"id":"el-silmarillion","shelf":77,"theme":"Narrativa","title":"El Silmarillion","author":"J. R. R. Tolkien","sortKey":"Tolkien","summary":"Antes de los hechos de «El Señor de los Anillos» está la historia de los Días Antiguos: la creación del mundo a partir de la música de Ilúvatar, la rebelión de Melkor, el robo de los Silmarils y las largas guerras de los elfos contra la oscuridad. Editado por Christopher Tolkien a partir de los manuscritos de su padre, este libro reúne la mitología completa de la Tierra Media con un tono solemne, casi bíblico. Exige paciencia, pero recompensa con relatos inolvidables como el de Beren y Lúthien.","authorBio":"J. R. R. Tolkien (1892–1973) fue un filólogo y escritor británico, católico ferviente y profesor en Oxford, creador del universo de la Tierra Media.","year":1977,"originalTitle":"The Silmarillion","language":"inglés","pages":450,"tags":["mitología","creación","tierra media","elfos","fantasía épica","caída"],"ratio":1.5,"color":"#783026"},{"id":"alicia-en-el-pais-de-las-maravillas","shelf":78,"theme":"Narrativa","title":"Alicia en el País de las Maravillas","author":"Lewis Carroll","sortKey":"Carroll","summary":"Una tarde de verano, Alicia sigue a un conejo blanco con chaleco y reloj, cae por su madriguera y llega a un mundo donde nada obedece a la lógica: crece y encoge, conversa con un gato que sonríe y desaparece, asiste a una merienda de locos y juega al cróquet con una reina furiosa. Carroll, matemático y amante de los juegos de palabras, creó un cuento lleno de humor, absurdo e ingenio que encanta a niños y fascina a adultos. Un clásico para leer en familia.","authorBio":"Lewis Carroll, seudónimo de Charles Lutwidge Dodgson (1832–1898), fue un escritor, matemático y diácono anglicano británico, profesor en Oxford.","year":1865,"originalTitle":"Alice's Adventures in Wonderland","language":"inglés","pages":180,"tags":["literatura infantil","fantasía","absurdo","juegos de palabras","imaginación","clásicos"],"cover":"covers/alicia-en-el-pais-de-las-maravillas.jpg","ratio":1.502,"color":"#251e48"},{"id":"dante-poeta-del-deseo","shelf":79,"theme":"Poesía","title":"Dante, poeta del deseo","author":"Franco Nembrini","sortKey":"Nembrini","summary":"Franco Nembrini, profesor y educador italiano, lleva años recorriendo aulas y teatros para contar la «Divina Comedia» como lo que es: el camino de un hombre que busca la felicidad y descubre que su deseo solo se sacia en Dios. Con un tono cercano y apasionado, comenta los cantos más significativos, los relaciona con la experiencia cotidiana y muestra la actualidad de Dante para cualquier lector. La obra se publicó en tres volúmenes (Infierno, Purgatorio y Paraíso). Una guía espléndida para acercarse a Dante desde la fe y la vida.","authorBio":"Franco Nembrini (Trescore Balneario, 1955) es un educador y escritor italiano, fundador del centro escolar La Traccia y difusor incansable de la obra de Dante, ligado al movimiento Comunión y Liberación.","year":2011,"originalTitle":"Dante, poeta del desiderio","language":"italiano","pages":220,"tags":["dante","divina comedia","deseo","educación","fe","literatura italiana"],"ratio":1.5,"color":"#7e5c9d"},{"id":"yo-siempre-vi-un-sombrero","shelf":80,"theme":"Narrativa","title":"Yo siempre vi un sombrero","author":"Álvaro Abellán-García Barrio","sortKey":"Abellán-García","summary":"Partiendo del célebre dibujo de la boa que digiere un elefante, que los adultos confunden con un sombrero, este libro propone una relectura atenta de «El Principito» de Saint-Exupéry. El autor ofrece claves para interpretar sus símbolos —la rosa, el zorro, el aviador, los planetas— y pregunta al lector si de verdad lo esencial es invisible a los ojos. Escrito para los «mayores» que han olvidado mirar la realidad con asombro, es un ensayo sencillo y sugerente sobre la amistad, el amor y el sentido de la vida.","authorBio":"Álvaro Abellán-García Barrio es periodista, doctor en Humanidades y profesor e investigador de la Universidad Francisco de Vitoria, donde trabaja en comunicación, antropología y escritura creativa.","year":2022,"language":"español","tags":["el principito","saint-exupéry","asombro","amistad","sentido de la vida","ensayo literario"],"cover":"covers/yo-siempre-vi-un-sombrero.jpg","ratio":1.408,"color":"#3c3f6c"},{"id":"historia-del-pensamiento-filosofico-y-cientifico-i","shelf":81,"theme":"Filosofía","title":"Historia del pensamiento filosófico y científico I","author":"Giovanni Reale y Dario Antiseri","sortKey":"Reale","summary":"Primer volumen de un manual ya clásico que recorre la historia de la filosofía desde los presocráticos hasta el final de la Edad Media. Reale y Antiseri exponen con claridad a Sócrates, Platón, Aristóteles, las escuelas helenísticas, los Padres de la Iglesia, san Agustín y santo Tomás, prestando atención también al desarrollo de la ciencia. Cada capítulo se completa con esquemas, textos de los autores y una presentación rigurosa pero accesible. Una obra de consulta excelente para estudiantes y para cualquier lector que quiera conocer las raíces del pensamiento occidental.","authorBio":"Giovanni Reale (1931–2014) fue un historiador de la filosofía antigua italiano, gran estudioso de Platón; Dario Antiseri (1940) es un filósofo y epistemólogo italiano, especialista en Popper.","year":1983,"originalTitle":"Il pensiero occidentale dalle origini ad oggi","language":"italiano","pages":600,"tags":["historia de la filosofía","filosofía antigua","filosofía medieval","ciencia","manual","pensamiento occidental"],"ratio":1.5,"color":"#3749a4"},{"id":"historia-del-pensamiento-filosofico-y-cientifico-ii","shelf":82,"theme":"Filosofía","title":"Historia del pensamiento filosófico y científico II","author":"Giovanni Reale y Dario Antiseri","sortKey":"Reale","summary":"El segundo volumen abarca desde el humanismo renacentista hasta Kant, la época en que nace la ciencia moderna y la filosofía se reorganiza en torno al problema del conocimiento. Galileo, Descartes, Pascal, Spinoza, Leibniz, los empiristas británicos y la Ilustración desfilan con la claridad y el equilibrio característicos de los autores. La atención constante a la revolución científica convierte este tomo en una guía valiosa para entender cómo se forjó la mentalidad moderna. Útil tanto para el estudio sistemático como para la consulta puntual.","authorBio":"Giovanni Reale (1931–2014) fue un historiador de la filosofía antigua italiano, gran estudioso de Platón; Dario Antiseri (1940) es un filósofo y epistemólogo italiano, especialista en Popper.","year":1983,"originalTitle":"Il pensiero occidentale dalle origini ad oggi","language":"italiano","pages":800,"tags":["historia de la filosofía","renacimiento","revolución científica","racionalismo","ilustración","manual"],"ratio":1.5,"color":"#6c85a7"},{"id":"historia-del-pensamiento-filosofico-y-cientifico-iii","shelf":83,"theme":"Filosofía","title":"Historia del pensamiento filosófico y científico III","author":"Giovanni Reale y Dario Antiseri","sortKey":"Reale","summary":"El tercer volumen recorre el pensamiento desde el romanticismo y el idealismo alemán hasta las corrientes del siglo XX: Hegel, Kierkegaard, Marx, Nietzsche, el positivismo, la fenomenología, el existencialismo, la filosofía analítica y la epistemología contemporánea. Reale y Antiseri ofrecen una síntesis rigurosa y bien documentada de un periodo complejo, sin renunciar a una mirada crítica atenta a la cuestión de la verdad y de la persona. Una herramienta muy útil para orientarse en el panorama intelectual que ha configurado nuestro tiempo.","authorBio":"Giovanni Reale (1931–2014) fue un historiador de la filosofía antigua italiano, gran estudioso de Platón; Dario Antiseri (1940) es un filósofo y epistemólogo italiano, especialista en Popper.","year":1983,"originalTitle":"Il pensiero occidentale dalle origini ad oggi","language":"italiano","pages":1000,"tags":["historia de la filosofía","filosofía contemporánea","idealismo","existencialismo","epistemología","manual"],"ratio":1.5,"color":"#6064a4"},{"id":"la-tarea-de-ser-mejor-curso-de-etica","shelf":84,"theme":"Filosofía","title":"La tarea de ser mejor. Curso de ética","author":"José Ángel Agejas (coord.), José Luis Parada e Isaac Oliver","sortKey":"Agejas","note":"Autor por confirmar","summary":"Manual de ética concebido para los estudiantes de la Universidad Francisco de Vitoria, con la intención de integrar la reflexión moral en la formación de cualquier carrera. Parte de una base antropológica: para saber cómo actuar bien es necesario comprender quién es la persona y hacia dónde se orienta. A partir de ahí desarrolla la dinámica del crecimiento personal, las virtudes y la idea de una vida lograda. Claro y didáctico, presenta la ética no como un listado de normas, sino como la tarea apasionante de llegar a ser mejores.","authorBio":"José Ángel Agejas Esteban es doctor en Filosofía y profesor de la Universidad Francisco de Vitoria, donde ha coordinado la enseñanza de ética y humanidades junto a José Luis Parada e Isaac Oliver.","year":2007,"language":"español","pages":268,"tags":["ética","virtudes","antropología","persona","manual universitario","vida lograda"],"cover":"covers/la-tarea-de-ser-mejor-curso-de-etica.jpg","ratio":1.582,"color":"#77adcf"},{"id":"historia-sencilla-de-la-filosofia","shelf":85,"theme":"Filosofía","title":"Historia sencilla de la filosofía","author":"Rafael Gambra","sortKey":"Gambra","summary":"Rafael Gambra escribió este libro pensando en jóvenes que se acercan por primera vez a la filosofía, y lo logró con creces: con un lenguaje llano y ejemplos cercanos, recorre los grandes sistemas desde los presocráticos hasta el siglo XX. Su perspectiva es la del realismo clásico de raíz aristotélico-tomista, lo que le permite valorar y criticar con claridad las distintas corrientes. Lleva décadas reeditándose y sigue siendo una de las mejores introducciones en español para estudiantes y lectores curiosos.","authorBio":"Rafael Gambra Ciudad (1920–2004) fue un filósofo español, catedrático de instituto, pensador tradicionalista y católico, autor de obras como «El silencio de Dios».","year":1961,"language":"español","pages":300,"tags":["historia de la filosofía","introducción","tomismo","realismo","divulgación","jóvenes"],"cover":"covers/historia-sencilla-de-la-filosofia.jpg","ratio":1.502,"color":"#693c35"},{"id":"historia-de-las-ideas-contemporaneas","shelf":86,"theme":"Filosofía","title":"Historia de las ideas contemporáneas","author":"Mariano Fazio","sortKey":"Fazio","summary":"Mariano Fazio propone una lectura de la modernidad como un gran movimiento de secularización: desde la Ilustración hasta la posmodernidad, pasando por el liberalismo, el romanticismo, el nacionalismo, el marxismo o el nihilismo. Junto a estas corrientes presenta también las respuestas cristianas y los pensadores que han defendido la dignidad de la persona. Con estilo claro y riguroso, el libro ayuda a entender de dónde vienen muchas ideas que hoy damos por supuestas. Muy recomendable para quien desee comprender la cultura actual desde una perspectiva católica.","authorBio":"Mariano Fazio (Buenos Aires, 1960) es sacerdote, historiador y filósofo argentino. Fue rector de la Pontificia Universidad de la Santa Cruz y es vicario auxiliar del Opus Dei.","year":2006,"language":"español","pages":450,"tags":["historia de las ideas","modernidad","secularización","ideologías","pensamiento cristiano","cultura contemporánea"],"ratio":1.5,"color":"#5d60c6"},{"id":"filosofia-minima","shelf":87,"theme":"Filosofía","title":"Filosofía mínima","author":"José Ramón Ayllón","sortKey":"Ayllón","summary":"José Ramón Ayllón escribió este libro para alumnos de bachillerato, pero su estilo coloquial y ameno lo hace atractivo para cualquier lector. En capítulos breves aborda las grandes cuestiones: la verdad, la ciencia, el origen del hombre, la libertad, el trabajo, el arte, la cultura y las formas de gobierno. Combina argumentos, anécdotas, citas literarias y ejemplos cotidianos con una visión humanista de fondo cristiano. Una excelente puerta de entrada a la filosofía para jóvenes, padres y profesores.","authorBio":"José Ramón Ayllón (Cantabria, 1955) es profesor, escritor y conferenciante español, autor de numerosos libros de divulgación filosófica, ética y literatura para jóvenes.","year":2001,"language":"español","pages":326,"tags":["introducción a la filosofía","bachillerato","libertad","verdad","divulgación","jóvenes"],"cover":"covers/filosofia-minima.jpg","ratio":1.563,"color":"#bdbdbd"},{"id":"etica-aplicada-y-democracia-radical","shelf":88,"theme":"Filosofía","title":"Ética aplicada y democracia radical","author":"Adela Cortina","sortKey":"Cortina","summary":"Adela Cortina reflexiona sobre cómo fundamentar una ética común en sociedades plurales y democráticas. Desde la ética del discurso de Apel y Habermas, propone una «democracia radical» en la que todos los afectados puedan participar en las decisiones, y desarrolla el campo de las éticas aplicadas: empresa, medicina, ecología, medios de comunicación. Es un libro académico, de lectura exigente, útil para conocer uno de los enfoques más influyentes de la ética civil en España y para dialogar con él desde otras tradiciones filosóficas.","authorBio":"Adela Cortina (Valencia, 1947) es catedrática emérita de Ética y Filosofía Política de la Universidad de Valencia y miembro de la Real Academia de Ciencias Morales y Políticas.","year":1993,"language":"español","pages":280,"tags":["ética aplicada","democracia","ética del discurso","bioética","ética civil","pluralismo"],"cover":"covers/etica-aplicada-y-democracia-radical.jpg","ratio":1.572,"color":"#681922"},{"id":"explicame-la-persona","shelf":89,"theme":"Filosofía","title":"Explícame la persona","author":"Ramón Lucas Lucas","sortKey":"Lucas","summary":"¿Quién soy? ¿Qué sentido tienen la vida, la muerte, el sufrimiento o la libertad? Ramón Lucas Lucas ofrece aquí una antropología filosófica «para todos», escrita con lenguaje claro y acompañada de esquemas y dibujos que facilitan la comprensión. Recorre la vida, el conocimiento, la voluntad, la afectividad, la sexualidad, la corporeidad y la apertura a la trascendencia, desde la tradición realista y personalista. Un libro muy útil como introducción para estudiantes y para quien desee conocerse mejor a sí mismo.","authorBio":"Ramón Lucas Lucas es sacerdote español de los Legionarios de Cristo, profesor de antropología filosófica y bioética en la Pontificia Universidad Gregoriana de Roma y autor de «Bioética para todos».","year":2010,"language":"español","pages":287,"tags":["antropología filosófica","persona","sentido de la vida","libertad","trascendencia","divulgación"],"cover":"covers/explicame-la-persona.jpg","ratio":1.416,"color":"#dad25f"},{"id":"vertigo-y-extasis","shelf":90,"theme":"Filosofía","title":"Vértigo y éxtasis","author":"Alfonso López Quintás","sortKey":"López Quintás","summary":"López Quintás distingue dos caminos opuestos en la vida humana: el vértigo, la fascinación que promete plenitud inmediata pero conduce a la decepción y al vacío, y el éxtasis, el proceso creativo de encuentro con las personas, los valores y Dios, que exige generosidad y fidelidad. Con ejemplos tomados de la literatura, la música y la experiencia cotidiana, el autor muestra cómo solo el encuentro genera auténtica libertad y madurez. Un libro formativo, de gran valor para educadores, padres y jóvenes.","authorBio":"Alfonso López Quintás (Franza, La Coruña, 1928) es un filósofo español, catedrático emérito de Estética de la Universidad Complutense y académico de Ciencias Morales y Políticas, creador de la teoría del encuentro.","language":"español","pages":300,"tags":["encuentro","creatividad","libertad interior","valores","manipulación","formación"],"ratio":1.5,"color":"#6884c0"},{"id":"el-secuestro-del-lenguaje","shelf":91,"theme":"Filosofía","title":"El secuestro del lenguaje","author":"Alfonso López Quintás","sortKey":"López Quintás","summary":"Las palabras pueden servir para el encuentro o para la manipulación. En este ensayo, López Quintás desmonta las tácticas con que se secuestra el lenguaje para dominar a las personas: términos talismán, eufemismos, planteamientos dilemáticos y estrategias de confusión que impiden pensar con libertad. Con numerosos ejemplos tomados del debate público, enseña a detectar estos mecanismos y a recuperar un uso del lenguaje al servicio de la verdad. Una lectura muy práctica en tiempos de propaganda y polarización.","authorBio":"Alfonso López Quintás (Franza, La Coruña, 1928) es un filósofo español, catedrático emérito de Estética de la Universidad Complutense y académico de Ciencias Morales y Políticas, creador de la teoría del encuentro.","language":"español","pages":200,"tags":["manipulación","lenguaje","pensamiento crítico","verdad","propaganda","libertad"],"ratio":1.5,"color":"#556391"},{"id":"mundus","shelf":92,"theme":"Filosofía","title":"Mundus","author":"Higinio Marín","sortKey":"Marín","summary":"Higinio Marín reúne en esta obra madura décadas de reflexión sobre el ser humano y la cultura. Su tesis central es que el mundo es lo que le sucede al universo físico cuando el hombre está presente en él: el espacio en el que la existencia humana se despliega. Con el subtítulo «Una arqueología filosófica de la existencia», el libro examina el mundo como existencia y como presencia, recorriendo la casa, el cuerpo, la palabra, el trabajo o la memoria. Un ensayo denso y original para lectores con formación filosófica.","authorBio":"Higinio Marín (1965) es catedrático de Antropología Filosófica en la Universidad CEU Cardenal Herrera, autor de ensayos sobre el hombre y la cultura como «Teoría de la cordura» o «Civismo y ciudadanía».","year":2019,"language":"español","pages":494,"tags":["antropología filosófica","filosofía de la cultura","existencia","mundo","ensayo","persona"],"cover":"covers/mundus.jpg","ratio":1.401,"color":"#bdbdbd"},{"id":"gnoseologia","shelf":93,"theme":"Filosofía","title":"Gnoseología","author":"Alejandro Llano","sortKey":"Llano","summary":"Manual universitario de teoría del conocimiento escrito desde la tradición realista. Alejandro Llano estudia qué significa conocer, cómo se relacionan el pensamiento y la realidad, qué es la verdad y cómo responder al escepticismo y al idealismo moderno. Dialoga con Aristóteles, santo Tomás, Kant y la filosofía contemporánea con rigor y claridad. Forma parte de la colección de manuales de filosofía de la editorial EUNSA y se ha convertido en una referencia para estudiantes que buscan fundamentar sólidamente la confianza en la razón.","authorBio":"Alejandro Llano (1943–2024) fue un filósofo español, catedrático de Metafísica y rector de la Universidad de Navarra, uno de los grandes referentes del pensamiento realista en España.","year":1983,"language":"español","pages":200,"tags":["teoría del conocimiento","verdad","realismo","metafísica","manual universitario","tomismo"],"cover":"covers/gnoseologia.jpg","ratio":1.475,"color":"#a32632"},{"id":"sobre-dios","shelf":94,"theme":"Filosofía","title":"Sobre Dios","author":"Byung-Chul Han","sortKey":"Han","summary":"Byung-Chul Han se acerca a la cuestión de Dios de la mano de Simone Weil, sin pretender una teología sistemática. Diagnostica por qué la experiencia religiosa se ha vuelto tan difícil hoy: la saturación del yo, el ruido informativo, la pérdida del silencio y de la atención. Frente a ello, recupera con Weil la idea de un Dios que se manifiesta en la retirada y en la atención desnuda, y la necesidad de vaciarse para acoger al otro. Un ensayo breve y sugerente que abre preguntas valiosas para el lector creyente.","authorBio":"Byung-Chul Han (Seúl, 1959) es un filósofo surcoreano afincado en Alemania, profesor en la Universidad de las Artes de Berlín y autor de ensayos breves sobre la sociedad contemporánea; recibió el Premio Princesa de Asturias en 2025.","year":2025,"originalTitle":"Sprechen über Gott. Ein Dialog mit Simone Weil","language":"alemán","pages":144,"tags":["dios","simone weil","atención","silencio","trascendencia","crítica cultural"],"cover":"covers/sobre-dios.jpg","ratio":1.553,"color":"#5b6e5e"},{"id":"vida-contemplativa","shelf":95,"theme":"Filosofía","title":"Vida contemplativa","author":"Byung-Chul Han","sortKey":"Han","summary":"En una sociedad obsesionada con el rendimiento y la productividad, Byung-Chul Han reivindica el valor de la inactividad, que no es pereza sino la capacidad de detenerse, demorarse y contemplar. Apoyándose en la tradición filosófica y también en la mística cristiana, muestra que sin ese espacio de quietud la vida se convierte en mera supervivencia y se pierde el sentido de la fiesta, del juego y de lo sagrado. Un ensayo breve, lúcido y muy oportuno para recuperar el descanso y la dimensión contemplativa de la existencia.","authorBio":"Byung-Chul Han (Seúl, 1959) es un filósofo surcoreano afincado en Alemania, profesor en la Universidad de las Artes de Berlín y autor de ensayos breves sobre la sociedad contemporánea; recibió el Premio Princesa de Asturias en 2025.","year":2022,"originalTitle":"Vita contemplativa. Oder von der Untätigkeit","language":"alemán","pages":130,"tags":["contemplación","descanso","sociedad del rendimiento","silencio","crítica cultural","sentido"],"ratio":1.5,"color":"#364d8c"},{"id":"la-desaparicion-de-los-rituales","shelf":96,"theme":"Filosofía","title":"La desaparición de los rituales","author":"Byung-Chul Han","sortKey":"Han","summary":"Los rituales son, para Byung-Chul Han, técnicas simbólicas que nos dan un hogar en el tiempo y nos vinculan a una comunidad. Su desaparición en la sociedad actual, dominada por la producción, la autenticidad narcisista y la comunicación incesante, nos deja aislados y sin raíces. El autor examina el valor de la repetición, la fiesta, el juego, la cortesía o el silencio frente a la lógica del consumo. Un ensayo breve y penetrante que ilumina también el sentido profundo de la liturgia y de las tradiciones compartidas.","authorBio":"Byung-Chul Han (Seúl, 1959) es un filósofo surcoreano afincado en Alemania, profesor en la Universidad de las Artes de Berlín y autor de ensayos breves sobre la sociedad contemporánea; recibió el Premio Princesa de Asturias en 2025.","year":2019,"originalTitle":"Vom Verschwinden der Rituale. Eine Topologie der Gegenwart","language":"alemán","pages":120,"tags":["rituales","comunidad","tradición","fiesta","narcisismo","crítica cultural"],"ratio":1.5,"color":"#5b6a9f"},{"id":"el-espiritu-de-la-esperanza","shelf":97,"theme":"Filosofía","title":"El espíritu de la esperanza","author":"Byung-Chul Han","sortKey":"Han","summary":"Vivimos, dice Byung-Chul Han, en una sociedad del miedo, donde las crisis se suceden y el futuro se percibe como amenaza. Frente al optimismo superficial y al pensamiento positivo, el autor propone la esperanza como una actitud profunda que abre horizontes, impulsa a actuar y nos une a los demás. Dialogando con filósofos, poetas y pensadores religiosos, describe la esperanza como un movimiento del espíritu que trasciende lo dado. Un ensayo luminoso y necesario que conecta de forma natural con la virtud teologal de la esperanza.","authorBio":"Byung-Chul Han (Seúl, 1959) es un filósofo surcoreano afincado en Alemania, profesor en la Universidad de las Artes de Berlín y autor de ensayos breves sobre la sociedad contemporánea; recibió el Premio Princesa de Asturias en 2025.","year":2023,"originalTitle":"Der Geist der Hoffnung. Wider die Gesellschaft der Angst","language":"alemán","pages":140,"tags":["esperanza","miedo","futuro","espíritu","crítica cultural","sentido"],"ratio":1.5,"color":"#3e68ac"},{"id":"el-arte-de-pensar","shelf":98,"theme":"Filosofía","title":"El arte de pensar","author":"José Carlos Ruiz","sortKey":"Ruiz","summary":"José Carlos Ruiz invita a cultivar el pensamiento crítico como una herramienta para vivir mejor. En una época de estímulos constantes, opiniones prefabricadas y prisa, propone aprender a interpretar el contexto, cuestionar lo que damos por supuesto y tomar decisiones con criterio propio. Con un estilo cercano y ejemplos cotidianos, acerca ideas de la tradición filosófica a la vida diaria, la educación y las relaciones personales. Un ensayo divulgativo de gran éxito, útil para quien quiere pensar por sí mismo.","authorBio":"José Carlos Ruiz es doctor en Filosofía y profesor de la Universidad de Córdoba, especializado en pensamiento crítico y divulgación filosófica.","year":2018,"language":"español","pages":288,"tags":["pensamiento crítico","divulgación","educación","sociedad actual","criterio","filosofía práctica"],"cover":"covers/el-arte-de-pensar.jpg","ratio":1.529,"color":"#b52a37"},{"id":"el-hombre-espiritu-encarnado","shelf":99,"theme":"Filosofía","title":"El hombre, espíritu encarnado","author":"Ramón Lucas Lucas","sortKey":"Lucas","summary":"Este manual de antropología filosófica estudia al ser humano como unidad de cuerpo y espíritu. Ramón Lucas Lucas recorre la vida, la corporeidad, el conocimiento, la libertad, la afectividad, la sociabilidad y la apertura a Dios, dialogando con la tradición clásica y con el personalismo contemporáneo. Su enfoque realista y cristiano permite comprender la dignidad única de cada persona y fundamentar después la ética y la bioética. Riguroso y bien estructurado, es un texto muy usado en universidades y seminarios.","authorBio":"Ramón Lucas Lucas es sacerdote español de los Legionarios de Cristo, profesor de antropología filosófica y bioética en la Pontificia Universidad Gregoriana de Roma y autor de «Bioética para todos».","year":1993,"originalTitle":"L'uomo, spirito incarnato","language":"italiano","pages":380,"tags":["antropología filosófica","persona","cuerpo y alma","dignidad humana","manual universitario","personalismo"],"cover":"covers/el-hombre-espiritu-encarnado.jpg","ratio":1.543,"color":"#b9c8b1"},{"id":"humanismo-integral","shelf":100,"theme":"Filosofía","title":"Humanismo integral","author":"Jacques Maritain","sortKey":"Maritain","summary":"Ante el humanismo ateo y los totalitarismos de su tiempo, Jacques Maritain propone un humanismo integral o teocéntrico, que reconoce al hombre en todas sus dimensiones, incluida su vocación sobrenatural. Analiza la tragedia del humanismo moderno y esboza el ideal histórico de una nueva cristiandad: una sociedad pluralista, respetuosa con la libertad y la dignidad de la persona, inspirada en el Evangelio sin confundir lo temporal y lo espiritual. Una obra clave del pensamiento social católico del siglo XX.","authorBio":"Jacques Maritain (1882–1973) fue un filósofo francés converso al catolicismo, renovador del tomismo e influyente en la redacción de la Declaración Universal de los Derechos Humanos.","year":1936,"originalTitle":"Humanisme intégral","language":"francés","pages":300,"tags":["humanismo cristiano","filosofía política","persona","tomismo","nueva cristiandad","doctrina social"],"cover":"covers/humanismo-integral.jpg","ratio":1.618,"color":"#1f5685"},{"id":"horizonte-vertical","shelf":101,"theme":"Filosofía","title":"Horizonte vertical","author":"Ramón Lucas Lucas","sortKey":"Lucas","summary":"Un tratado de antropología filosófica que se pregunta, sin rodeos, qué es el hombre y hacia dónde apunta su existencia. Ramón Lucas recorre las grandes dimensiones de la persona —corporeidad, conocimiento, libertad, afectividad, relación con los demás, sexualidad, trabajo, cultura y muerte— para mostrar que el ser humano no se agota en lo horizontal: está abierto a la trascendencia. Escrito con claridad didáctica y apoyado en la tradición clásica y cristiana, sin ignorar a los pensadores modernos, es un manual excelente para quien busca una visión integral y esperanzada de la persona y de su dignidad.","authorBio":"Ramón Lucas Lucas es sacerdote y filósofo español, profesor de antropología filosófica y bioética en universidades pontificias de Roma y autor de numerosos manuales sobre la persona humana.","year":2008,"language":"español","pages":400,"tags":["antropología filosófica","persona","trascendencia","libertad","dignidad humana","sentido de la vida"],"ratio":1.5,"color":"#292376"},{"id":"la-sombra-del-padre","shelf":102,"theme":"Narrativa","title":"La sombra del Padre","author":"Jan Dobraczyński","sortKey":"Dobraczyński","summary":"Novela sobre san José, el hombre silencioso del Evangelio. Dobraczyński imagina con hondura psicológica y rigor histórico la vida del carpintero de Nazaret: su amor por María, la desconcertante noticia de su maternidad, la huida a Egipto, los años ocultos criando a Jesús. José aparece como un hombre de carne y hueso que duda, sufre y obedece, y que aprende a ser padre de un Hijo que no es suyo. Una lectura conmovedora que ilumina la paternidad, la fe que confía sin entender del todo y la grandeza de las vidas sencillas entregadas a Dios.","authorBio":"Jan Dobraczyński (1910-1994) fue un novelista católico polaco, autor de célebres novelas de tema bíblico e histórico, reconocido como Justo entre las Naciones por salvar a niños judíos durante la ocupación nazi.","year":1977,"originalTitle":"Cień Ojca","language":"polaco","pages":380,"tags":["san josé","novela bíblica","paternidad","sagrada familia","fe","nazaret"],"cover":"covers/la-sombra-del-padre.jpg","ratio":1.592,"color":"#442d22"},{"id":"canon-inverso","shelf":103,"theme":"Narrativa","title":"Canon inverso","author":"Paolo Maurensig","sortKey":"Maurensig","summary":"Un violín antiguo comprado en una subasta abre la puerta a una historia de amistad, rivalidad y obsesión. A través de varios narradores encadenados, Maurensig nos lleva a la Centroeuropa de entreguerras y a un severo conservatorio vienés, donde dos jóvenes violinistas descubren juntos la música y el misterio de un canon que solo puede tocarse a dos. Breve, elegante y llena de ecos, la novela es a la vez una meditación sobre el talento, la culpa y el poder casi demoníaco del arte, y un relato construido con la precisión de una partitura.","authorBio":"Paolo Maurensig (1943-2021) fue un novelista italiano de Gorizia, conocido por sus novelas sobre música y ajedrez como «La variante de Lüneburg» y «Canon inverso».","year":1996,"originalTitle":"Canone inverso","language":"italiano","pages":180,"tags":["música","violín","novela italiana","amistad","obsesión","centroeuropa"],"cover":"covers/canon-inverso.jpg","ratio":1.629,"color":"#7d2b28"},{"id":"como-ser-un-estoico","shelf":104,"theme":"Filosofía","title":"Cómo ser un estoico","author":"Massimo Pigliucci","sortKey":"Pigliucci","summary":"Massimo Pigliucci propone tomarse el estoicismo en serio como filosofía de vida y no como simple técnica de autoayuda. Imaginando conversaciones con Epicteto, el antiguo esclavo convertido en maestro, recorre las grandes ideas estoicas: distinguir lo que depende de nosotros de lo que no, vivir según la razón, cultivar las virtudes, afrontar la muerte, la ira o la enfermedad con serenidad. Combina anécdotas personales, ejercicios prácticos y reflexión filosófica en un libro ameno y útil para quien busca orden interior y una ética exigente en medio de la prisa contemporánea.","authorBio":"Massimo Pigliucci (1964) es un filósofo y biólogo italoamericano, profesor en el City College de Nueva York y uno de los principales divulgadores del estoicismo moderno.","year":2017,"originalTitle":"How to Be a Stoic","language":"inglés","pages":300,"tags":["estoicismo","epicteto","virtud","filosofía práctica","serenidad","ética"],"cover":"covers/como-ser-un-estoico.jpg","ratio":1.602,"color":"#653c26"},{"id":"ensayo-sobre-la-vida-privada","shelf":105,"theme":"Filosofía","title":"Ensayo sobre la vida privada","author":"Manuel García Morente","sortKey":"García Morente","summary":"Breve y luminoso ensayo en el que García Morente distingue la vida pública, hecha de funciones y relaciones impersonales, de la vida privada, ese ámbito íntimo donde la persona es verdaderamente ella misma. Con prosa clara y fina capacidad de observación, analiza la soledad, la amistad, el amor, la intimidad y el pudor, y advierte de los peligros de una sociedad que tiende a invadir y masificar lo personal. Escrito poco antes de la Guerra Civil, conserva hoy plena vigencia como defensa de la interioridad y de los vínculos que dan hondura a la existencia.","authorBio":"Manuel García Morente (1886-1942) fue un filósofo español, catedrático y decano de Filosofía en Madrid y traductor de Kant, que tras una profunda conversión religiosa en 1937 se ordenó sacerdote.","year":1935,"language":"español","pages":100,"tags":["vida privada","intimidad","amistad","persona","ensayo español","sociedad de masas"],"cover":"covers/ensayo-sobre-la-vida-privada.jpg","ratio":1.408,"color":"#8c4aa7"},{"id":"reflexiones-sobre-la-persona-humana","shelf":106,"theme":"Filosofía","title":"Reflexiones sobre la persona humana","author":"Jacques Maritain","sortKey":"Maritain","summary":"Breve texto de Jacques Maritain que condensa algunas de sus intuiciones centrales sobre la persona. Frente a los totalitarismos y al individualismo, el filósofo francés recuerda que el ser humano no es una mera pieza de la sociedad ni un átomo aislado, sino un todo espiritual dotado de inteligencia y libertad, abierto a la comunión con los demás y con Dios. De ahí brotan su dignidad inviolable y sus derechos. Una puerta de entrada accesible al personalismo cristiano de Maritain, ideal para leer despacio y volver a él.","authorBio":"Jacques Maritain (1882-1973) fue un filósofo francés converso al catolicismo, gran renovador del pensamiento de santo Tomás en el siglo XX e inspirador del humanismo cristiano y de la Declaración Universal de los Derechos Humanos.","language":"francés","tags":["persona","personalismo","dignidad humana","tomismo","derechos humanos","humanismo cristiano"],"cover":"covers/reflexiones-sobre-la-persona-humana.jpg","ratio":1.401,"color":"#4f4492"},{"id":"the-person-and-the-common-good","shelf":107,"theme":"Filosofía","title":"The Person and the Common Good","author":"Jacques Maritain","sortKey":"Maritain","note":"Edición en inglés","summary":"En este ensayo breve y denso, Maritain aborda una cuestión decisiva de la filosofía política: cómo se relacionan la persona y la sociedad. Apoyándose en santo Tomás, distingue entre el individuo, parte del todo social, y la persona, que por su dimensión espiritual trasciende la comunidad política y se ordena a Dios. El bien común no es la suma de intereses privados ni un fin que aplaste a las personas, sino un bien que redunda en ellas. Escrito tras la Segunda Guerra Mundial, es una respuesta serena tanto al totalitarismo como al individualismo liberal.","authorBio":"Jacques Maritain (1882-1973) fue un filósofo francés converso al catolicismo, gran renovador del pensamiento de santo Tomás en el siglo XX e inspirador del humanismo cristiano.","year":1946,"originalTitle":"La personne et le bien commun","language":"francés","pages":110,"tags":["bien común","persona","filosofía política","tomismo","totalitarismo","personalismo"],"ratio":1.5,"color":"#647baf"},{"id":"el-hombre-y-sus-alrededores","shelf":108,"theme":"Filosofía","title":"El hombre y sus alrededores","author":"Higinio Marín","sortKey":"Marín","summary":"Colección de estudios de filosofía del hombre y de la cultura en la que Higinio Marín piensa al ser humano a partir de lo que lo rodea: la casa, la ciudad, el vestido, la técnica, las costumbres, la memoria y las instituciones. Su tesis de fondo es que no podemos entendernos al margen de esos «alrededores» que fabricamos y que, a su vez, nos configuran. Con una escritura cuidada, atenta a la historia y a la vida cotidiana, el libro ofrece una antropología viva y sugerente, lejos de la abstracción, que invita a mirar con ojos nuevos lo más familiar.","authorBio":"Higinio Marín (1965) es un filósofo español, profesor de Antropología Filosófica en la Universidad CEU Cardenal Herrera y autor de ensayos sobre el hombre, la cultura y la ciudadanía.","year":2013,"language":"español","tags":["antropología filosófica","filosofía de la cultura","ciudad","técnica","vida cotidiana","ensayo"],"cover":"covers/el-hombre-y-sus-alrededores.jpg","ratio":1.538,"color":"#4b4c2d"},{"id":"tao-te-ching","shelf":109,"theme":"Filosofía","title":"Tao Te Ching","author":"Lao Tse","sortKey":"Lao Tse","summary":"Uno de los libros más traducidos de la historia: ochenta y un breves capítulos atribuidos al sabio chino Lao Tse, fundamento del taoísmo. En aforismos poéticos y a menudo paradójicos, habla del Tao, el principio inefable que sostiene todas las cosas, y de una sabiduría basada en la humildad, la sencillez, la no violencia y el «no forzar». Ofrece también consejos al gobernante sobre el arte de guiar sin imponerse. Leído desde una mirada cristiana, es un fascinante testimonio de la búsqueda humana de sentido y armonía, y un texto para saborear sin prisa.","authorBio":"Lao Tse es el sabio chino, de existencia semilegendaria, al que la tradición atribuye el «Tao Te Ching» y considera fundador del taoísmo, en torno a los siglos VI-IV a. C.","originalTitle":"Dao De Jing","language":"chino clásico","pages":150,"tags":["taoísmo","sabiduría oriental","china","aforismos","humildad","filosofía antigua"],"cover":"covers/tao-te-ching.jpg","ratio":1.656,"color":"#c49f6e"},{"id":"jacques-maritain-y-la-polemica-del-bien-comun","shelf":110,"theme":"Filosofía","title":"Jacques Maritain y la polémica del bien común","author":"Carlos Santamaría","sortKey":"Santamaría","summary":"En los años cuarenta y cincuenta, el pensamiento católico vivió una intensa discusión sobre la relación entre la persona y el bien común: ¿debe primar la persona o la comunidad política? Carlos Santamaría expone los términos de aquella polémica, en la que Maritain fue acusado por algunos tomistas de exaltar en exceso a la persona, y examina con rigor los argumentos de unos y otros. El resultado es una defensa matizada del personalismo de Maritain, útil para comprender un debate que sigue iluminando cuestiones de filosofía social, política y doctrina social de la Iglesia.","authorBio":"Carlos Santamaría (1909-2001) fue un matemático y pensador católico donostiarra, impulsor de las Conversaciones Católicas Internacionales de San Sebastián y promotor del diálogo y la paz en el País Vasco.","year":1955,"language":"español","tags":["bien común","maritain","personalismo","filosofía política","tomismo","doctrina social"],"ratio":1.5,"color":"#3e4d89"},{"id":"bosquejo-de-una-teoria-de-las-emociones","shelf":111,"theme":"Filosofía","title":"Bosquejo de una teoría de las emociones","author":"Jean-Paul Sartre","sortKey":"Sartre","summary":"Ensayo temprano en el que Sartre aplica la fenomenología de Husserl al estudio de las emociones. Critica las teorías psicológicas que las reducen a reacciones fisiológicas o a mecanismos inconscientes y propone verlas como una forma de conciencia: un modo «mágico» de transformar el mundo cuando los caminos ordinarios nos resultan difíciles o imposibles. El miedo, la tristeza o la alegría serían así maneras de relacionarnos con la realidad. Breve y exigente, es una buena introducción al método fenomenológico y a las raíces del existencialismo sartriano, que conviene leer con espíritu crítico.","authorBio":"Jean-Paul Sartre (1905-1980) fue un filósofo, novelista y dramaturgo francés, figura central del existencialismo; rechazó el Premio Nobel de Literatura en 1964.","year":1939,"originalTitle":"Esquisse d'une théorie des émotions","language":"francés","pages":110,"tags":["emociones","fenomenología","existencialismo","psicología","conciencia","filosofía francesa"],"cover":"covers/bosquejo-de-una-teoria-de-las-emociones.jpg","ratio":1.634,"color":"#636852"},{"id":"breviario-del-animal-humano","shelf":112,"theme":"Filosofía","title":"Breviario del animal humano","author":"Enrique Baca","sortKey":"Baca","summary":"Tras más de medio siglo dedicado a la psiquiatría, Enrique Baca condensa en forma breve y aforística lo que ha aprendido sobre el ser humano. El libro recorre la génesis, la estructura y el funcionamiento de la persona, las claves de su conducta, las razones profundas de sus actos y la dinámica de sus relaciones con los demás. Es su primera obra dirigida al gran público, fruto del estudio teórico, la investigación y la experiencia clínica, y resulta un breviario en el sentido literal: un libro para tener a mano y releer a sorbos.","authorBio":"Enrique Baca Baldomero es un psiquiatra granadino, catedrático de Psiquiatría y autor de numerosos trabajos sobre psicopatología, antropología y filosofía de la psiquiatría.","year":2019,"language":"español","pages":216,"tags":["naturaleza humana","psiquiatría","antropología","aforismos","conducta","psicología"],"cover":"covers/breviario-del-animal-humano.jpg","ratio":1.515,"color":"#c9beb1"},{"id":"nietzsche","shelf":113,"theme":"Filosofía","title":"Nietzsche","author":"Autor desconocido","sortKey":"~","note":"Edición por confirmar","summary":"Volumen dedicado al pensamiento de Friedrich Nietzsche, el filósofo alemán que proclamó la «muerte de Dios» y sometió a una crítica radical la moral, la religión y la metafísica occidentales. Sus grandes temas —el nihilismo, la voluntad de poder, el superhombre, el eterno retorno y la transvaloración de todos los valores— han marcado profundamente la cultura contemporánea. Pendiente de confirmar la edición concreta (tapa dura azul con letras doradas), es en todo caso una obra útil para conocer de primera mano a un autor imprescindible, cuya lectura desde la fe cristiana invita al diálogo y al discernimiento crítico.","authorBio":"Friedrich Nietzsche (1844-1900) fue un filósofo y filólogo alemán, autor de «Así habló Zaratustra» y «Más allá del bien y del mal», uno de los pensadores más influyentes y polémicos de la modernidad.","tags":["nietzsche","nihilismo","filosofía alemana","superhombre","crítica de la moral","modernidad"],"ratio":1.5,"color":"#3e53bb"},{"id":"etica-sin-moral","shelf":114,"theme":"Filosofía","title":"Ética sin moral","author":"Adela Cortina","sortKey":"Cortina","summary":"Adela Cortina se pregunta si es posible una ética para sociedades pluralistas, en las que conviven muchas concepciones de la vida buena. Distingue entre la moral vivida, que orienta la conducta cotidiana, y la ética como reflexión filosófica sobre ella, y defiende una ética mínima de raíz kantiana y dialógica, apoyada en la ética del discurso de Apel y Habermas. Un ensayo riguroso, clave en el debate español sobre ética civil, que ayuda a pensar cómo convivir respetando la dignidad de todos, aunque el lector católico echará en falta un fundamento trascendente.","authorBio":"Adela Cortina (1947) es una filósofa valenciana, catedrática emérita de Ética y Filosofía Política en la Universidad de Valencia y miembro de la Real Academia de Ciencias Morales y Políticas.","year":1990,"language":"español","pages":320,"tags":["ética","ética civil","pluralismo","kant","ética del discurso","filosofía moral"],"cover":"covers/etica-sin-moral.jpg","ratio":1.639,"color":"#bdbdbd"},{"id":"los-cuatro-amores","shelf":115,"theme":"Filosofía","title":"Los cuatro amores","author":"C. S. Lewis","sortKey":"Lewis","summary":"C. S. Lewis distingue y examina las cuatro formas clásicas del amor humano: el afecto familiar, la amistad, el eros o amor de enamorados y la caridad, el amor que procede de Dios. Con su mezcla característica de sentido común, humor e intuición teológica, muestra la grandeza de cada uno y también sus peligros cuando se absolutizan y pretenden ocupar el lugar de Dios. Solo la caridad puede ordenar y salvar los amores naturales. Un clásico de la literatura cristiana, profundo y a la vez cercano, ideal para meditar sobre nuestras relaciones.","authorBio":"C. S. Lewis (1898-1963) fue un escritor y profesor británico de Oxford y Cambridge, converso al cristianismo, autor de «Mero cristianismo» y de «Las crónicas de Narnia».","year":1960,"originalTitle":"The Four Loves","language":"inglés","pages":190,"tags":["amor","amistad","caridad","afecto","apologética cristiana","relaciones humanas"],"cover":"covers/los-cuatro-amores.jpg","ratio":1.639,"color":"#194c69"},{"id":"antropologia","shelf":116,"theme":"Filosofía","title":"Antropología","author":"Santo Tomás de Aquino","sortKey":"Tomás de Aquino","summary":"Selección de textos de la «Suma teológica» en los que santo Tomás de Aquino expone su visión del ser humano. El lector encontrará su doctrina sobre el alma como forma del cuerpo, la unidad de la persona, las potencias del entendimiento y la voluntad, las pasiones, la libertad y la imagen de Dios en el hombre. Lejos de ser un saber anticuado, esta antropología sigue ofreciendo una síntesis equilibrada entre lo corporal y lo espiritual. Un volumen manejable para acercarse directamente a las fuentes del pensamiento cristiano sobre la persona.","authorBio":"Santo Tomás de Aquino (1225-1274) fue un fraile dominico, teólogo y filósofo italiano, Doctor de la Iglesia y autor de la «Suma teológica», cumbre del pensamiento escolástico.","originalTitle":"Summa Theologiae (selección)","language":"latín","pages":110,"tags":["santo tomás","antropología","alma","escolástica","suma teológica","persona"],"cover":"covers/antropologia.jpg","ratio":1.634,"color":"#e5d094"},{"id":"mision-de-la-universidad","shelf":117,"theme":"Filosofía","title":"Misión de la universidad","author":"José Ortega y Gasset","sortKey":"Ortega","summary":"Conferencia convertida en ensayo en la que Ortega y Gasset reflexiona sobre qué debe ser la universidad. Critica una institución que se limita a formar profesionales o a acumular investigación especializada y reclama que su tarea primera sea transmitir la cultura: el sistema vital de ideas de cada época, sin el cual el hombre queda desorientado. Propone una enseñanza centrada en el estudiante, en lo esencial y en la formación de personas cultas. Escrito en 1930, conserva una sorprendente actualidad ante los debates sobre especialización y sentido de la educación superior.","authorBio":"José Ortega y Gasset (1883-1955) fue el filósofo español más influyente del siglo XX, catedrático de Metafísica en Madrid y fundador de la «Revista de Occidente».","year":1930,"language":"español","pages":110,"tags":["universidad","educación superior","cultura","ortega y gasset","especialización","ensayo español"],"cover":"covers/mision-de-la-universidad.jpg","ratio":1.543,"color":"#e5e694"},{"id":"dialogos","shelf":118,"theme":"Clásicos grecolatinos","title":"Diálogos","author":"Platón","sortKey":"Platón","summary":"En los diálogos de Platón, Sócrates conversa con jóvenes, sofistas y políticos sobre las preguntas que nunca dejan de inquietarnos: qué es la justicia, la virtud, el amor, la belleza o el alma, y si existe una verdad que no dependa de la opinión. Mediante preguntas incisivas desmonta certezas aparentes y conduce al interlocutor a pensar por sí mismo. Obras como la «Apología», el «Critón», el «Banquete» o el «Fedón» son a la vez filosofía y literatura de primer orden. Un clásico fundacional de Occidente, siempre fecundo para quien busca la verdad.","authorBio":"Platón (c. 427-347 a. C.) fue un filósofo ateniense, discípulo de Sócrates y maestro de Aristóteles, fundador de la Academia y uno de los pilares del pensamiento occidental.","language":"griego antiguo","pages":400,"tags":["sócrates","filosofía griega","diálogo","virtud","justicia","clásicos"],"cover":"covers/dialogos.jpg","ratio":1.656,"color":"#135314"},{"id":"sobre-la-vejez-sobre-la-amistad","shelf":119,"theme":"Clásicos grecolatinos","title":"Sobre la vejez. Sobre la amistad","author":"Cicerón","sortKey":"Cicerón","summary":"Dos breves tratados escritos por Cicerón en el último año de su vida. En «Sobre la vejez», el anciano Catón defiende que esta etapa no tiene por qué ser triste: puede ser tiempo de sabiduría, serenidad, consejo y preparación para la muerte. En «Sobre la amistad», Lelio, tras la pérdida de su amigo Escipión, explica que la verdadera amistad solo es posible entre personas virtuosas y constituye uno de los mayores bienes de la vida. Dos joyas de la prosa latina, llenas de humanidad y sentido común, que se leen con provecho a cualquier edad.","authorBio":"Marco Tulio Cicerón (106-43 a. C.) fue un orador, político y filósofo romano, maestro de la prosa latina y gran transmisor de la filosofía griega a Roma.","year":-44,"originalTitle":"Cato Maior de senectute; Laelius de amicitia","language":"latín","pages":160,"tags":["amistad","vejez","estoicismo","filosofía romana","virtud","clásicos latinos"],"cover":"covers/sobre-la-vejez-sobre-la-amistad.jpg","ratio":1.592,"color":"#657139"},{"id":"la-rebelion-de-las-masas-y-otros-ensayos","shelf":120,"theme":"Filosofía","title":"La rebelión de las masas y otros ensayos","author":"José Ortega y Gasset","sortKey":"Ortega","summary":"El ensayo más célebre de Ortega y Gasset analiza la irrupción del «hombre masa» en la Europa del siglo XX: un tipo humano satisfecho de sí mismo, que disfruta de los logros de la civilización sin sentirse obligado por ellos, que no reconoce ninguna instancia superior y quiere imponer su vulgaridad. Frente a él, Ortega reivindica la vida noble, entendida como exigencia y servicio. El volumen se completa con otros ensayos afines. Escrito en 1930, es un diagnóstico penetrante que anticipa fenómenos de nuestro tiempo y sigue provocando reflexión.","authorBio":"José Ortega y Gasset (1883-1955) fue el filósofo español más influyente del siglo XX, catedrático de Metafísica en Madrid y fundador de la «Revista de Occidente».","year":1930,"language":"español","pages":300,"tags":["hombre masa","sociedad de masas","europa","ortega y gasset","filosofía social","ensayo español"],"ratio":1.5,"color":"#3b4fab"},{"id":"coyuntura-economica-y-reformismo-burgues","shelf":121,"theme":"Historia y actualidad","title":"Coyuntura económica y reformismo burgués","author":"Jaime Vicens Vives","sortKey":"Vicens Vives","summary":"Recopilación póstuma de estudios del gran historiador Jaume Vicens Vives, reunidos tras su prematura muerte. Los trabajos analizan la historia de España, y especialmente de Cataluña, desde la economía y la sociedad: las coyunturas de crisis y expansión, el papel de la burguesía y los intentos reformistas desde la Baja Edad Media hasta la época contemporánea. Representan bien la renovación metodológica que Vicens impulsó, alejada de la historia meramente política y abierta a la influencia de la escuela de los Annales. Lectura de referencia para interesados en la historiografía española.","authorBio":"Jaume Vicens Vives (1910-1960) fue un historiador catalán, catedrático en Barcelona y renovador de la historiografía española con obras como «Aproximación a la historia de España» y «Noticia de Cataluña».","year":1968,"language":"español","pages":215,"tags":["historia económica","historia de españa","cataluña","burguesía","historiografía","reformismo"],"cover":"covers/coyuntura-economica-y-reformismo-burgues.jpg","ratio":1.63,"color":"#65589c"},{"id":"el-poder-de-la-oracion","shelf":122,"theme":"Fe y espiritualidad","title":"El poder de la oración","author":"Jean Lafrance","sortKey":"Lafrance","summary":"Jean Lafrance, gran maestro de oración del siglo XX, invita a redescubrir la fuerza de la oración de petición, a menudo infravalorada. A partir de las promesas de Jesús —«pedid y se os dará»— y de la experiencia de los santos, muestra que orar con perseverancia, humildad y confianza filial no es un gesto infantil, sino la actitud del hijo que lo espera todo del Padre. Con tono cálido y espiritualidad muy bíblica, el libro ayuda a vencer el desaliento, a insistir en la oración y a dejar que Dios transforme el corazón de quien reza.","authorBio":"Jean Lafrance (1931-1991) fue un sacerdote francés de la diócesis de Lille, predicador de retiros y autor de numerosos libros de espiritualidad sobre la oración traducidos a muchas lenguas.","language":"francés","pages":200,"tags":["oración","oración de petición","perseverancia","confianza en dios","vida espiritual","espiritualidad"],"cover":"covers/el-poder-de-la-oracion.jpg","ratio":1.567,"color":"#674d49"},{"id":"jesus-tambien-estaba-invitado","shelf":123,"theme":"Fe y espiritualidad","title":"Jesús también estaba invitado","author":"Mauro Giuseppe Lepori","sortKey":"Lepori","summary":"Inspirándose en las bodas de Caná, donde Jesús también fue invitado, el abad cisterciense Mauro-Giuseppe Lepori reúne charlas pronunciadas en retiros espirituales para familias. Reflexiona sobre la vocación matrimonial y familiar como camino de santidad: el amor de los esposos, la educación de los hijos, las pruebas y el cansancio de la vida cotidiana, y la necesidad de dejar que Cristo entre en casa para transformar el agua en vino. Un libro sencillo y profundo, nacido de la escucha de muchas familias, que devuelve esperanza a quienes viven el matrimonio como vocación.","authorBio":"Mauro-Giuseppe Lepori (1959) es un monje cisterciense suizo, antiguo abad de Hauterive y abad general de la Orden Cisterciense desde 2010.","year":2006,"originalTitle":"Fu invitato anche Gesù. Conversazioni sulla vocazione familiare","language":"italiano","tags":["matrimonio","familia","vocación","bodas de caná","espiritualidad conyugal","santidad"],"cover":"covers/jesus-tambien-estaba-invitado.jpg","ratio":1.408,"color":"#b87f39"},{"id":"persona","shelf":124,"theme":"Filosofía","title":"Persona","author":"Julián Marías","sortKey":"Marías","summary":"Obra de madurez en la que Julián Marías, discípulo de Ortega, culmina su reflexión sobre la persona humana. Frente a las visiones que reducen al hombre a cosa, organismo o mera conciencia, sostiene que la persona es un «alguien», irreductible e insustituible, proyectado hacia el futuro, que se realiza en su vida biográfica, en el amor y en la relación con otras personas, y que está abierto a la pervivencia más allá de la muerte. Escrito con la claridad y elegancia habituales del autor, es una síntesis espléndida de antropología cristiana y metafísica de la vida humana.","authorBio":"Julián Marías (1914-2005) fue un filósofo y ensayista español, discípulo de Ortega y Gasset, miembro de la Real Academia Española y autor de una extensa obra sobre antropología, historia y cultura.","year":1996,"language":"español","pages":190,"tags":["persona","antropología","razón vital","amor","inmortalidad","filosofía española"],"cover":"covers/persona.jpg","ratio":1.75,"color":"#131353"},{"id":"que-surja-el-hombre-nuevo","shelf":125,"theme":"Schoenstatt","title":"Que surja el hombre nuevo","author":"P. José Kentenich","sortKey":"Kentenich","summary":"Clásico de la literatura de Schoenstatt que recoge las conferencias de una jornada pedagógica impartida por el padre José Kentenich en 1951. Ante el hombre moderno desarraigado, sin hogar, sin padre ni madre, sin vínculos, el fundador propone una psicopedagogía religiosa: sanar a la persona desde las vinculaciones naturales —familia, tierra, personas y lugares queridos— para que de ellas brote una relación profunda y estable con Dios Padre. María aparece como educadora de un hombre nuevo, libre y comunitario. Una obra esencial para comprender la pedagogía kentenichiana y su vigencia actual.","authorBio":"El padre José Kentenich (1885-1968) fue un sacerdote palotino alemán, fundador del Movimiento Apostólico de Schoenstatt, superviviente del campo de Dachau y cuya causa de beatificación está en curso.","year":1951,"language":"alemán","tags":["schoenstatt","kentenich","pedagogía","vinculaciones","hombre nuevo","virgen maría"],"ratio":1.5,"color":"#4c9e6e"},{"id":"pequena-historia-de-espana","shelf":126,"theme":"Historia y actualidad","title":"Pequeña historia de España","author":"Manuel Fernández Álvarez","sortKey":"Fernández Álvarez","summary":"Manuel Fernández Álvarez, uno de los grandes historiadores de la España moderna, se propuso contar la historia de su país como un relato lleno de aventuras que realmente sucedieron. Desde la Prehistoria hasta nuestros días, pasando por romanos, visigodos, la Reconquista, los Reyes Católicos, el Imperio, la Ilustración, las guerras y la democracia, la narración avanza con sencillez y viveza, sin perder rigor. Pensado para lectores jóvenes pero disfrutable a cualquier edad, es una excelente puerta de entrada a nuestro pasado común y una lectura ideal para compartir en familia.","authorBio":"Manuel Fernández Álvarez (1921-2010) fue un historiador español, miembro de la Real Academia de la Historia y gran especialista en la España del siglo XVI, autor de biografías de Carlos V, Felipe II e Isabel la Católica.","year":2008,"language":"español","pages":220,"tags":["historia de españa","divulgación","lectura juvenil","historia narrada","familia","cultura general"],"cover":"covers/pequena-historia-de-espana.jpg","ratio":1.511,"color":"#a67a58"},{"id":"pequena-historia-del-mundo","shelf":127,"theme":"Historia y actualidad","title":"Pequeña historia del mundo","author":"Fernando García de Cortázar","sortKey":"García de Cortázar","summary":"Fernando García de Cortázar propone un viaje por la historia universal a través de los ojos de un niño, acompañado por seis guías ilustres: Heródoto, Ibn Jaldún, Leonardo da Vinci, Montesquieu, Joseph Conrad y Stefan Zweig. Con ellos asiste al nacimiento de la civilización, al esplendor y caída de los imperios, a los grandes descubrimientos y a las luces y sombras del mundo moderno. Ameno, ilustrado y bien documentado, combina la emoción de una buena aventura con el rigor del historiador, y resulta perfecto para despertar la curiosidad histórica de jóvenes y adultos.","authorBio":"Fernando García de Cortázar (1942-2022) fue un sacerdote jesuita e historiador bilbaíno, catedrático de la Universidad de Deusto y gran divulgador de la historia de España.","year":2009,"language":"español","pages":290,"tags":["historia universal","divulgación","lectura juvenil","civilización","historia narrada","cultura general"],"cover":"covers/pequena-historia-del-mundo.jpg","ratio":1.534,"color":"#bdbdbd"},{"id":"breve-historia-de-espana-ii","shelf":128,"theme":"Historia y actualidad","title":"Breve historia de España II","author":"Fernando García de Cortázar y José Manuel González Vesga","sortKey":"García de Cortázar","summary":"Segundo volumen de una de las síntesis más leídas de la historia de España, obra de Fernando García de Cortázar y José Manuel González Vesga. Concebida para el gran público, la obra recorre con agilidad los acontecimientos políticos, pero también la economía, la sociedad, la religión y la cultura, y este tomo se ocupa de los siglos más cercanos a nosotros. Escrita con claridad y equilibrio, sin renunciar al rigor académico, ofrece una visión de conjunto que ayuda a comprender el presente a la luz del pasado. Un libro de consulta excelente para cualquier biblioteca familiar.","authorBio":"Fernando García de Cortázar (1942-2022), jesuita y catedrático de Deusto, y José Manuel González Vesga, historiador y colaborador habitual suyo, firmaron juntos varias obras de divulgación histórica.","year":1994,"language":"español","pages":400,"tags":["historia de españa","divulgación","historia contemporánea","síntesis histórica","cultura general"],"ratio":1.5,"color":"#c5a049"},{"id":"el-hombre-en-busca-de-sentido","shelf":129,"theme":"Filosofía","title":"El hombre en busca de sentido","author":"Viktor Frankl","sortKey":"Frankl","summary":"Viktor Frankl, psiquiatra vienés, relata su experiencia como prisionero en Auschwitz y otros campos de concentración. Más que los horrores en sí, le interesa cómo reaccionaba el ser humano ante ellos: por qué algunos se derrumbaban y otros conservaban su dignidad. Su conclusión es que quien tiene un «para qué» vivir soporta casi cualquier «cómo». De esa experiencia nace la logoterapia, que sitúa la búsqueda de sentido en el centro de la vida humana. Un testimonio estremecedor y profundamente esperanzador, uno de los libros más influyentes del siglo XX.","authorBio":"Viktor Frankl (1905-1997) fue un neurólogo y psiquiatra austriaco, superviviente del Holocausto y fundador de la logoterapia.","year":1946,"originalTitle":"…trotzdem Ja zum Leben sagen. Ein Psychologe erlebt das Konzentrationslager","language":"alemán","pages":160,"tags":["sentido de la vida","logoterapia","holocausto","sufrimiento","esperanza","psicología"],"ratio":1.5,"color":"#393786"},{"id":"el-mundo-de-sofia","shelf":130,"theme":"Filosofía","title":"El mundo de Sofía","author":"Jostein Gaarder","sortKey":"Gaarder","summary":"Sofía Amundsen, una adolescente noruega, empieza a recibir cartas anónimas con preguntas sencillas e inquietantes: ¿quién eres?, ¿de dónde viene el mundo? Así comienza un curso de filosofía por correspondencia que la lleva, de la mano de un misterioso profesor, desde los presocráticos hasta Sartre, pasando por Platón, santo Tomás, Descartes, Kant o Darwin. A la vez, una intriga cada vez más extraña envuelve la historia. Novela y manual a la vez, ha iniciado en la filosofía a millones de lectores y despierta el gusto por hacerse grandes preguntas.","authorBio":"Jostein Gaarder (1952) es un escritor noruego, antiguo profesor de filosofía de secundaria, mundialmente conocido por «El mundo de Sofía».","year":1991,"originalTitle":"Sofies verden","language":"noruego","pages":640,"tags":["historia de la filosofía","novela","adolescencia","divulgación","preguntas existenciales","literatura juvenil"],"cover":"covers/el-mundo-de-sofia.jpg","ratio":1.52,"color":"#cfb131"},{"id":"montessori-ante-el-legado-de-rousseau","shelf":131,"theme":"Educación","title":"Montessori ante el legado de Rousseau","author":"Catherine L'Ecuyer","sortKey":"L'Ecuyer","summary":"¿Era Maria Montessori una heredera de la pedagogía romántica de Rousseau y de la Escuela Nueva? Catherine L'Ecuyer responde con rigor a esta pregunta y desmonta muchos mitos que circulan sobre la célebre pedagoga, criticada a la vez por naturalistas, progresistas y modernistas por su método, su supuesto individualismo o su religiosidad. Comparando cuidadosamente las fuentes, muestra que la antropología montessoriana, realista y abierta a lo trascendente, se aleja en puntos clave del naturalismo rousseauniano. Un estudio académico pero accesible, imprescindible para padres y educadores interesados en Montessori.","authorBio":"Catherine L'Ecuyer es una investigadora y divulgadora canadiense afincada en Barcelona, doctora en Educación y Psicología, madre de cuatro hijos y autora de éxitos como «Educar en el asombro».","year":2020,"language":"español","pages":353,"tags":["montessori","rousseau","pedagogía","historia de la educación","infancia","filosofía de la educación"],"ratio":1.5,"color":"#5fc889"},{"id":"pedagogia-de-la-lucha-ascetica","shelf":132,"theme":"Educación","title":"Pedagogía de la lucha ascética","author":"Víctor García Hoz","sortKey":"García Hoz","note":"Edición de 1942","summary":"Primera obra de Víctor García Hoz, nacida de su tesis doctoral sobre el concepto de lucha en la ascética española y la educación de la juventud. A partir de los grandes autores espirituales del Siglo de Oro, estudia el esfuerzo moral, el dominio de sí y el combate interior como elementos esenciales de la formación de la persona, y propone aplicarlos a la tarea educativa. Ejemplar antiguo y valioso, refleja el clima intelectual de la posguerra, pero también anticipa la pedagogía personalizada que el autor desarrollaría después. Una pieza de interés histórico y espiritual.","authorBio":"Víctor García Hoz (1911-1998) fue un pedagogo español, catedrático de la Universidad de Madrid, impulsor de la educación personalizada y una de las figuras centrales de la pedagogía española del siglo XX.","year":1941,"language":"español","tags":["ascética","pedagogía","educación moral","esfuerzo","espiritualidad española","formación del carácter"],"ratio":1.5,"color":"#72ac90"},{"id":"exigir-para-educar","shelf":133,"theme":"Educación","title":"Exigir para educar","author":"Eusebio Ferrer","sortKey":"Ferrer","summary":"Libro práctico de la colección «Hacer Familia» dirigido a padres y educadores que quieren formar hijos responsables y libres. Eusebio Ferrer defiende que la exigencia, bien entendida, no se opone al cariño sino que es una de sus formas más altas: pedir esfuerzo, poner límites y mantener la coherencia ayuda a los hijos a crecer en voluntad, orden y virtudes. Con ejemplos cotidianos y orientaciones concretas para distintas edades, ofrece criterios claros frente a la permisividad y el autoritarismo. Una guía sencilla y sensata para la educación en familia.","authorBio":"Eusebio Ferrer Hortet es un educador y orientador familiar español, autor de libros de pedagogía familiar publicados en la colección «Hacer Familia» de Ediciones Palabra.","language":"español","pages":230,"tags":["educación familiar","exigencia","voluntad","virtudes","paternidad","límites"],"cover":"covers/exigir-para-educar.jpg","ratio":1.582,"color":"#cc303d"},{"id":"matar-a-socrates","shelf":134,"theme":"Educación","title":"¿Matar a Sócrates?","author":"Gregorio Luri","sortKey":"Luri","summary":"Gregorio Luri baja a Sócrates de los altares para que volvamos a aprender de él. En un tiempo de revolución tecnológica, en el que lo nuevo parece haber sustituido a lo bueno y llamamos diálogo a lo que ocurre en las redes sociales, se pregunta para qué necesitamos todavía al filósofo ateniense. Su respuesta es que Sócrates inauguró una conversación sobre la verdad, la virtud y el conocimiento que sigue siendo imprescindible. Ameno, culto y provocador, el libro reivindica la memoria, la atención y el diálogo cara a cara como bases de toda educación.","authorBio":"Gregorio Luri (1955) es un maestro, pedagogo y doctor en Filosofía navarro, uno de los referentes del debate educativo en España y autor de numerosos ensayos sobre educación y filosofía.","year":2015,"language":"español","pages":250,"tags":["sócrates","filosofía griega","educación","diálogo","pensamiento crítico","ensayo"],"ratio":1.5,"color":"#429a58"},{"id":"cultivar-el-caracter-en-la-familia-una-tarea-ineludible","shelf":135,"theme":"Educación","title":"Cultivar el carácter en la familia: una tarea ineludible","author":"Josu Ahedo, Carmen Caro y Juan Luis Fuentes (coords.)","sortKey":"Ahedo","summary":"Obra colectiva coordinada por Josu Ahedo, Carmen Caro y Juan Luis Fuentes que reúne doce capítulos sobre la educación del carácter en el ámbito familiar. Desde distintas perspectivas —filosofía de la educación, psicología, pedagogía—, los autores defienden que la familia es el primer y más decisivo espacio para cultivar virtudes, hábitos y convicciones, y que esa tarea no puede delegarse por completo en la escuela. Combina fundamentación teórica y propuestas prácticas, y ofrece a padres, educadores e investigadores ideas valiosas para acompañar el crecimiento moral de los hijos.","authorBio":"Josu Ahedo, Carmen Caro y Juan Luis Fuentes son profesores universitarios españoles de Teoría y Filosofía de la Educación, especializados en educación del carácter y familia.","year":2021,"language":"español","pages":176,"tags":["educación del carácter","familia","virtudes","educación moral","paternidad","pedagogía"],"ratio":1.5,"color":"#569965"},{"id":"perspectivas-actuales-de-la-condicion-humana-y-la-accion-edu","shelf":136,"theme":"Educación","title":"Perspectivas actuales de la condición humana y la acción educativa","author":"Concepción Naval, Antonio Bernal, Gonzalo Jover y Juan Luis Fuentes (coords.)","sortKey":"Naval","summary":"Volumen colectivo, coordinado por Concepción Naval, Antonio Bernal, Gonzalo Jover y Juan Luis Fuentes, que reflexiona desde la filosofía de la educación sobre los grandes desafíos de la condición humana en nuestro tiempo. Sus diecinueve capítulos, organizados en cuatro partes, abordan la cultura, los enfoques pedagógicos, la globalización y la revolución científica y tecnológica, con una pregunta de fondo: cómo educar para la plenitud humana en una sociedad acelerada que relega la reflexión. Un libro académico, útil para docentes e investigadores que buscan pensar la educación más allá de lo instrumental.","authorBio":"Concepción Naval, Antonio Bernal, Gonzalo Jover y Juan Luis Fuentes son catedráticos y profesores españoles de Teoría y Filosofía de la Educación en distintas universidades.","year":2020,"language":"español","pages":316,"tags":["filosofía de la educación","condición humana","tecnología","globalización","pedagogía","humanismo"],"cover":"covers/perspectivas-actuales-de-la-condicion-humana-y-la-accion-edu.jpg","ratio":1.441,"color":"#403d4d"},{"id":"conversaciones-con-mi-maestra","shelf":137,"theme":"Educación","title":"Conversaciones con mi maestra","author":"Catherine L'Ecuyer","sortKey":"L'Ecuyer","summary":"En un momento de desconcierto educativo, con escuelas que se debaten entre lo tradicional y una oferta de innovaciones a menudo guiada por modas o marketing, Catherine L'Ecuyer imagina un diálogo con una maestra sabia para resolver dudas y fijar certezas. ¿Qué dice realmente la ciencia sobre el aprendizaje? ¿Qué papel tienen la memoria, la atención, las pantallas o el asombro? Con lenguaje cercano y numerosas referencias, el libro ayuda a padres y docentes a discernir lo valioso de lo pasajero y a recuperar una educación centrada en la persona.","authorBio":"Catherine L'Ecuyer es una investigadora y divulgadora canadiense afincada en Barcelona, doctora en Educación y Psicología, madre de cuatro hijos y autora de éxitos como «Educar en el asombro».","year":2021,"language":"español","pages":325,"tags":["educación","innovación educativa","escuela","asombro","pantallas","padres y maestros"],"cover":"covers/conversaciones-con-mi-maestra.jpg","ratio":1.515,"color":"#a6aaa5"},{"id":"el-talento-de-los-adolescentes","shelf":138,"theme":"Educación","title":"El talento de los adolescentes","author":"José Antonio Marina","sortKey":"Marina","summary":"José Antonio Marina sostiene que la adolescencia no es una etapa problemática que haya que soportar, sino una época de enormes oportunidades: el cerebro adolescente posee una plasticidad extraordinaria que permite desarrollar talento, carácter y proyectos vitales. Apoyándose en la neurociencia y en su larga experiencia como educador, ofrece claves a padres y profesores para acompañar a los jóvenes en la gestión de las emociones, la voluntad, la creatividad y la toma de decisiones. Un libro optimista y práctico que invita a mirar a los adolescentes con confianza.","authorBio":"José Antonio Marina (1939) es un filósofo, ensayista y pedagogo toledano, autor de numerosos libros sobre inteligencia, emociones y educación.","year":2014,"language":"español","pages":250,"tags":["adolescencia","talento","neurociencia","educación","carácter","paternidad"],"cover":"covers/el-talento-de-los-adolescentes.jpg","ratio":1.57,"color":"#bdbdbd"},{"id":"socrates-en-el-aula","shelf":139,"theme":"Educación","title":"Sócrates en el aula","author":"José María Barrio Maestre","sortKey":"Barrio","summary":"José María Barrio Maestre reúne una serie de reflexiones filosóficas y pedagógicas, deliberadamente «incorrectas», para reconciliar la filosofía y la educación, dos disciplinas que se han ido distanciando en las últimas décadas. Desde la tradición aristotélica defiende que cuanto más sabemos, más somos como personas, y reivindica la memoria, la paciencia del entendimiento y el valor de la verdad frente a modas pedagógicas que los han desacreditado. Un ensayo lúcido y polémico, de lectura muy recomendable para maestros, profesores y padres que se preguntan qué significa realmente educar.","authorBio":"José María Barrio Maestre es doctor en Filosofía y profesor de Antropología Pedagógica en la Universidad Complutense de Madrid, autor de numerosos ensayos sobre educación y persona.","year":2026,"language":"español","tags":["filosofía de la educación","sócrates","aristóteles","memoria","verdad","docencia"],"ratio":1.5,"color":"#478067"},{"id":"las-flores-del-mal","shelf":140,"theme":"Poesía","title":"Las flores del mal","author":"Charles Baudelaire","sortKey":"Baudelaire","summary":"El libro que inauguró la poesía moderna. Baudelaire explora la tensión entre el «spleen», el tedio y la angustia del hombre moderno, y el «ideal», la aspiración a la belleza y a lo absoluto. Sus poemas recorren el París de su tiempo, el amor y el deseo, la muerte, el pecado y la nostalgia de lo divino, con una perfección formal y una audacia que le valieron un proceso por inmoralidad. Leído desde la fe, es el testimonio desgarrado de un alma que conoce su miseria y no deja de anhelar la redención.","authorBio":"Charles Baudelaire (1821-1867) fue un poeta y crítico francés, precursor del simbolismo y considerado el padre de la poesía moderna.","year":1857,"originalTitle":"Les Fleurs du mal","language":"francés","pages":400,"tags":["poesía francesa","simbolismo","modernidad","spleen","belleza","pecado y redención"],"cover":"covers/las-flores-del-mal.jpg","ratio":1.506,"color":"#e0c979"},{"id":"oracion-de-la-lluvia","shelf":141,"theme":"Poesía","title":"Oración de la lluvia","author":"Carmen María López","sortKey":"López","summary":"Poemario ganador del Premio Adonáis 2025, uno de los galardones de poesía más prestigiosos y antiguos de España. Carmen María López ofrece una poesía meditativa y luminosa, en la que la lluvia se convierte en imagen de la gracia, la espera y la purificación, y en la que la mirada atenta a lo cotidiano se abre a la plegaria. Con un lenguaje depurado y musical, los poemas buscan nombrar lo invisible en lo pequeño. Una voz joven de gran hondura, muy recomendable para quienes aman la poesía de raíz espiritual.","authorBio":"Carmen María López López (Caravaca de la Cruz, 1991) es poeta y doctora en Teoría de la Literatura, profesora en la UNED y ganadora del Premio Complutense de Poesía y del Premio Adonáis.","year":2026,"language":"español","pages":72,"tags":["poesía española","premio adonáis","poesía religiosa","oración","naturaleza","poesía contemporánea"],"cover":"covers/oracion-de-la-lluvia.jpg","ratio":1.484,"color":"#e2ce97"},{"id":"azul-cantos-de-vida-y-esperanza","shelf":142,"theme":"Poesía","title":"Azul... Cantos de vida y esperanza","author":"Rubén Darío","sortKey":"Darío","summary":"Dos libros fundamentales de Rubén Darío reunidos en un volumen. «Azul…», con sus cuentos y versos de belleza exquisita, marcó el nacimiento del modernismo hispánico y renovó por completo la lengua poética en español. «Cantos de vida y esperanza», de su plena madurez, añade a la musicalidad y el refinamiento una hondura existencial nueva: la conciencia del paso del tiempo, la angustia ante la muerte, la afirmación de lo hispánico y la búsqueda de Dios. Poemas como «Lo fatal» o «Canción de otoño en primavera» siguen emocionando a cada nueva generación.","authorBio":"Rubén Darío (1867-1916) fue un poeta nicaragüense, iniciador y máximo representante del modernismo literario en lengua española.","year":1888,"language":"español","pages":300,"tags":["modernismo","poesía hispanoamericana","nicaragua","belleza","paso del tiempo","clásicos en español"],"cover":"covers/azul-cantos-de-vida-y-esperanza.jpg","ratio":1.661,"color":"#a47d4d"},{"id":"el-cristo-de-velazquez","shelf":143,"theme":"Poesía","title":"El Cristo de Velázquez","author":"Miguel de Unamuno","sortKey":"Unamuno","summary":"Extenso poema en endecasílabos blancos en el que Unamuno contempla el célebre crucificado pintado por Velázquez. Verso a verso, la meditación se convierte en oración: el Cristo blanco y silencioso del lienzo es imagen del Dios hecho hombre que muere por amor, y a él dirige el poeta sus anhelos de inmortalidad, sus dudas y su sed de fe. Inspirado en la Biblia y en la tradición mística española, es una de las cumbres de la poesía religiosa en nuestra lengua, intensa, dramática y profundamente cristocéntrica.","authorBio":"Miguel de Unamuno (1864-1936) fue un escritor y filósofo bilbaíno de la Generación del 98, rector de la Universidad de Salamanca y autor de «Niebla» y «Del sentimiento trágico de la vida».","year":1920,"language":"español","pages":200,"tags":["poesía religiosa","cristo crucificado","velázquez","generación del 98","fe y duda","poesía española"],"ratio":1.5,"color":"#5c3177"},{"id":"alumbramiento","shelf":144,"theme":"Poesía","title":"Alumbramiento","author":"Daniel Cotta","sortKey":"Cotta","note":"Colección Adonáis","summary":"Poemario de la colección Adonáis en el que Daniel Cotta celebra con alegría su fe católica. Lejos de una mística abstracta, sus versos parten de lo cotidiano —la perfección de una hoja, el canto de un ruiseñor, el azahar en primavera— para reconocer en todo la huella de Dios creador, padre y redentor. Con gran variedad de formas clásicas, de la silva y el soneto a glosas, romances y romancillos, el libro es un canto a la Belleza nacido del asombro y la gratitud, que ha encontrado un público joven que reza con sus poemas.","authorBio":"Daniel Cotta es un poeta español de inspiración católica cuyo libro «Alumbramiento», publicado en la colección Adonáis, alcanzó una notable difusión entre lectores jóvenes.","year":2021,"language":"español","pages":98,"tags":["poesía religiosa","colección adonáis","fe católica","asombro","creación","poesía contemporánea"],"cover":"covers/alumbramiento.jpg","ratio":1.562,"color":"#e6c994"},{"id":"cancion-de-cuna","shelf":145,"theme":"Poesía","title":"Canción de cuna","author":"Jesús Montiel","sortKey":"Montiel","summary":"Libro breve y delicado, a medio camino entre la poesía, la prosa poética y el aforismo, como es habitual en Jesús Montiel. A partir de recuerdos de la infancia y de la relación con su madre, el autor reflexiona sobre los vínculos que nos sostienen, la fragilidad, el cuidado y la gratitud por lo recibido. Su mirada, atenta a los detalles pequeños y abierta a lo trascendente, recuerda a la de Christian Bobin, a quien ha traducido. Una lectura serena y luminosa, para leer despacio y volver a ella en momentos de recogimiento.","authorBio":"Jesús Montiel (Granada, 1984) es poeta y escritor, Premio Hiperión de poesía en 2016 y traductor al español de la obra de Christian Bobin.","year":2022,"language":"español","pages":68,"tags":["poesía española","prosa poética","infancia","madre","fragilidad","gratitud"],"cover":"covers/cancion-de-cuna.jpg","ratio":1.453,"color":"#7badb5"},{"id":"veinte-poemas-de-amor-y-una-cancion-desesperada","shelf":146,"theme":"Poesía","title":"Veinte poemas de amor y una canción desesperada","author":"Pablo Neruda","sortKey":"Neruda","summary":"Publicado cuando Neruda apenas tenía veinte años, es probablemente el libro de poemas más leído en lengua española. Sus versos cantan el amor juvenil con una sensualidad y una melancolía inolvidables, en estrecha unión con la naturaleza: el mar, la lluvia, el bosque y el cuerpo de la amada se funden en imágenes de gran intensidad. Poemas como el 20, «Puedo escribir los versos más tristes esta noche», forman parte de la memoria colectiva. Un clásico para conocer la poesía amorosa del siglo XX.","authorBio":"Pablo Neruda (1904-1973) fue un poeta chileno, uno de los más influyentes del siglo XX en lengua española y Premio Nobel de Literatura en 1971.","year":1924,"language":"español","pages":110,"tags":["poesía amorosa","poesía hispanoamericana","chile","juventud","naturaleza","clásicos en español"],"ratio":1.5,"color":"#712c72"},{"id":"ancia","shelf":147,"theme":"Poesía","title":"Ancia","author":"Blas de Otero","sortKey":"Otero","summary":"Blas de Otero reúne en «Ancia» sus libros «Ángel fieramente humano» y «Redoble de conciencia», junto con nuevos poemas; el título nace precisamente de unir el principio y el final de esos dos títulos. Es la etapa de su poesía existencial: un hombre que busca a Dios en medio de la angustia, el silencio divino y el dolor del mundo de posguerra, y que expresa esa lucha con sonetos y versos de enorme fuerza y desgarro. Un libro capital de la poesía española del siglo XX, donde la sed de Dios y de sentido se vuelve grito.","authorBio":"Blas de Otero (1916-1979) fue un poeta bilbaíno, una de las voces mayores de la poesía española de posguerra, tanto en su vertiente existencial como social.","year":1958,"language":"español","pages":250,"tags":["poesía española","poesía existencial","posguerra","búsqueda de dios","soneto","angustia"],"ratio":1.5,"color":"#742886"},{"id":"antologia-poetica","shelf":148,"theme":"Poesía","title":"Antología poética","author":"Federico García Lorca","sortKey":"García Lorca","summary":"Una selección de la obra poética de Federico García Lorca que permite recorrer su evolución: la frescura popular del «Libro de poemas» y las «Canciones», el mundo andaluz de «Poema del cante jondo» y el «Romancero gitano», la experiencia desgarrada de «Poeta en Nueva York» y la madurez de los «Sonetos del amor oscuro» o el «Llanto por Ignacio Sánchez Mejías». Música, imágenes deslumbrantes, sentido trágico y raíz andaluza se dan cita en una de las voces más universales de la poesía española. Una excelente puerta de entrada al poeta granadino.","authorBio":"Federico García Lorca (1898-1936) fue un poeta y dramaturgo granadino de la Generación del 27, autor del «Romancero gitano» y «Bodas de sangre», asesinado al comienzo de la Guerra Civil.","language":"español","pages":250,"tags":["generación del 27","poesía española","andalucía","romancero","granada","antología"],"cover":"covers/antologia-poetica.jpg","ratio":1.582,"color":"#386f52"},{"id":"tierra-granada","shelf":149,"theme":"Poesía","title":"Tierra granada","author":"Manuel Jesús Gámiz Gordo","sortKey":"Gámiz","summary":"Poemario de Manuel Jesús Gámiz Gordo, autor granadino de Huétor Tájar. No hemos podido documentar con detalle su contenido, pero el título, que juega con el nombre de su tierra y con la imagen de la granada madura, sugiere una poesía arraigada en el paisaje, la memoria y las gentes de Granada. Gámiz, médico pediatra de profesión, cultiva una lírica cercana a la tradición andaluza y al flamenco, en la que la vida cotidiana y el amor a lo propio ocupan un lugar central. Un libro de poesía local y personal, cercano y entrañable.","authorBio":"Manuel Jesús Gámiz Gordo es un médico pediatra y poeta de Huétor Tájar (Granada), premiado en certámenes de letras flamencas y autor de libros de poemas como «Un ramo de poesías».","language":"español","tags":["poesía española","granada","andalucía","tierra natal","flamenco","poesía local"],"ratio":1.5,"color":"#6441aa"},{"id":"himnos-a-la-iglesia","shelf":150,"theme":"Poesía","title":"Himnos a la Iglesia","author":"Gertrud von le Fort","sortKey":"Le Fort","summary":"Ciclo de poemas escrito por Gertrud von le Fort en los años de su conversión al catolicismo. En forma de diálogo entre el alma y la Iglesia, la poeta expresa la búsqueda inquieta de Dios, la resistencia del orgullo, la rendición final y la alegría de encontrar en la Iglesia a la madre y esposa de Cristo que acoge al hombre. Con un lenguaje de resonancias bíblicas y litúrgicas, de enorme fuerza lírica, es una de las grandes obras de la poesía religiosa del siglo XX y una meditación preciosa sobre el misterio de la Iglesia.","authorBio":"Gertrud von le Fort (1876-1971) fue una poeta y novelista alemana convertida al catolicismo en 1926, autora de «La última en el cadalso», inspiradora de los «Diálogos de carmelitas».","year":1924,"originalTitle":"Hymnen an die Kirche","language":"alemán","pages":120,"tags":["poesía religiosa","iglesia","conversión","literatura alemana","liturgia","poesía católica"],"ratio":1.5,"color":"#a953c6"},{"id":"el-vuelo-de-la-bruma","shelf":151,"theme":"Poesía","title":"El vuelo de la bruma","author":"Alejandro López Andrada","sortKey":"López Andrada","summary":"Poemario de Alejandro López Andrada, una de las voces más personales de la poesía andaluza actual. Sus versos vuelven una y otra vez al paisaje de Los Pedroches, al norte de Córdoba: encinares, nieblas de invierno, pueblos que se vacían y oficios que desaparecen. La bruma del título es a la vez paisaje y memoria, ese velo que cubre la infancia y el mundo rural que el poeta vio desvanecerse. Es una poesía serena y contemplativa, de lenguaje limpio y hondo sentimiento de pérdida, que invita a mirar la naturaleza con asombro y gratitud. Merece la pena para leer despacio, en voz baja, saboreando cada imagen.","authorBio":"Poeta y narrador nacido en Villanueva del Duque (Córdoba) en 1957. Su obra, muy premiada, está marcada por la naturaleza, la ecología y la memoria del mundo rural de Los Pedroches.","year":2005,"language":"español","tags":["poesía","poesía española contemporánea","naturaleza","mundo rural","memoria","andalucía"],"cover":"covers/el-vuelo-de-la-bruma.jpg","ratio":1.656,"color":"#bdbdbd"},{"id":"atomos-y-galaxias","shelf":152,"theme":"Poesía","title":"Átomos y galaxias","author":"Miguel d'Ors","sortKey":"d'Ors","summary":"Libro de poemas de Miguel d'Ors publicado en la colección Calle del Aire de la editorial Renacimiento. Como indica el título, el poeta se mueve entre lo diminuto y lo inmenso: las pequeñas cosas de cada día, los recuerdos familiares, el paso del tiempo, y al mismo tiempo la grandeza de la creación y la pregunta por Dios. Con un dominio técnico admirable y un tono cordial, a menudo con humor y ternura, d'Ors convierte lo cotidiano en motivo de contemplación. Es una poesía clara, nada hermética, de fondo cristiano, que reconcilia con la vida. Muy recomendable para quien busque poesía actual con hondura espiritual.","authorBio":"Poeta nacido en Santiago de Compostela en 1946, nieto de Eugenio d'Ors y catedrático de Literatura Española en las universidades de Navarra y Granada. Es una de las voces más reconocidas de la poesía católica española contemporánea.","year":2013,"language":"español","tags":["poesía","poesía española contemporánea","vida cotidiana","fe","creación","contemplación"],"ratio":1.5,"color":"#9d5ba4"},{"id":"teoria-teatral","shelf":153,"theme":"Teatro","title":"Teoría teatral","author":"Vsévolod E. Meyerhold","sortKey":"Meyerhold","summary":"Antología de escritos del gran director ruso Vsévolod Meyerhold, uno de los renovadores decisivos de la escena del siglo XX. Reúne artículos, conferencias y notas en los que explica su ruptura con el naturalismo, su idea de un teatro convencional y estilizado, la recuperación de la commedia dell'arte y del grotesco, y su famoso método de la biomecánica para el entrenamiento físico del actor. Leerlo es asomarse al laboratorio de las vanguardias rusas y entender de dónde vienen muchas prácticas teatrales actuales. Es una obra de referencia para actores, directores y estudiosos del teatro, y también para cualquier aficionado curioso por la historia de la escena.","authorBio":"Actor y director teatral ruso (1874–1940), discípulo de Stanislavski y figura clave de la vanguardia escénica. Fue detenido y ejecutado durante las purgas de Stalin.","language":"ruso","tags":["teatro","teoría teatral","vanguardias","biomecánica","dirección escénica","rusia"],"ratio":1.5,"color":"#914e36"},{"id":"diccionario-de-la-lengua-espanola-ag","shelf":154,"theme":"Obras de consulta","title":"Diccionario de la lengua española (A–G)","author":"Real Academia Española","sortKey":"Real Academia","note":"22.ª edición, 2001","summary":"Primer tomo (letras A a G) de la vigésima segunda edición del Diccionario de la lengua española de la Real Academia Española, publicada en 2001. Fue la primera edición elaborada en estrecha colaboración con las academias de América y Filipinas, e incorporó numerosas voces y acepciones del español americano, así como muchas palabras nuevas de la ciencia, la técnica y la vida moderna. Es la obra de referencia por excelencia para resolver dudas de significado, ortografía y uso. Tener el diccionario en papel sigue siendo un placer: permite hojear, descubrir palabras inesperadas y disfrutar de la riqueza del idioma.","authorBio":"La Real Academia Española, fundada en 1713, es la institución encargada de velar por la unidad y el buen uso del español, en colaboración con las demás academias de la lengua.","year":2001,"language":"español","tags":["diccionario","lengua española","real academia española","obras de consulta","léxico"],"cover":"covers/diccionario-de-la-lengua-espanola-ag.jpg","ratio":1.493,"color":"#bdbdbd"},{"id":"diccionario-de-la-lengua-espanola-hz","shelf":155,"theme":"Obras de consulta","title":"Diccionario de la lengua española (H–Z)","author":"Real Academia Española","sortKey":"Real Academia","note":"22.ª edición, 2001","summary":"Segundo tomo (letras H a Z) de la vigésima segunda edición del Diccionario de la lengua española de la Real Academia Española, aparecida en 2001. Completa la obra iniciada en el primer volumen y recoge, como él, el léxico general del español de ambas orillas del Atlántico, con especial atención a los americanismos y a las palabras incorporadas por la vida moderna. Indispensable para quien escribe, estudia o simplemente ama el idioma, es una obra de consulta que acompaña toda la vida y que, hojeada sin prisa, se convierte también en lectura entretenida y sorprendente.","authorBio":"La Real Academia Española, fundada en 1713, es la institución encargada de velar por la unidad y el buen uso del español, en colaboración con las demás academias de la lengua.","year":2001,"language":"español","tags":["diccionario","lengua española","real academia española","obras de consulta","léxico"],"cover":"covers/diccionario-de-la-lengua-espanola-hz.jpg","ratio":1.493,"color":"#bdbdbd"},{"id":"documentos-completos-del-vaticano-ii","shelf":156,"theme":"Magisterio de la Iglesia","title":"Documentos completos del Vaticano II","author":"Concilio Vaticano II","sortKey":"Vaticano II","summary":"Recopilación de los dieciséis documentos aprobados por el Concilio Vaticano II (1962–1965): las cuatro constituciones (sobre la liturgia, la Iglesia, la Revelación y la Iglesia en el mundo actual), los nueve decretos y las tres declaraciones. Juntos dibujan el rostro de una Iglesia que se entiende como misterio de comunión y pueblo de Dios, llama a todos los bautizados a la santidad, renueva la liturgia, impulsa el diálogo ecuménico y se abre al mundo moderno con esperanza. Es una lectura fundamental para comprender la vida de la Iglesia de las últimas décadas y para formarse con las fuentes y no solo con lo que se dice de ellas.","authorBio":"El Concilio Vaticano II fue el vigésimo primer concilio ecuménico de la Iglesia católica, convocado por san Juan XXIII y clausurado por san Pablo VI en 1965.","year":1965,"language":"latín","tags":["concilio vaticano ii","magisterio","eclesiología","liturgia","iglesia y mundo","documentos de la iglesia"],"ratio":1.5,"color":"#69513f"},{"id":"textos-sobre-la-regulacion-de-la-natalidad","shelf":157,"theme":"Magisterio de la Iglesia","title":"Textos sobre la regulación de la natalidad","author":"Pablo VI y Juan Pablo II","sortKey":"Pablo VI","summary":"Volumen que reúne enseñanzas de san Pablo VI y san Juan Pablo II sobre la transmisión de la vida, con la encíclica Humanae vitae (1968) como texto central. Presenta la visión católica del amor conyugal como amor plenamente humano, total, fiel y fecundo, y la inseparable unión de sus dimensiones unitiva y procreativa. Explica la paternidad responsable, que se vive con generosidad ante la vida y, cuando hay motivos serios, recurriendo a la continencia periódica en los días fértiles, nunca a medios que separan lo que Dios ha unido. Los textos de Juan Pablo II profundizan en esta enseñanza desde su teología del cuerpo. Muy valioso para matrimonios y novios.","authorBio":"San Pablo VI (1897–1978) fue papa de 1963 a 1978 y clausuró el Concilio Vaticano II; san Juan Pablo II (1920–2005), papa de 1978 a 2005, desarrolló ampliamente la teología del cuerpo y del matrimonio.","language":"latín","tags":["humanae vitae","paternidad responsable","matrimonio","teología del cuerpo","regulación natural de la natalidad","magisterio"],"ratio":1.5,"color":"#8b6537"},{"id":"amoris-laetitia","shelf":158,"theme":"Magisterio de la Iglesia","title":"Amoris laetitia","author":"Papa Francisco","sortKey":"Francisco","note":"Exhortación apostólica","summary":"Exhortación apostólica postsinodal del papa Francisco, fruto de los dos sínodos sobre la familia de 2014 y 2015. Parte de la Sagrada Escritura y de la realidad concreta de las familias para proponer el Evangelio del matrimonio y la familia con lenguaje cercano. Su capítulo cuarto, un comentario al himno de la caridad de san Pablo, es una joya sobre el amor en el día a día de los esposos. Trata también la fecundidad, la educación de los hijos, la preparación al matrimonio y el acompañamiento pastoral de situaciones difíciles. Una lectura muy práctica para matrimonios que quieren cuidar su amor y su vida familiar.","authorBio":"Jorge Mario Bergoglio (1936–2025), jesuita argentino y arzobispo de Buenos Aires, fue papa con el nombre de Francisco de 2013 a 2025.","year":2016,"language":"latín","pages":260,"tags":["familia","matrimonio","amor conyugal","educación de los hijos","papa francisco","magisterio"],"cover":"covers/amoris-laetitia.jpg","ratio":1.429,"color":"#4c251a"},{"id":"spe-salvi","shelf":159,"theme":"Magisterio de la Iglesia","title":"Spe salvi","author":"Benedicto XVI","sortKey":"Benedicto XVI","note":"Carta encíclica","summary":"Segunda encíclica de Benedicto XVI, dedicada a la esperanza cristiana a partir de la frase de san Pablo «en esperanza fuimos salvados». Con una prosa luminosa, el papa muestra que la fe es esperanza que transforma la vida ya desde ahora, discute las promesas de progreso de la Modernidad y explica por qué ni la ciencia ni la política pueden darnos por sí solas la salvación. Propone lugares de aprendizaje de la esperanza: la oración, el actuar y el sufrir, y el juicio final. Recuerda figuras como santa Josefina Bakhita y termina con una bella oración a María, estrella de la esperanza. Breve, profunda y muy consoladora.","authorBio":"Joseph Ratzinger (1927–2022), teólogo alemán y prefecto de la Congregación para la Doctrina de la Fe, fue papa con el nombre de Benedicto XVI de 2005 a 2013.","year":2007,"language":"latín","pages":100,"tags":["esperanza","escatología","benedicto xvi","encíclica","virgen maría","magisterio"],"cover":"covers/spe-salvi.jpg","ratio":1.538,"color":"#9c6a25"},{"id":"palabras-de-su-santidad-leon-xiv-en-su-viaje-a-espana","shelf":160,"theme":"Magisterio de la Iglesia","title":"Palabras de Su Santidad León XIV en su viaje a España","author":"León XIV","sortKey":"León XIV","note":"Junio de 2026","summary":"Recopilación de los discursos, homilías y saludos pronunciados por León XIV durante su viaje apostólico a España del 6 al 12 de junio de 2026, el primero de un papa en quince años, bajo el lema «Alzad la mirada». El recorrido incluyó Madrid, con su discurso ante las Cortes y la misa del Corpus, Barcelona, con la Sagrada Familia, y Montserrat, Gran Canaria y Tenerife, donde puso en el centro la dignidad de los migrantes que llegan por mar. El papa habló de unidad frente a la polarización, de la fe en la vida pública, de los jóvenes y de la misericordia. Un recuerdo valioso de un acontecimiento histórico para la Iglesia en España.","authorBio":"Robert Francis Prevost (Chicago, 1955), religioso agustino, misionero y obispo en Perú y prefecto del Dicasterio para los Obispos, fue elegido papa en mayo de 2025 con el nombre de León XIV.","year":2026,"language":"español","tags":["león xiv","viaje apostólico","españa","homilías","migrantes","magisterio"],"ratio":1.5,"color":"#8b713c"},{"id":"redemptor-hominis","shelf":161,"theme":"Magisterio de la Iglesia","title":"Redemptor hominis","author":"Juan Pablo II","sortKey":"Juan Pablo II","note":"Carta encíclica","summary":"Primera encíclica de san Juan Pablo II, publicada pocos meses después de su elección y considerada el programa de su pontificado. Su idea central es que Jesucristo, Redentor del hombre, es el centro del cosmos y de la historia, y que solo en Él el ser humano descubre plenamente quién es. Desde ahí, el papa afirma que el hombre es el camino de la Iglesia, defiende la dignidad y los derechos de la persona y alerta ante las amenazas de un progreso técnico desligado de la ética. Es un texto denso pero apasionante, que ayuda a entender todo el magisterio posterior de Juan Pablo II.","authorBio":"Karol Wojtyła (1920–2005), filósofo y arzobispo de Cracovia, fue papa con el nombre de Juan Pablo II de 1978 a 2005. Fue canonizado en 2014.","year":1979,"language":"latín","pages":100,"tags":["cristología","dignidad humana","juan pablo ii","encíclica","redención","magisterio"],"cover":"covers/redemptor-hominis.jpg","ratio":1.471,"color":"#425313"},{"id":"evangelium-vitae","shelf":162,"theme":"Magisterio de la Iglesia","title":"Evangelium vitae","author":"Juan Pablo II","sortKey":"Juan Pablo II","note":"Carta encíclica","summary":"Encíclica de san Juan Pablo II sobre el valor y el carácter inviolable de la vida humana. Ante lo que llama una cultura de la muerte, el papa denuncia con claridad el aborto, la eutanasia y otras amenazas contra la vida, y afirma con la autoridad de su magisterio la gravedad moral de quitar la vida al inocente. Pero el tono no es solo de denuncia: el núcleo es el anuncio gozoso del Evangelio de la vida y la llamada a construir una cultura de la vida, desde la familia, la educación y la política. Imprescindible para formarse en bioética católica.","authorBio":"Karol Wojtyła (1920–2005), filósofo y arzobispo de Cracovia, fue papa con el nombre de Juan Pablo II de 1978 a 2005. Fue canonizado en 2014.","year":1995,"language":"latín","pages":190,"tags":["defensa de la vida","bioética","cultura de la vida","juan pablo ii","encíclica","magisterio"],"cover":"covers/evangelium-vitae.jpg","ratio":1.506,"color":"#194d27"},{"id":"redemptoris-mater","shelf":163,"theme":"Magisterio de la Iglesia","title":"Redemptoris Mater","author":"Juan Pablo II","sortKey":"Juan Pablo II","note":"Carta encíclica","summary":"Encíclica de san Juan Pablo II sobre la Bienaventurada Virgen María en la vida de la Iglesia peregrina, escrita como preparación al Año Mariano de 1987–1988. Siguiendo el capítulo octavo de Lumen gentium, el papa contempla a María en el misterio de Cristo, presenta su fe como peregrinación y la muestra como Madre en medio de la Iglesia y como mediación materna subordinada a la de Cristo. Destaca la dimensión mariana de la vida del discípulo, que acoge a María en su casa como el apóstol Juan. Una lectura preciosa para profundizar con rigor en la devoción mariana, tan central en Schoenstatt.","authorBio":"Karol Wojtyła (1920–2005), filósofo y arzobispo de Cracovia, fue papa con el nombre de Juan Pablo II de 1978 a 2005. Fue canonizado en 2014.","year":1987,"language":"latín","pages":110,"tags":["virgen maría","mariología","juan pablo ii","encíclica","iglesia","magisterio"],"cover":"covers/redemptoris-mater.jpg","ratio":1.661,"color":"#437bd3"},{"id":"familiaris-consortio","shelf":164,"theme":"Magisterio de la Iglesia","title":"Familiaris consortio","author":"Juan Pablo II","sortKey":"Juan Pablo II","note":"Exhortación apostólica","summary":"Exhortación apostólica de san Juan Pablo II tras el Sínodo de los Obispos de 1980 sobre la familia. Presenta el designio de Dios sobre el matrimonio y la familia, a la que llama «comunidad de vida y amor», y le confía cuatro grandes tareas: formar una comunidad de personas, servir a la vida, participar en el desarrollo de la sociedad y en la vida y misión de la Iglesia. Reafirma la enseñanza de Humanae vitae y anima a los esposos a conocer y vivir los métodos naturales. Es la carta magna de la pastoral familiar y una referencia práctica para todo matrimonio cristiano.","authorBio":"Karol Wojtyła (1920–2005), filósofo y arzobispo de Cracovia, fue papa con el nombre de Juan Pablo II de 1978 a 2005. Fue canonizado en 2014.","year":1981,"language":"latín","pages":180,"tags":["familia","matrimonio","pastoral familiar","juan pablo ii","paternidad responsable","magisterio"],"cover":"covers/familiaris-consortio.jpg","ratio":1.639,"color":"#e2c886"},{"id":"mulieris-dignitatem","shelf":165,"theme":"Magisterio de la Iglesia","title":"Mulieris dignitatem","author":"Juan Pablo II","sortKey":"Juan Pablo II","note":"Carta apostólica","summary":"Carta apostólica de san Juan Pablo II sobre la dignidad y la vocación de la mujer, publicada en el Año Mariano de 1988. Partiendo del relato de la creación del hombre y la mujer a imagen de Dios y de la figura de María, el papa reflexiona sobre la igualdad y complementariedad de ambos, sobre la maternidad y la virginidad como caminos de entrega, y sobre el modo en que Jesús trató a las mujeres en el Evangelio. Acuña la expresión del «genio femenino» y subraya que la mujer tiene una vocación singular a acoger y custodiar al ser humano. Un texto hermoso y luminoso.","authorBio":"Karol Wojtyła (1920–2005), filósofo y arzobispo de Cracovia, fue papa con el nombre de Juan Pablo II de 1978 a 2005. Fue canonizado en 2014.","year":1988,"language":"latín","pages":120,"tags":["dignidad de la mujer","genio femenino","virgen maría","antropología cristiana","juan pablo ii","magisterio"],"cover":"covers/mulieris-dignitatem.jpg","ratio":1.645,"color":"#e692b2"},{"id":"sollicitudo-rei-socialis","shelf":166,"theme":"Magisterio de la Iglesia","title":"Sollicitudo rei socialis","author":"Juan Pablo II","sortKey":"Juan Pablo II","note":"Carta encíclica","summary":"Encíclica social de san Juan Pablo II escrita con motivo del vigésimo aniversario de Populorum progressio de Pablo VI. Analiza el panorama mundial de finales de los años ochenta: la división entre bloques, la brecha entre Norte y Sur y el subdesarrollo de tantos pueblos. Sostiene que el verdadero desarrollo no es solo económico sino integral, moral y espiritual, introduce el concepto de «estructuras de pecado» y propone la solidaridad como virtud cristiana y la opción preferencial por los pobres. Una pieza clave de la doctrina social de la Iglesia, sorprendentemente actual.","authorBio":"Karol Wojtyła (1920–2005), filósofo y arzobispo de Cracovia, fue papa con el nombre de Juan Pablo II de 1978 a 2005. Fue canonizado en 2014.","year":1987,"language":"latín","pages":120,"tags":["doctrina social de la iglesia","desarrollo","solidaridad","pobreza","juan pablo ii","encíclica"],"cover":"covers/sollicitudo-rei-socialis.jpg","ratio":1.623,"color":"#8d4271"},{"id":"magnifica-humanitas","shelf":167,"theme":"Magisterio de la Iglesia","title":"Magnifica humanitas","author":"León XIV","sortKey":"León XIV","note":"Carta encíclica","summary":"Primera encíclica de León XIV, dedicada a la custodia de la persona humana en la era de la inteligencia artificial. El papa la firmó el 15 de mayo de 2026, aniversario de la Rerum novarum de León XIII, y la presentó él mismo en el Vaticano el 25 de mayo. Afirma que la inteligencia artificial no es moralmente neutral y pide responsabilidades claras a quienes la diseñan, programan y usan, con límites éticos que respeten la dignidad y la sacralidad de la vida. Examina sus efectos en la educación, el trabajo, la economía, la democracia, los jóvenes y la guerra. Una lectura necesaria para pensar con fe los grandes cambios de nuestro tiempo.","authorBio":"Robert Francis Prevost (Chicago, 1955), religioso agustino, misionero y obispo en Perú y prefecto del Dicasterio para los Obispos, fue elegido papa en mayo de 2025 con el nombre de León XIV.","year":2026,"language":"latín","pages":190,"tags":["inteligencia artificial","dignidad humana","doctrina social de la iglesia","león xiv","encíclica","tecnología"],"cover":"covers/magnifica-humanitas.jpg","ratio":1.667,"color":"#cebbab"},{"id":"dilexit-nos","shelf":168,"theme":"Magisterio de la Iglesia","title":"Dilexit nos","author":"Papa Francisco","sortKey":"Francisco","note":"Carta encíclica","summary":"Cuarta encíclica del papa Francisco, dedicada al amor humano y divino del Corazón de Jesucristo, publicada en el marco del 350 aniversario de las apariciones a santa Margarita María Alacoque. En un mundo que corre el riesgo de perder el corazón, el papa invita a volver a él como centro de la persona y lugar del encuentro con Dios. Recorre la Escritura, los Padres y los santos, como san Francisco de Sales, santa Teresa del Niño Jesús o san Carlos de Foucauld, y muestra que la devoción al Sagrado Corazón impulsa también la reparación y el amor a los hermanos. Cálida, sencilla y muy nutritiva para la oración.","authorBio":"Jorge Mario Bergoglio (1936–2025), jesuita argentino y arzobispo de Buenos Aires, fue papa con el nombre de Francisco de 2013 a 2025.","year":2024,"language":"latín","pages":150,"tags":["sagrado corazón","amor de dios","espiritualidad","papa francisco","encíclica","magisterio"],"ratio":1.5,"color":"#8d8449"},{"id":"caritas-in-veritate","shelf":169,"theme":"Magisterio de la Iglesia","title":"Caritas in veritate","author":"Benedicto XVI","sortKey":"Benedicto XVI","note":"Carta encíclica","summary":"Encíclica social de Benedicto XVI sobre el desarrollo humano integral en la caridad y en la verdad, publicada en plena crisis financiera de 2008–2009. Retoma Populorum progressio y afirma que la caridad sin verdad se vuelve sentimentalismo, mientras que la verdad ilumina el amor y lo hace creíble. Aborda la globalización, la ética en la economía y la empresa, la lógica del don y la gratuidad, la cuestión ecológica, la técnica y la necesidad de una autoridad política mundial al servicio del bien común. Una reflexión exigente y lúcida, imprescindible para quien quiera pensar la economía desde la fe.","authorBio":"Joseph Ratzinger (1927–2022), teólogo alemán y prefecto de la Congregación para la Doctrina de la Fe, fue papa con el nombre de Benedicto XVI de 2005 a 2013.","year":2009,"language":"latín","pages":160,"tags":["doctrina social de la iglesia","desarrollo humano integral","economía","caridad","benedicto xvi","encíclica"],"cover":"covers/caritas-in-veritate.jpg","ratio":1.634,"color":"#d1573b"},{"id":"la-alegria-de-ser-familia","shelf":170,"theme":"Schoenstatt","title":"La alegría de ser familia","author":"Hna. Gertrud-Maria Erhard (ed.)","sortKey":"Erhard","summary":"Libro editado por la hermana Gertrud-Maria Erhard, Hermana de María de Schoenstatt con larga experiencia en la pastoral familiar. Por lo que se puede saber, recoge textos y reflexiones, en buena parte inspirados en el padre José Kentenich, sobre la vida familiar vivida desde la fe: la alegría de estar juntos, el amor entre los esposos, la educación de los hijos y la presencia de Dios en lo cotidiano. Con un enfoque práctico y esperanzado, invita a descubrir el hogar como pequeño santuario donde se aprende a amar. Una lectura amable para matrimonios y familias que desean crecer juntos.","authorBio":"Hermana de María de Schoenstatt dedicada durante años al acompañamiento de familias; ha editado obras de espiritualidad familiar en la línea del padre Kentenich.","language":"alemán","tags":["schoenstatt","vida familiar","matrimonio","educación de los hijos","santuario hogar","padre kentenich"],"ratio":1.5,"color":"#59a6a6"},{"id":"tormentas-de-otono-1912","shelf":171,"theme":"Schoenstatt","title":"Tormentas de otoño 1912","author":"Dorothea M. Schlickmann","sortKey":"Schlickmann","summary":"Estudio histórico de la hermana Dorothea M. Schlickmann sobre los meses decisivos del otoño de 1912 en el seminario palotino de Schoenstatt, en Vallendar. Ante el malestar y la rebeldía de los alumnos contra un régimen disciplinario rígido, se nombró director espiritual a un joven sacerdote, José Kentenich, que se ganó su confianza con una propuesta nueva: educarse a sí mismos, bajo la protección de María, como personalidades firmes y libres. De ese clima nació el Acta de Prefundación del 27 de octubre de 1912. Con rigor documental, el libro ayuda a comprender las raíces pedagógicas de Schoenstatt.","authorBio":"Hermana de María de Schoenstatt e historiadora, especialista en los orígenes del Movimiento y autora de una extensa biografía del padre Kentenich.","language":"alemán","tags":["schoenstatt","historia de schoenstatt","padre kentenich","acta de prefundación","pedagogía","1912"],"ratio":1.5,"color":"#348d88"},{"id":"la-educacion-en-un-cambio-de-epoca","shelf":172,"theme":"Schoenstatt","title":"La educación en un cambio de época","author":"P. José Kentenich","sortKey":"Kentenich","summary":"Obra dedicada al pensamiento pedagógico del padre José Kentenich, que se entendió a sí mismo ante todo como educador. Kentenich percibió con lucidez que el mundo vivía un cambio de época y que la educación basada solo en normas externas ya no bastaba. Propone formar personalidades libres, interiormente firmes y vinculadas a Dios, a las personas y a los lugares, mediante una pedagogía del ideal, de la confianza, de las vinculaciones y del movimiento. María aparece como la gran educadora. Muy útil para padres, profesores y formadores que buscan educar con hondura en tiempos de incertidumbre.","authorBio":"Sacerdote alemán (1885–1968), fundador del Movimiento Apostólico de Schoenstatt en 1914; sobrevivió al campo de concentración de Dachau y pasó catorce años de exilio en Milwaukee (EE. UU.). Su causa de beatificación está abierta.","language":"alemán","tags":["schoenstatt","padre kentenich","pedagogía","educación","pedagogía de vinculaciones","formación"],"ratio":1.5,"color":"#6baeac"},{"id":"dios-mi-padre","shelf":173,"theme":"Schoenstatt","title":"Dios, mi Padre","author":"P. José Kentenich","sortKey":"Kentenich","summary":"Selección de textos del padre José Kentenich centrados en Dios como Padre, uno de los ejes de su espiritualidad. Kentenich insistió en que el hombre moderno, desarraigado y huérfano, necesita redescubrir el amor personal y misericordioso del Padre, que guía cada vida con su Providencia. Los textos invitan a vivir como hijos: con confianza, con sencillez, abandonándose en sus manos y aprendiendo a leer en los acontecimientos diarios los deseos de Dios. Un libro para orar y meditar despacio, especialmente adecuado en momentos de inquietud o de búsqueda.","authorBio":"Sacerdote alemán (1885–1968), fundador del Movimiento Apostólico de Schoenstatt en 1914; sobrevivió al campo de concentración de Dachau y pasó catorce años de exilio en Milwaukee (EE. UU.). Su causa de beatificación está abierta.","language":"alemán","tags":["schoenstatt","padre kentenich","dios padre","filialidad","divina providencia","oración"],"ratio":1.5,"color":"#396a5a"},{"id":"lunes-por-la-tarde-3","shelf":174,"theme":"Schoenstatt","title":"Lunes por la tarde… 3","author":"P. José Kentenich","sortKey":"Kentenich","summary":"Tercer volumen de la serie que recoge las charlas que el padre José Kentenich dirigía los lunes por la tarde a un grupo de matrimonios de origen alemán en Milwaukee (Estados Unidos), durante su exilio entre 1955 y 1964. En un clima familiar y con abundantes ejemplos de la vida cotidiana, Kentenich explica cómo vivir la Alianza de Amor con María en el matrimonio, cómo educar a los hijos y cómo santificar el trabajo y las preocupaciones diarias. No hemos podido confirmar el tema concreto de este tomo; como el resto de la serie, ofrece una espiritualidad práctica y cercana para las familias.","authorBio":"Sacerdote alemán (1885–1968), fundador del Movimiento Apostólico de Schoenstatt en 1914; sobrevivió al campo de concentración de Dachau y pasó catorce años de exilio en Milwaukee (EE. UU.). Su causa de beatificación está abierta.","originalTitle":"Am Montagabend…","language":"alemán","tags":["schoenstatt","padre kentenich","milwaukee","matrimonio","vida familiar","alianza de amor"],"ratio":1.5,"color":"#44ab8e"},{"id":"lunes-por-la-tarde-4","shelf":175,"theme":"Schoenstatt","title":"Lunes por la tarde… 4","author":"P. José Kentenich","sortKey":"Kentenich","summary":"Cuarto volumen de las charlas de los lunes por la tarde del padre José Kentenich a matrimonios de Milwaukee, pronunciadas durante su exilio en Estados Unidos entre 1955 y 1964. Como en los demás tomos, Kentenich comenta temas de fe y de vida práctica con un estilo coloquial y paternal: el amor conyugal, la vida de oración en el hogar, la confianza en la Providencia y la educación de los hijos en un mundo cambiante. No hemos podido identificar el subtítulo de este tomo. Es una lectura muy adecuada para grupos de matrimonios y para la oración en pareja.","authorBio":"Sacerdote alemán (1885–1968), fundador del Movimiento Apostólico de Schoenstatt en 1914; sobrevivió al campo de concentración de Dachau y pasó catorce años de exilio en Milwaukee (EE. UU.). Su causa de beatificación está abierta.","originalTitle":"Am Montagabend…","language":"alemán","tags":["schoenstatt","padre kentenich","milwaukee","matrimonio","vida familiar","oración en familia"],"ratio":1.5,"color":"#4b817d"},{"id":"lunes-por-la-tarde-5","shelf":176,"theme":"Schoenstatt","title":"Lunes por la tarde… 5","author":"P. José Kentenich","sortKey":"Kentenich","summary":"Quinto tomo de las charlas del padre José Kentenich a los matrimonios de Milwaukee, con el subtítulo «Creer en el amor misericordioso del Padre Dios». El tema central es la confianza filial: Kentenich anima a las familias a descubrir que Dios es un Padre que nos ama no a pesar de nuestras debilidades, sino precisamente en ellas, y que su misericordia es el fundamento de toda la vida cristiana. Con ejemplos sencillos de la vida familiar, enseña a abandonarse en Dios y a transmitir esa confianza a los hijos. Un volumen especialmente consolador, ideal para leer en pareja.","authorBio":"Sacerdote alemán (1885–1968), fundador del Movimiento Apostólico de Schoenstatt en 1914; sobrevivió al campo de concentración de Dachau y pasó catorce años de exilio en Milwaukee (EE. UU.). Su causa de beatificación está abierta.","originalTitle":"Am Montagabend…","language":"alemán","tags":["schoenstatt","padre kentenich","milwaukee","misericordia","dios padre","matrimonio"],"ratio":1.5,"color":"#2a8489"},{"id":"lunes-por-la-tarde-20","shelf":177,"theme":"Schoenstatt","title":"Lunes por la tarde… 20","author":"P. José Kentenich","sortKey":"Kentenich","summary":"Vigésimo tomo de las charlas del padre José Kentenich a matrimonios en Milwaukee, titulado «El amor conyugal, camino a la santidad». Es uno de los volúmenes más leídos de la serie. Kentenich presenta el matrimonio como verdadero camino de santificación: el amor entre los esposos, también en su expresión corporal, es reflejo y cauce del amor de Dios, y debe crecer, purificarse y madurar a lo largo de los años. Habla con realismo de las crisis, del paso del amor ideal al amor real y de la importancia de la entrega mutua. Muy recomendable para matrimonios de cualquier edad.","authorBio":"Sacerdote alemán (1885–1968), fundador del Movimiento Apostólico de Schoenstatt en 1914; sobrevivió al campo de concentración de Dachau y pasó catorce años de exilio en Milwaukee (EE. UU.). Su causa de beatificación está abierta.","originalTitle":"Am Montagabend…","language":"alemán","tags":["schoenstatt","padre kentenich","amor conyugal","santidad","matrimonio","milwaukee"],"ratio":1.5,"color":"#3b6359"},{"id":"lunes-por-la-tarde-29","shelf":178,"theme":"Schoenstatt","title":"Lunes por la tarde… 29","author":"P. José Kentenich","sortKey":"Kentenich","summary":"Tomo vigésimo noveno de la serie que recoge las charlas de los lunes por la tarde del padre José Kentenich a matrimonios de Milwaukee, entre 1955 y 1964. Pertenece a la parte final de la colección, correspondiente a los últimos años de su exilio, cuando ya se vislumbraba su regreso a Schoenstatt tras el Concilio. No hemos podido confirmar su tema específico. Como los demás volúmenes, combina comentarios de la liturgia y del año litúrgico con orientaciones prácticas para vivir la fe en el matrimonio y en la familia, siempre en clima de cercanía y de confianza.","authorBio":"Sacerdote alemán (1885–1968), fundador del Movimiento Apostólico de Schoenstatt en 1914; sobrevivió al campo de concentración de Dachau y pasó catorce años de exilio en Milwaukee (EE. UU.). Su causa de beatificación está abierta.","originalTitle":"Am Montagabend…","language":"alemán","tags":["schoenstatt","padre kentenich","milwaukee","matrimonio","vida familiar","año litúrgico"],"ratio":1.5,"color":"#2d8c8f"},{"id":"lunes-por-la-tarde-30","shelf":179,"theme":"Schoenstatt","title":"Lunes por la tarde… 30","author":"P. José Kentenich","sortKey":"Kentenich","summary":"Trigésimo tomo de las charlas del padre José Kentenich a las familias de Milwaukee, uno de los volúmenes finales de esta larga serie. Recoge encuentros de sus últimos años en Estados Unidos, antes de su rehabilitación y regreso a Alemania en 1965. No hemos podido identificar el tema concreto del tomo. En conjunto, estas charlas muestran a un Kentenich paternal que acompaña a los matrimonios en su crecimiento humano y espiritual, les ayuda a mirar su vida a la luz de la fe y les anima a construir familias firmes, unidas y abiertas a Dios.","authorBio":"Sacerdote alemán (1885–1968), fundador del Movimiento Apostólico de Schoenstatt en 1914; sobrevivió al campo de concentración de Dachau y pasó catorce años de exilio en Milwaukee (EE. UU.). Su causa de beatificación está abierta.","originalTitle":"Am Montagabend…","language":"alemán","tags":["schoenstatt","padre kentenich","milwaukee","matrimonio","vida familiar","fe"],"ratio":1.5,"color":"#67a899"},{"id":"la-santidad-de-la-vida-diaria","shelf":180,"theme":"Schoenstatt","title":"La santidad de la vida diaria","author":"Herbert King","sortKey":"King","note":"José Kentenich: una presentación de su pensamiento en textos, 6","summary":"Sexto tomo de la colección «José Kentenich: una presentación de su pensamiento en textos», preparada por el padre Herbert King. Reúne y ordena textos del fundador de Schoenstatt sobre la santidad de la vida diaria, una de sus aportaciones más características: la santidad no consiste en hacer cosas extraordinarias, sino en vivir lo ordinario con amor, en unión con Dios, en el trabajo, la familia y las pequeñas obligaciones de cada día. Los textos están introducidos y comentados, lo que facilita su comprensión. Una excelente puerta de entrada al pensamiento de Kentenich para leer y meditar.","authorBio":"Sacerdote del Instituto de los Padres de Schoenstatt, teólogo y psicólogo, gran estudioso de la obra del padre Kentenich, de la que ha publicado numerosas antologías comentadas.","language":"alemán","tags":["schoenstatt","padre kentenich","santidad de la vida diaria","espiritualidad laical","trabajo","textos escogidos"],"ratio":1.5,"color":"#66b789"},{"id":"los-anos-ocultos-padre-jose-kentenich-infancia-y-juventud-18","shelf":181,"theme":"Schoenstatt","title":"Los años ocultos. Padre José Kentenich: infancia y juventud (1885–1910)","author":"Dorothea M. Schlickmann","sortKey":"Schlickmann","summary":"Primera parte de la gran biografía del padre José Kentenich escrita por la hermana Dorothea M. Schlickmann a partir de una investigación documental exhaustiva. Narra su nacimiento en Gymnich en 1885 como hijo natural, la entrega de su madre, que lo consagró a la Virgen al dejarlo en un orfanato, sus años de formación con los palotinos y las profundas crisis interiores que atravesó hasta su ordenación sacerdotal en 1910. Muestra cómo Dios fue preparando, en lo escondido, al futuro fundador. Un libro conmovedor y riguroso para conocer las raíces humanas de Schoenstatt.","authorBio":"Hermana de María de Schoenstatt e historiadora, especialista en los orígenes del Movimiento y autora de una extensa biografía del padre Kentenich.","year":1995,"originalTitle":"Die verborgenen Jahre. Pater Josef Kentenich: Kindheit und Jugend (1885–1910)","language":"alemán","tags":["schoenstatt","padre kentenich","biografía","infancia","historia de schoenstatt","vocación"],"ratio":1.5,"color":"#4fab78"},{"id":"julio-steinkaul-un-heroe-de-la-primavera-sagrada","shelf":182,"theme":"Schoenstatt","title":"Julio Steinkaul. Un héroe de la «Primavera Sagrada»","author":"José Klein","sortKey":"Klein","note":"Dos ejemplares","summary":"Biografía de Julio Steinkaul (1921–1943), joven de Witten (Alemania) que con trece años entró en el seminario menor junto al Santuario de Schoenstatt e hizo suyo el ideal de la «Primavera Sagrada» (Ver Sacrum): una juventud entregada por entero a Dios por manos de María. Su lema era ser jefe sirviendo a los demás. En 1939 selló su entrega con un Poder en Blanco a la Virgen, ofreciendo su vida por santos sacerdotes. Murió en el frente ruso, cerca de Orel, en 1943, herido mientras acudía a socorrer a un compañero. Un testimonio luminoso para jóvenes y educadores.","authorBio":"Autor de esta biografía publicada por Editorial Patris en 1992; no hemos encontrado más datos biográficos sobre él.","language":"alemán","tags":["schoenstatt","héroes de schoenstatt","primavera sagrada","juventud","biografía","segunda guerra mundial"],"ratio":1.5,"color":"#6fb8a5"},{"id":"adelante","shelf":183,"theme":"Schoenstatt","title":"Adelante","author":"P. José Kentenich","sortKey":"Kentenich","note":"Fundación Instituto de Familias","summary":"Publicación de la Fundación Instituto de Familias con textos del padre José Kentenich. El Instituto de Familias fue fundado por el propio Kentenich en el campo de concentración de Dachau, el 16 de julio de 1942, como comunidad de matrimonios consagrados dentro de Schoenstatt. Por el título y la procedencia, cabe pensar que el libro reúne palabras de aliento del fundador para avanzar con confianza en la vida familiar y en la misión, pero no hemos podido confirmar su contenido exacto. Un libro de cabecera para quienes viven la espiritualidad de Schoenstatt en familia.","authorBio":"Sacerdote alemán (1885–1968), fundador del Movimiento Apostólico de Schoenstatt en 1914; sobrevivió al campo de concentración de Dachau y pasó catorce años de exilio en Milwaukee (EE. UU.). Su causa de beatificación está abierta.","language":"alemán","tags":["schoenstatt","padre kentenich","instituto de familias","matrimonio","vida familiar","misión"],"ratio":1.5,"color":"#439d70"},{"id":"adelante-2","shelf":184,"theme":"Schoenstatt","title":"¡Adelante!","author":"Autor desconocido","sortKey":"~","note":"Autor por confirmar","summary":"Libro del ámbito de Schoenstatt cuyo autor no hemos podido identificar con certeza; quizá esté relacionado con el ejemplar del mismo título publicado por la Fundación Instituto de Familias con textos del padre Kentenich, o sea otra edición de él. El título, «¡Adelante!», evoca la actitud tan característica del fundador de mirar el futuro con confianza en la Providencia y no detenerse ante las dificultades. Conviene revisar la portadilla para confirmar autor, editorial y año. Mientras tanto, queda en la biblioteca como lectura de ánimo y esperanza para el camino cristiano.","authorBio":"Autor por confirmar.","language":"español","tags":["schoenstatt","padre kentenich","confianza","esperanza","vida cristiana"],"ratio":1.5,"color":"#39c0b3"},{"id":"pedagogia-mariana-el-estilo-pedagogico-kentenijiano","shelf":185,"theme":"Schoenstatt","title":"Pedagogía mariana. El estilo pedagógico kentenijiano","author":"P. Rafael Fernández de A.","sortKey":"Fernández de Andraca","summary":"Obra del padre Rafael Fernández de Andraca dentro de una serie dedicada al estilo pedagógico del padre José Kentenich. Este volumen se centra en la dimensión mariana de esa pedagogía: María no es solo objeto de devoción, sino la gran educadora que forma a Cristo en cada persona y modelo del hombre nuevo. El autor explica cómo la Alianza de Amor con ella sostiene un camino educativo basado en la libertad, la confianza y las vinculaciones personales. Un libro claro y muy útil para educadores, padres y responsables de grupos que quieran educar con estilo de Schoenstatt.","authorBio":"Sacerdote chileno de los Padres de Schoenstatt, teólogo y uno de los principales divulgadores del pensamiento del padre Kentenich en lengua española, con numerosos libros publicados por Nueva Patris.","language":"español","tags":["schoenstatt","pedagogía","virgen maría","padre kentenich","educación","alianza de amor"],"ratio":1.5,"color":"#327755"},{"id":"eres-el-alma-de-mi-alma","shelf":186,"theme":"Schoenstatt","title":"Eres el alma de mi alma","author":"P. Patricio Moore Infante","sortKey":"Moore","summary":"Meditaciones del padre Patricio Moore sobre la oración al Espíritu Santo que el padre José Kentenich compuso en el campo de concentración de Dachau y que comienza con las palabras del título. Verso a verso, el autor desgrana la oración y la convierte en escuela de vida interior: el Espíritu Santo como alma del alma, fuente de luz, fortaleza y alegría, que actúa unido a María. Es un libro sencillo y profundo, pensado para rezar más que para estudiar, que ha conocido numerosas ediciones. Ideal para retiros, para Pentecostés o para la oración personal diaria.","authorBio":"Sacerdote chileno de los Padres de Schoenstatt, autor de varios libros de espiritualidad y meditación inspirados en el padre Kentenich.","language":"español","tags":["schoenstatt","espíritu santo","oración","hacia el padre","padre kentenich","meditación"],"ratio":1.5,"color":"#4bbeb8"},{"id":"el-dios-de-la-vida-huellas-religiosas-en-los-procesos-psiqui","shelf":187,"theme":"Schoenstatt","title":"El Dios de la vida. Huellas religiosas en los procesos psíquicos","author":"Heriberto King","sortKey":"King","summary":"Ensayo del padre Herbert (Heriberto) King, teólogo y psicólogo, que explora la relación entre la vida psíquica y la experiencia religiosa desde la perspectiva del padre Kentenich. Muestra cómo Dios se hace presente en los procesos humanos ordinarios, en los afectos, las vinculaciones, las heridas y los anhelos, y cómo la fe sana, integra y madura la personalidad. Frente a una religiosidad desencarnada, propone un Dios de la vida que actúa en la historia personal de cada uno. Una lectura exigente pero enriquecedora para quien se interesa por la psicología y la espiritualidad.","authorBio":"Sacerdote del Instituto de los Padres de Schoenstatt, teólogo y psicólogo, gran estudioso de la obra del padre Kentenich, de la que ha publicado numerosas antologías comentadas.","language":"alemán","tags":["schoenstatt","psicología","espiritualidad","padre kentenich","experiencia religiosa","vinculaciones"],"ratio":1.5,"color":"#49c5a0"},{"id":"me-amas-una-mirada-sobre-la-castidad-matrimonial","shelf":188,"theme":"Schoenstatt","title":"¿Me amas? Una mirada sobre la castidad matrimonial","author":"P. Carlos Padilla Esteban","sortKey":"Padilla","summary":"Libro del padre Carlos Padilla, sacerdote de Schoenstatt en España, sobre la castidad vivida dentro del matrimonio. Lejos de entenderla como represión, la presenta como la virtud que hace posible un amor verdadero, que no utiliza al otro sino que lo acoge y lo respeta como persona. Habla del deseo, de la ternura, de la entrega mutua, de los tiempos de espera y de abstinencia, y de cómo integrar cuerpo y alma en una unión abierta a la vida y a Dios. La pregunta de Jesús a Pedro, «¿me amas?», da el tono: un amor que se renueva cada día.","authorBio":"Sacerdote de los Padres de Schoenstatt en Madrid, escritor y predicador muy leído; publica con regularidad libros de espiritualidad y comentarios al Evangelio.","language":"español","tags":["schoenstatt","castidad","matrimonio","amor conyugal","sexualidad","afectividad"],"ratio":1.5,"color":"#59c7c9"},{"id":"beber-de-la-fuente-de-vida-reflexiones-sobre-los-evangelios-","shelf":189,"theme":"Schoenstatt","title":"Beber de la fuente de vida. Reflexiones sobre los Evangelios dominicales","author":"P. Carlos Padilla Esteban","sortKey":"Padilla","summary":"Recopilación de comentarios del padre Carlos Padilla a los Evangelios de los domingos, fruto de su predicación semanal. Cada reflexión parte del texto del día y lo aterriza en la vida concreta: los miedos, las heridas, las relaciones familiares, el deseo de Dios y la necesidad de confiar. Con un estilo cercano, lleno de imágenes y testimonios, ayuda a preparar la misa dominical y a orar con la Palabra durante la semana. Es un libro para tener a mano y leer poco a poco, domingo a domingo, como quien vuelve a la fuente para beber.","authorBio":"Sacerdote de los Padres de Schoenstatt en Madrid, escritor y predicador muy leído; publica con regularidad libros de espiritualidad y comentarios al Evangelio.","language":"español","tags":["evangelio","año litúrgico","homilías","oración","palabra de dios","schoenstatt"],"ratio":1.5,"color":"#56c299"},{"id":"heroes-de-fuego-ardieron-hasta-consumirse","shelf":190,"theme":"Schoenstatt","title":"Héroes de fuego. Ardieron hasta consumirse","author":"P. Jonathan Niehaus","sortKey":"Niehaus","summary":"El padre Jonathan Niehaus presenta seis figuras de Schoenstatt cuyas causas de canonización están abiertas: José Engling, Gertraud von Bullion, Karl Leisner, Emilie Engel, Mario Hiriart y João Luiz Pozzobon. Son vidas muy distintas, un soldado de la Primera Guerra Mundial, una aristócrata enfermera, un sacerdote ordenado en Dachau, una religiosa, un ingeniero chileno y un diácono brasileño que recorrió miles de kilómetros con la Virgen Peregrina, pero todos ardieron de amor a Dios por medio de María. Un libro ágil e inspirador, ideal para jóvenes y para conocer la santidad que nace del Santuario.","authorBio":"Sacerdote estadounidense de los Padres de Schoenstatt (1960–2012), historiador del Movimiento y autor de numerosas obras divulgativas sobre su historia y sus héroes.","language":"inglés","tags":["schoenstatt","héroes de schoenstatt","santidad","biografías","josé engling","juventud"],"ratio":1.5,"color":"#73b595"},{"id":"el-padre-kentenich","shelf":191,"theme":"Schoenstatt","title":"El Padre Kentenich","author":"Autor desconocido","sortKey":"~","note":"Autor por confirmar","summary":"Libro sobre la figura del padre José Kentenich, fundador del Movimiento Apostólico de Schoenstatt, cuyo autor no hemos podido determinar. Por el título, se trata probablemente de una semblanza o biografía breve que recorre su vida: su infancia en Gymnich, la fundación de Schoenstatt en 1914, su prisión en Dachau, el largo exilio en Milwaukee y su regreso tras el Concilio, hasta su muerte en 1968. Conviene comprobar en la portada el autor y la editorial. Aun así, es una buena forma de acercarse a la personalidad de un fundador apasionado por María y por el hombre nuevo.","authorBio":"Autor por confirmar.","language":"español","tags":["schoenstatt","padre kentenich","biografía","fundador","historia de schoenstatt"],"ratio":1.5,"color":"#539796"},{"id":"jose-kentenich","shelf":192,"theme":"Schoenstatt","title":"José Kentenich","author":"Eduardo T. Gil de Muro","sortKey":"Gil de Muro","summary":"Biografía del padre José Kentenich escrita por Eduardo T. Gil de Muro, un experimentado biógrafo con oficio periodístico, publicada también con el subtítulo «Historia de un hombre libre». Con estilo narrativo y ameno, recorre la vida del fundador de Schoenstatt: una infancia marcada por la ausencia del padre, su vocación palotina, la fundación del Movimiento, la resistencia al nazismo y los años en Dachau, el exilio en Estados Unidos y su rehabilitación final. El hilo conductor es la libertad interior de un hombre que se fió por entero de Dios y de María. Muy adecuada como primera biografía.","authorBio":"Escritor y periodista español, autor de numerosas biografías de santos y figuras de la Iglesia escritas con estilo divulgativo y narrativo.","language":"español","tags":["schoenstatt","padre kentenich","biografía","libertad","dachau","fundador"],"ratio":1.5,"color":"#328680"},{"id":"el-31-de-mayo-una-mision-para-nuestro-tiempo","shelf":193,"theme":"Schoenstatt","title":"El 31 de mayo. Una misión para nuestro tiempo","author":"P. Rafael Fernández de A.","sortKey":"Fernández de Andraca","summary":"El padre Rafael Fernández explica el significado del 31 de mayo de 1949, el llamado tercer hito de la historia de Schoenstatt. Ese día, en el Santuario de Bellavista (Chile), el padre Kentenich firmó una carta en la que diagnosticaba la enfermedad de fondo de la cultura moderna, el pensamiento mecanicista que separa lo natural de lo sobrenatural, y proponía como remedio un pensar, vivir y amar orgánicos. El autor muestra la actualidad de esa misión para la Iglesia y para la familia de hoy. Una lectura clave para entender la misión de Schoenstatt y su relación con Chile.","authorBio":"Sacerdote chileno de los Padres de Schoenstatt, teólogo y uno de los principales divulgadores del pensamiento del padre Kentenich en lengua española, con numerosos libros publicados por Nueva Patris.","language":"español","tags":["schoenstatt","31 de mayo","pensamiento orgánico","padre kentenich","bellavista","historia de schoenstatt"],"ratio":1.5,"color":"#62a39e"},{"id":"el-verdadero-amor","shelf":194,"theme":"Schoenstatt","title":"El verdadero amor","author":"P. José Kentenich","sortKey":"Kentenich","summary":"Textos del padre José Kentenich sobre el amor auténtico, tema que atraviesa toda su obra. Para el fundador de Schoenstatt, el ser humano está hecho para amar y ser amado, y el amor verdadero une el corazón con la voluntad, sabe purificarse y madurar, y se abre a Dios como su fuente. Las páginas tratan del amor entre los esposos, del paso del amor idealizado al amor real, de la entrega y de la fidelidad, siempre con María como modelo. No hemos podido confirmar la edición concreta, pero su temática lo hace muy recomendable para novios y matrimonios.","authorBio":"Sacerdote alemán (1885–1968), fundador del Movimiento Apostólico de Schoenstatt en 1914; sobrevivió al campo de concentración de Dachau y pasó catorce años de exilio en Milwaukee (EE. UU.). Su causa de beatificación está abierta.","language":"alemán","tags":["schoenstatt","padre kentenich","amor","matrimonio","noviazgo","afectividad"],"ratio":1.5,"color":"#4f8771"},{"id":"la-renovacion-de-la-iglesia-textos-escogidos","shelf":195,"theme":"Schoenstatt","title":"La renovación de la Iglesia. Textos escogidos","author":"P. José Kentenich","sortKey":"Kentenich","note":"Dos ejemplares","summary":"Antología de textos del padre José Kentenich sobre la Iglesia y su renovación, publicada por la editorial Patris. Kentenich vivió intensamente el Concilio Vaticano II, que coincidió con el final de su exilio, y habló de la Iglesia de las nuevas playas: una Iglesia más fraterna, más paternal, interiormente libre, profundamente mariana y capaz de dialogar con el mundo moderno sin perder su identidad. Los textos muestran su amor y fidelidad a la Iglesia aun en tiempos de prueba. Una lectura muy actual para quien se pregunta cómo renovar la Iglesia desde dentro.","authorBio":"Sacerdote alemán (1885–1968), fundador del Movimiento Apostólico de Schoenstatt en 1914; sobrevivió al campo de concentración de Dachau y pasó catorce años de exilio en Milwaukee (EE. UU.). Su causa de beatificación está abierta.","language":"alemán","tags":["schoenstatt","padre kentenich","iglesia","concilio vaticano ii","renovación","textos escogidos"],"ratio":1.5,"color":"#328f8c"},{"id":"la-familia-de-nazareth","shelf":196,"theme":"Schoenstatt","title":"La familia de Nazareth","author":"Míriam de Manuel San José","sortKey":"Manuel","note":"Dos ejemplares","summary":"Libro de Míriam de Manuel San José sobre la Sagrada Familia de Nazaret como modelo para las familias de hoy, del que apenas hemos encontrado información. Por su temática y su lugar en la biblioteca, cabe esperar una reflexión cercana sobre la vida oculta de Jesús, María y José: el trabajo, la oración, la obediencia a Dios, la ternura y las dificultades compartidas. Schoenstatt ve en Nazaret la escuela del santuario hogar. Recomendamos comprobar en el propio libro la editorial y el año. Es una lectura sencilla para inspirar la vida cotidiana en familia.","authorBio":"Autora española relacionada con el ámbito de Schoenstatt; no hemos encontrado datos biográficos contrastados.","language":"español","tags":["sagrada familia","nazaret","vida familiar","san josé","virgen maría","schoenstatt"],"ratio":1.5,"color":"#569572"},{"id":"el-dia-que-cambie-mi-vida","shelf":197,"theme":"Fe y espiritualidad","title":"El día que cambié mi vida","author":"Francisco Fernández-Carvajal","sortKey":"Fernández-Carvajal","summary":"Libro de Francisco Fernández-Carvajal, el conocido autor de «Hablar con Dios», publicado por Ediciones Palabra. Como sugiere el título, gira en torno a la conversión: ese momento, a veces discreto y a veces radical, en que una persona se encuentra de verdad con Cristo y su vida toma un rumbo nuevo. Con el estilo claro y piadoso que caracteriza al autor, invita al lector a no conformarse con una fe rutinaria y a dejarse transformar por Dios. No hemos podido confirmar el detalle de su contenido. Una lectura breve y estimulante para la vida espiritual.","authorBio":"Sacerdote español de la Prelatura del Opus Dei, autor de libros de espiritualidad muy difundidos, sobre todo la colección de meditaciones «Hablar con Dios», traducida a numerosos idiomas.","language":"español","tags":["conversión","vida espiritual","encuentro con cristo","testimonios","fe"],"cover":"covers/el-dia-que-cambie-mi-vida.jpg","ratio":1.602,"color":"#202746"},{"id":"bajo-la-proteccion-de-maria","shelf":198,"theme":"Schoenstatt","title":"Bajo la protección de María","author":"P. José Kentenich","sortKey":"Kentenich","summary":"Textos del padre José Kentenich sobre María y su papel en la educación y la vida cristiana. El título recoge unas palabras de su famosa charla de octubre de 1912 a los seminaristas de Schoenstatt, cuando les propuso aprender a educarse a sí mismos bajo la protección de María para llegar a ser personalidades firmes, libres y apostólicas. Esa intuición sigue siendo el corazón de la espiritualidad de Schoenstatt: una Alianza de Amor con la Virgen que nos transforma y nos educa. No hemos podido verificar la edición concreta. Un libro para cultivar una devoción mariana madura y confiada.","authorBio":"Sacerdote alemán (1885–1968), fundador del Movimiento Apostólico de Schoenstatt en 1914; sobrevivió al campo de concentración de Dachau y pasó catorce años de exilio en Milwaukee (EE. UU.). Su causa de beatificación está abierta.","language":"alemán","tags":["schoenstatt","virgen maría","padre kentenich","autoeducación","alianza de amor","pedagogía"],"ratio":1.5,"color":"#288176"},{"id":"mision-personal","shelf":199,"theme":"Schoenstatt","title":"Misión personal","author":"María Gorostiaga","sortKey":"Gorostiaga","summary":"Libro de María Gorostiaga del que no hemos encontrado información contrastada. Por su título y su relación con Schoenstatt, previsiblemente trata del ideal personal, una de las enseñanzas más originales del padre Kentenich: Dios tiene un pensamiento único sobre cada persona, una misión que solo ella puede cumplir, y descubrirla da unidad, alegría y sentido a toda la vida. Sería, por tanto, una invitación a buscar ese ideal en la oración y en la propia historia. Recomendamos confirmar en el libro su contenido y editorial. Útil para jóvenes y adultos en discernimiento.","authorBio":"Autora vinculada a Schoenstatt; no hemos encontrado datos biográficos contrastados.","language":"español","tags":["schoenstatt","ideal personal","vocación","misión","discernimiento"],"ratio":1.5,"color":"#70b2a7"},{"id":"la-historia-del-p-kentenich","shelf":200,"theme":"Schoenstatt","title":"La historia del P. Kentenich","author":"P. Hernán Alessandri M.","sortKey":"Alessandri","summary":"Biografía del padre José Kentenich escrita por el padre Hernán Alessandri, que se apoya en buena medida en los textos autobiográficos del propio fundador. Recorre su vida desde la infancia hasta su muerte en 1968: la consagración a María de niño, las crisis de juventud, la fundación de Schoenstatt, la persecución nazi y Dachau, la visitación eclesiástica y el exilio en Milwaukee, y su regreso tras el Concilio. Alessandri, que lo conoció personalmente, ofrece una lectura teológica de esa historia como camino de Dios. Una biografía fiable y accesible para conocer al fundador.","authorBio":"Sacerdote chileno de los Padres de Schoenstatt (1935–2007), teólogo y uno de los grandes intérpretes del pensamiento del padre Kentenich, al que conoció personalmente.","language":"español","tags":["schoenstatt","padre kentenich","biografía","historia de schoenstatt","exilio","fundador"],"ratio":1.5,"color":"#518a7d"}];
